function result = test_C6_BSPLINE_PHASE9CR8F102K_D0_VECTOR_BUGFIX_VALIDATION()
% =========================================================================
% Phase 9C-R8-F80: MATLAB EXPRESSION-LEVEL FINAL AUDIT
%
% RUN:
%   Press the MATLAB Run button.  No input argument is required.
%
% IMPORTANT:
%   - The exact F9 782-case DEFINITIONS are reconstructed only to preserve
%     Case-ID -> condition mapping.
%   - QP/certificate diagnostics are executed ONLY for the 190 F9 rejects.
%   - No F9 planning/safety threshold is changed.
%   - Avoidance-room quantities are diagnostics, NOT impossibility proofs.
% =========================================================================
clc;
scenario=setup_benchmark();
[cfg0,limits0,obs0,~,~,~]=unpack_scenario(scenario);
opt=setup_options(); alpha=1/sqrt(3);
opt.coherent_lambda=1.25; opt.coherent_flip_cos=-0.15;
opt.coherent_topK=min(48,opt.separator_grid_N);
opt.compat_enable=true; opt.compat_min_dot=0.05; opt.compat_lambda=1.00;
opt.geom_guide_enable=true; opt.geom_guide_lambda=0.85;
opt.geom_guide_min_dot=0.35; opt.quality_enable=false;
opt.authority_tol=1e-10; opt.authority_lambda=0.15;

SUPPORT=[1 1.15 1.35 1.65 2 2.4]; MAX_CUTS=12; TMISSION=72;
FAM={'STRAIGHT','CIRCLE','HELIX','S_CURVE','CLIMB_TURN'};
SYS=[.70 .70 .70 .70;1 1 1 1;1.30 1 1 1;1 1.30 1 1;1 1 1.50 1;1 1 1 1.35;1.25 1.25 1.25 1.25;1.50 1.30 1.50 1.40];
SYSNAME={'SMALL_ALL','BASE','BIG_PAYLOAD','BIG_UAV','THICK_CABLE','LONG_CABLE','BIG_ALL','XL_MIXED'};
OG=[.70 1 1 1 0 0 0;1 1 1 1 35 15 -20;1.20 1.50 .70 1 70 -25 30;1.30 .65 1.60 .85 115 35 -40;1.10 .75 .80 1.70 155 -35 55;1.35 1.70 .60 .70 205 20 65];
OGNAME={'SMALL_SPHEROID','BASE_ROTATED','LONG_X','LONG_Y','TALL_Z','FLAT_LONG'};

% Exact F9 case generator (A-J), unchanged.
C=repmat(f9_case_template(),1,0); id=0;
% A) exact established 48-case baseline.
for is=1:8, for io=1:6
 id=id+1; q=f9_case_template(); q.id=id; q.group='A_BASE48'; q.sys=SYS(is,:); q.sys_name=SYSNAME{is}; q.og=OG(io,:); q.obs_name=OGNAME{io};
 q.family=FAM{mod(id-1,5)+1}; sfv=[.75 1 1.25]; q.sf=sfv(mod(floor((id-1)/5),3)+1); C(end+1)=q;
end,end
% B) trajectory speed/family sweep.  Includes more aggressive speeds than F8.
SPEED=[.55 .70 .85 1.00 1.20 1.40 1.60 1.85];
for f=1:numel(FAM), for s=1:numel(SPEED)
 id=id+1; q=f9_case_template(); q.id=id; q.group='B_SPEED'; q.family=FAM{f}; q.sf=SPEED(s); q.og=OG(2,:); q.obs_name='BASE_ROTATED'; C(end+1)=q;
end,end
% C) one-factor system geometry sweeps.
LEV=[.60 .75 .90 1.00 1.15 1.30 1.50 1.75]; PN={'R_PAYLOAD','R_UAV','R_CABLE','L_CABLE'};
for p=1:4, for l=1:numel(LEV)
 id=id+1; q=f9_case_template(); q.id=id; q.group=['C_' PN{p}]; q.sys(p)=LEV(l); q.sys_name=sprintf('%s_x%.2f',PN{p},LEV(l)); q.family='CLIMB_TURN'; q.sf=1.10; q.og=OG(2,:); q.obs_name='BASE_ROTATED'; C(end+1)=q;
end,end
% D) dynamic-limit sweeps: individual + joint scaling.
DLEV=[.55 .70 .85 1.00 1.20 1.40]; DNAME={'VMAX','AMAX','JMAX'};
for p=1:4, for l=1:numel(DLEV)
 id=id+1; q=f9_case_template(); q.id=id; q.group='D_DYNAMICS';
 if p<=3, q.limit_scale(p)=DLEV(l); q.limit_name=sprintf('%s_x%.2f',DNAME{p},DLEV(l)); else, q.limit_scale(:)=DLEV(l); q.limit_name=sprintf('ALLLIM_x%.2f',DLEV(l)); end
 q.family='HELIX'; q.sf=1.25; q.og=OG(3,:); q.obs_name='LONG_X'; C(end+1)=q;
end,end
% E) safety-margin sweep.
MLEV=[.50 .75 1.00 1.25 1.50 1.75 2.00 2.50];
for l=1:numel(MLEV)
 id=id+1; q=f9_case_template(); q.id=id; q.group='E_MARGIN'; q.margin_scale=MLEV(l); q.family='S_CURVE'; q.sf=1.15; q.og=OG(4,:); q.obs_name='LONG_Y'; C(end+1)=q;
end
% F) sensor-trigger/replanning-start sweep across families and obstacles.
TPLAN=[8 12 16 20 24 28 32];
for f=1:numel(FAM), for io=1:6, for tt=1:numel(TPLAN)
 id=id+1; q=f9_case_template(); q.id=id; q.group='F_DETECTION'; q.family=FAM{f}; q.sf=1.15; q.og=OG(io,:); q.obs_name=OGNAME{io}; q.tplan=TPLAN(tt); C(end+1)=q;
end,end,end
% G) obstacle size/anisotropy/rotation stress.  p9cf_make_obstacles interprets og.
OS=[.65 .80 1.00 1.20 1.40 1.65]; AN=[.65 1.00 1.45]; ROT=[0 35 80 130 175 220];
for s=1:numel(OS), for a=1:numel(AN), for rr=1:numel(ROT)
 id=id+1; q=f9_case_template(); q.id=id; q.group='G_OBSTACLE'; q.family='CLIMB_TURN'; q.sf=1.10;
 q.og=[OS(s), AN(a), 1/AN(a), 1, ROT(rr), 0.35*ROT(rr), -0.25*ROT(rr)]; q.obs_name=sprintf('OBS_s%.2f_a%.2f_r%d',OS(s),AN(a),ROT(rr)); C(end+1)=q;
end,end,end
% H) deterministic pairwise mixed stress (not random, reproducible).
for k=1:120
 id=id+1; q=f9_case_template(); q.id=id; q.group='H_PAIRWISE';
 q.family=FAM{mod(2*k-1,5)+1}; q.sf=SPEED(mod(3*k-1,numel(SPEED))+1); q.tplan=TPLAN(mod(5*k-1,numel(TPLAN))+1);
 q.sys=[LEV(mod(k-1,8)+1),LEV(mod(3*k-1,8)+1),LEV(mod(5*k-1,8)+1),LEV(mod(7*k-1,8)+1)];
 q.limit_scale=[DLEV(mod(2*k-1,6)+1),DLEV(mod(3*k-1,6)+1),DLEV(mod(5*k-1,6)+1)]; q.margin_scale=MLEV(mod(7*k-1,8)+1);
 io=mod(11*k-1,6)+1; q.og=OG(io,:); q.obs_name=OGNAME{io}; q.sys_name='PAIRWISE'; q.limit_name='PAIRWISE'; C(end+1)=q;
end
% I) compound corners: intentionally hard combinations, useful for boundary/failure modes.
CORNER_SPEED=[1.40 1.60 1.85]; CORNER_TPLAN=[20 24 28 32]; CORNER_MARGIN=[1.25 1.50 1.75];
for k=1:48
 id=id+1; q=f9_case_template(); q.id=id; q.group='I_CORNERS'; q.family=FAM{mod(k-1,5)+1};
 q.sf=CORNER_SPEED(mod(k-1,3)+1); q.tplan=CORNER_TPLAN(mod(k-1,4)+1);
 q.sys=[1.30 1.30 1.50 1.35].*([1 1 1 1]+0.12*mod(k-1,2)); q.limit_scale=[.70 .70 .70]; q.margin_scale=CORNER_MARGIN(mod(k-1,3)+1);
 io=mod(k-1,6)+1; q.og=OG(io,:); q.og(1)=q.og(1)*1.25; q.obs_name=['HARD_' OGNAME{io}]; q.sys_name='HARD_SYSTEM'; q.limit_name='TIGHT_LIMITS'; C(end+1)=q;
end
% J) explicit simultaneous multi-obstacle stress.
%    Existing A-I cases already contain the frozen two-obstacle construction.
%    J varies obstacle COUNT and 3-D LAYOUT explicitly while keeping the same
%    ellipsoidal/support-function obstacle model used by the certificate.
NOBS=[2 3 5 8]; LAYOUT={'SERIAL','ALTERNATING','NARROW_3D','CLUSTERED'};
JSPEED=[.85 1.15 1.45]; JTPLAN=[12 20 28];
for nn=1:numel(NOBS), for ll=1:numel(LAYOUT), for ss=1:numel(JSPEED), for tt=1:numel(JTPLAN)
 id=id+1; q=f9_case_template(); q.id=id; q.group='J_MULTI_OBS';
 q.family=FAM{mod(id-1,numel(FAM))+1}; q.sf=JSPEED(ss); q.tplan=JTPLAN(tt);
 q.n_obs=NOBS(nn); q.obs_layout=LAYOUT{ll};
 io=mod(nn+2*ll+ss+tt-4,6)+1; q.og=OG(io,:);
 q.obs_name=sprintf('MULTI_%02d_%s_%s',q.n_obs,q.obs_layout,OGNAME{io});
 % Include moderate system variation without mixing in the extreme-corner suite.
 q.sys=SYS(mod(nn+ll+ss+tt-4,size(SYS,1))+1,:); q.sys_name='MULTI_SYSTEM';
 C(end+1)=q;
end,end,end,end



if numel(C)~=782 || C(1).id~=1 || C(end).id~=782
    error('F12 case-generator audit failed: expected exact F9 IDs 1..782.');
end

% -------------------------------------------------------------------------
% F34 F32 BASELINE + FAST-QP ISOLATION TEST
%
% Purpose:
%   Replace the two largest SEARCH costs found in F31:
%     1) long sampled risk-window scan,
%     2) broad all-pair corridor front-end.
%
% What is NOT changed:
%   - exact C6 boundary construction (r=0..6)
%   - rotated anisotropic ellipsoid support
%   - suspended UAV+cable+load directional geometry
%   - v/a/j hard constraints
%   - box authority (no safety relaxation)
%   - unchanged continuous-time global certificate
%
% Online semantics:
%   Obstacles are unknown before t_detect.  At t_detect, the sensor supplies
%   the ellipsoid set; replanning starts from Dstart at that instant.
%
% This V1 front-end uses a cheap current-state geometric threat estimate only
% to choose T and active pairs.  It is NOT a safety proof.  Safety remains
% exclusively gated by the unchanged global certificate.
%
% No CSV, no figures, no dense sphere scan.
% -------------------------------------------------------------------------

CASE_ID=[18 96 113 137 73];
FAMS={'STRAIGHT','CIRCLE','HELIX','S_CURVE','CLIMB_TURN'};
SPEED=[0.65 0.85 1.00 1.20 1.40];
NOBS_SET=[1 2 3 5];
TP_SET=[10 14 18 22 26];
SCALE_SET=[0.70 0.90 1.10 1.30];
SHAPES=[1.15 .95 1.25;1.55 .70 1.00;.70 1.50 .85;.80 .80 1.65];
alpha=1/sqrt(3);

% At most two duration attempts.  The second is a feasibility fallback, not
% a relaxation of any safety/dynamics condition.
T_SCALE=[1.00 1.35];

f101aa_silent_fprintf('================================================================================\n');
f101aa_silent_fprintf(' F68 OFFLINE/ONLINE STRUCTURAL DECOMPOSITION -- THEORY FIRST, TOTAL 2-3MS TARGET\n');
f101aa_silent_fprintf(' cases             : %d\n',numel(CASE_ID));
f101aa_silent_fprintf(' online semantics  : obstacle revealed only at t_detect\n');
f101aa_silent_fprintf(' T attempts         : at most %d\n',numel(T_SCALE));
f101aa_silent_fprintf(' safety gate        : unchanged continuous-time global certificate\n');
f101aa_silent_fprintf(' geometry           : rotated ellipsoid + directional suspended system\n');
f101aa_silent_fprintf(' C6 / v-a-j         : unchanged hard requirements\n');
f101aa_silent_fprintf('================================================================================\n');

R=repmat(f32_empty(),1,numel(CASE_ID));
X=repmat(f51_empty(),1,0);
tALL=tic;

% F51 philosophy:
%   One run explores several suspected bottlenecks.  Baseline acceptance
%   remains the validated F50 path.  Exploratory branches are diagnostic only.
%   We intentionally postpone exhaustive safety/generalization regression
%   until a 2--3 ms-class architecture becomes plausible.


% F39 FIX1: reference from the first evaluated candidate.
% Local variables are sufficient because all comparisons occur in this run.
F39_DN_REF=[];
F39_DB_REF=[];
F39_T_REF=[];

% F40 offline-template emulation. The first evaluated D determines only the
% normalized row-direction grouping. Subsequent cases reuse this grouping.
F40_KEY_REF=[];
F40_KEEP_REF=[];

for ii=1:numel(CASE_ID)
    id=CASE_ID(ii);
    fam=FAMS{1+mod(id-1,numel(FAMS))};
    sf=SPEED(1+mod(floor((id-1)/numel(FAMS)),numel(SPEED)));
    no=NOBS_SET(1+mod(floor((id-1)/25),numel(NOBS_SET)));
    tdetect=TP_SET(1+mod(floor((id-1)/100),numel(TP_SET)));

    cfg=cfg0;limits=limits0;
    nom_fun=@(t)p9a_nominal(t,fam,sf);
    Dstart=nom_fun(tdetect);

    % Sensor measurement becomes available NOW.
    obs=f32_detected_ellipsoids(obs0,nom_fun,cfg,id,no,tdetect,...
        SCALE_SET,SHAPES,TMISSION);

    rr=f32_empty();rr.id=id;rr.family=fam;rr.sf=sf;rr.nobs=no;rr.tdetect=tdetect;

    % ---------------------------------------------------------------------
    % FAST horizon seed: current state + detected ellipsoid geometry only.
    % This is a candidate selector, never the proof.
    % ---------------------------------------------------------------------
    tt=tic;
    [T0,threat]=f32_fast_horizon(Dstart,obs,cfg,limits);
    rr.front_ms=1000*toc(tt);rr.T0=T0;
    N=max(30,min(42,ceil(2*T0)));if mod(N,2),N=N+1;end
    rr.N=N;

    tw=tic;
    for it=1:numel(T_SCALE)
        T=T_SCALE(it)*T0;
        if T<=0 || tdetect+T>TMISSION,continue;end
        rr.attempts=rr.attempts+1;
        Dend=nom_fun(tdetect+T);
        cfgN=cfg;cfgN.N_ctrl=N;

        tt=tic;
        c=build_static_cache_boundary(cfgN,tdetect,tdetect+T,nom_fun,Dstart,Dend,opt);
        cache_this_ms=1000*toc(tt); rr.cache_ms=rr.cache_ms+cache_this_ms;
        tt67=tic; c67=f67_build_lean_cache_boundary(cfgN,tdetect,tdetect+T,nom_fun,Dstart,Dend,opt);
        f67_lean_cache_ms=1000*toc(tt67); f67_cache_err=f67_cache_equivalence(c,c67);

        [c6s0,c6e0]=f32_c6(c.Pbase,c,Dstart,Dend);
        if c6s0>opt.c6_tol || c6e0>opt.c6_tol
            rr.reason='BOUNDARY_CONSTRUCTION_ERROR';continue;
        end

        tt=tic;
        md=f43_build_dyn_E_template(c); [Dmat,dvec]=dyn_E(md,limits,alpha);
        dyn_this_ms=1000*toc(tt); rr.dynamics_ms=rr.dynamics_ms+dyn_this_ms;

        % F44: preserve the original F32/F43 active-obstacle selection and
        % corridor construction. Only the corridor call is profiled.
        tt=tic;
        active=f32_active_obstacles(c,obs,threat,cfg,opt);
        rr.active_max=max(rr.active_max,numel(active));
        obsA=obs(active);
        active_this_ms=1000*toc(tt); rr.active_ms=rr.active_ms+active_this_ms;

        % F54 PRESELECTION: choose local z columns BEFORE constructing G.
        % Uses only B-spline affine support already in cache + detected
        % obstacle geometry.  No corridor rows and no solved candidate.
        [preCols,preScore,pre_ms]=f54_preselect_columns(c,obs,cfgN,opt,threat);

        % F55 structured selector: no G, no optimization result.
        % Find collision-relevant base-trajectory spans geometrically, then
        % retain COMPLETE 3-D free-control-point blocks whose B-spline local
        % support intersects a +/- window around those spans.
        [blkCols,blkMeta,blk_ms]=f55_structured_blocks(c,obs,cfgN,opt,threat);

        % F57 analytic directional-authority selector.
        % IMPORTANT: this is computed BEFORE G exists and uses only:
        %   B_{s,l}=B0_{s,l}+M_{s,l} z,
        % detected ellipsoid centers/shapes, and algebraic separator directions.
        % It is candidate generation only, never the safety proof.
        [authCols,authScore,authMeta,auth_ms]=f57_directional_authority_selector(c,obs,cfgN,opt,threat);

        % F58 urgency-weighted streaming selector.
        % No stored full G is used. Rows are generated/evaluated one at a
        % time from the same batch separator ingredients; only a 1 x nz
        % score vector is accumulated. The weighting comes directly from
        % box authority:
        %   required_i=max(0,-b_i),
        %   authority_i=zmax*||a_i||_1,
        %   eta_i=required_i/authority_i.
        [urgCols,urgScore,urgMeta,urg_ms]=f58_streaming_urgency_selector(c,cfgN,obsA,opt);

        % F59: select a SET of DOFs by residual box-authority coverage.
        % Candidate-generation only; no safety decision is made here.
        [setCols,setMeta,set_ms]=f59_greedy_set_selector(c,cfgN,obsA,opt);

        % F61 signed critical-row consensus selector.
        % Selects both a DOF and a temporary preferred sign by greedily
        % reducing signed surrogate-row violation. The sign is ONLY for
        % subspace selection; the final z is solved by the usual LP.
        [sigCols,sigPref,sigMeta,sig_ms]=f61_signed_consensus_selector(c,cfgN,obsA,opt);

        % F50 production baseline retained for diagnostic cross-check.
        tt=tic;
        [G,g,info,f62stream]=f62_build_coherent_guided_corridor_batch(c,cfgN,obsA,opt);
        corridor_this_ms=1000*toc(tt); rr.corridor_ms=rr.corridor_ms+corridor_this_ms;

        Gbuilt=info.authority_screen_pass && ~isempty(G);
        if ~Gbuilt
            rr.n_screen=rr.n_screen+1; rr.reason='AUTHORITY_SCREEN_REJECT';
            continue;
        end
        rr.G_constructed=true;

        % QP formulation and final continuous-time certificate remain unchanged.
        Aall=[G;Dmat]; ball=[g;dvec];

        % -------------------------------------------------------------
        % F51 broad exploration: several hypotheses in ONE run.
        % None of these branches controls baseline acceptance.
        % -------------------------------------------------------------
        xx=f51_empty();
        xx.case_id=id; xx.attempt=it; xx.nobs=numel(obsA);
        xx.nz=c.nz; xx.nG=size(G,1); xx.nD=size(Dmat,1); xx.nAll=size(Aall,1);
        xx.pre_ms=pre_ms; xx.pre_cols=preCols; xx.pre_score=preScore;
        xx.nPre=numel(preCols);
        xx.blk_ms=blk_ms; xx.blk_center=blkMeta.center_span;
        xx.blk_guard_n=blkMeta.guard_n;
        xx.f57_select_ms=auth_ms; xx.f57_cols=authCols;
        xx.f57_score=authScore; xx.f57_meta=authMeta;
        xx.f58_select_ms=urg_ms; xx.f58_cols=urgCols;
        xx.f58_score=urgScore; xx.f58_meta=urgMeta;
        xx.f59_select_ms=set_ms; xx.f59_cols=setCols; xx.f59_meta=setMeta;
        xx.f61_select_ms=sig_ms; xx.f61_cols=sigCols;
        xx.f61_sign=sigPref; xx.f61_meta=sigMeta;
        xx.f62_stream=f62stream;

        % (A) Dynamic-row exact normalized-direction compression.
        [Dc,dc,keepD,tComp]=f51_compress_D(Dmat,dvec);
        xx.nDc=size(Dc,1); xx.Dcompress_ms=tComp;
        xx.Dratio=xx.nDc/max(1,xx.nD);

        % F54: 18/24/30 variables chosen BEFORE G existed.
        % For this exploration we restrict the already validated G/D rows to
        % those columns to test whether the preselection itself is sufficient.
        % The next implementation step, only if this succeeds, is to avoid
        % constructing the unused columns/rows at all.
        budgetsPre=[18 24 30];
        for ib=1:3
            kk=min(budgetsPre(ib),numel(preCols));
            if kk==0, continue; end
            cols=preCols(1:kk);
            xx.pre_n(ib)=kk;
            [rh,zs,tm]=f53_margin_lp_subset([G;Dc],[g;dc],c,opt,cols);
            xx.pre_solve_ms(ib)=tm; xx.pre_rho(ib)=rh;
            if ~isempty(zs)
                xx.pre_fullviol(ib)=max(Aall*zs-ball);
                Ppre=apply_z(c,zs);
                cp=certify_candidate_global(Ppre,c,cfgN,limits,obs,opt);
                xx.pre_cert(ib)=cp.pass; xx.pre_g(ib)=cp.min_g_lower;
            end
        end

        % F55 structured span windows: +/-1, +/-2, +/-3, +/-4 spans.
        for iw=1:4
            cols=blkCols{iw}; xx.blk_n(iw)=numel(cols);
            if isempty(cols), continue; end
            [rh,zs,tm]=f53_margin_lp_subset([G;Dc],[g;dc],c,opt,cols);
            xx.blk_solve_ms(iw)=tm; xx.blk_rho(iw)=rh;
            if ~isempty(zs)
                xx.blk_fullviol(iw)=max(Aall*zs-ball);
                Pb=apply_z(c,zs);
                cb=certify_candidate_global(Pb,c,cfgN,limits,obs,opt);
                xx.blk_cert(iw)=cb.pass; xx.blk_g(iw)=cb.min_g_lower;
                [esb,eeb]=f32_c6(Pb,c,Dstart,Dend);
                xx.blk_c6(iw)=max(esb,eeb);
            end
        end

        % (B) Solve the SAME near-zero-objective IP on compressed D.
        [xx.ipc_ok,xx.zipc,xx.ipc_ms]=f51_ip(c,[G;Dc],[g;dc],opt);
        if xx.ipc_ok
            xx.ipc_fullviol=max([Aall*xx.zipc-ball; ...
                -opt.box_z_max*ones(c.nz,1)-xx.zipc; ...
                xx.zipc-opt.box_z_max*ones(c.nz,1)]);
            Pc=apply_z(c,xx.zipc);
            cc=certify_candidate_global(Pc,c,cfgN,limits,obs,opt);
            xx.ipc_cert=cc.pass; xx.ipc_g=cc.min_g_lower;
        end

        % (C) Max normalized common margin on compressed rows.
        [xx.rho,xx.zmm,xx.mm_ms]=f51_margin_lp_fast([G;Dc],[g;dc],c,opt);
        if ~isempty(xx.zmm)
            xx.mm_fullviol=max(Aall*xx.zmm-ball);
            Pm=apply_z(c,xx.zmm);
            cm=certify_candidate_global(Pm,c,cfgN,limits,obs,opt);
            xx.mm_cert=cm.pass; xx.mm_g=cm.min_g_lower;
        end

        % (D) Correct max-margin activity:
        % normalized slack minus achieved rho.
        if ~isempty(xx.zmm)
            Ac=[G;Dc]; bc=[g;dc];
            rs=max(vecnorm(Ac,2,2),1e-12);
            slackN=(bc-Ac*xx.zmm)./rs;
            gap=slackN-xx.rho;
            xx.near1e6=nnz(gap<=1e-6);
            xx.near1e4=nnz(gap<=1e-4);
            xx.near1e2=nnz(gap<=1e-2);

            % (E) Reduced-row teacher experiments. Keep all G, but only
            % dynamic rows close to the teacher max-margin boundary.
            nG=size(G,1); gapD=gap(nG+1:end);
            for ih=1:3
                thr=[1e-4 1e-2 5e-2]; th=thr(ih);
                kd=find(gapD<=th);
                Ar=[G;Dc(kd,:)]; br=[g;dc(kd)];
                [rh,zr,tm]=f51_margin_lp_fast(Ar,br,c,opt);
                xx.red_n(ih)=size(Ar,1); xx.red_ms(ih)=tm; xx.red_rho(ih)=rh;
                if ~isempty(zr)
                    xx.red_fullviol(ih)=max(Aall*zr-ball);
                    Pr=apply_z(c,zr);
                    cr=certify_candidate_global(Pr,c,cfgN,limits,obs,opt);
                    xx.red_cert(ih)=cr.pass; xx.red_g(ih)=cr.min_g_lower;
                end
            end

            % (F) LOCAL-SUPPORT ARCHITECTURE EXPLORATION.
            % Use obstacle-corridor rows to identify which z-columns can
            % actually affect the collision-critical geometry. This does NOT
            % remove any obstacle from the final certificate.
            [xx.loc_cols,xx.loc_colscore]=f53_local_columns(G,c.nz);
            xx.nLocal=numel(xx.loc_cols);

            % Try three column budgets. Solve a max-margin LP only in those
            % variables, then lift back to full z and check ALL original rows
            % and ALL detected obstacles with the unchanged certificate.
            budgets=[12 24 36];
            for ib=1:3
                kk=min(budgets(ib),xx.nLocal);
                if kk==0, continue; end
                cols=xx.loc_cols(1:kk);
                [rh,zs,tm]=f53_margin_lp_subset(Ac,bc,c,opt,cols);
                xx.loc_n(ib)=kk; xx.loc_ms(ib)=tm; xx.loc_rho(ib)=rh;
                if ~isempty(zs)
                    xx.loc_fullviol(ib)=max(Aall*zs-ball);
                    Pl=apply_z(c,zs);
                    cl=certify_candidate_global(Pl,c,cfgN,limits,obs,opt);
                    xx.loc_cert(ib)=cl.pass; xx.loc_g(ib)=cl.min_g_lower;
                end
            end

            % (G) GUARD-SET diagnostic.
            % Candidate generation may focus on active obstacles, but every
            % detected obstacle whose ellipsoid can approach the reachable
            % control-point envelope is marked as a guard. Final certificate
            % remains against ALL detected obstacles regardless of this set.
            [xx.guard_n,xx.guard_ids,xx.guard_ms]=f53_guard_set(c,obs,cfgN,opt);

            % F56 FORENSIC: explain the successful F53 24-variable selector.
            % This is diagnostic only and does not affect acceptance.
            [xx.f56,xx.f56_ms]=f56_forensic24(c,G,g,Dmat,dvec,obs,cfgN,opt,info);

            % F57 compare analytic pre-G selector with successful teacher-24.
            budgets57=[18 24 30];
            teacher=xx.f56.cols;
            Gn=G./max(vecnorm(G,2,2),1e-12);
            Gtot=sum(Gn.^2,'all');
            [teacherFull,teacherScore]=f53_local_columns(G,c.nz);
            kk62=min(24,numel(teacherFull));
            teacher62=teacherFull(1:kk62);
            stream62=f62stream.cols(1:min(kk62,numel(f62stream.cols)));
            xx.f62_teacher_cols=teacher62;
            xx.f62_stream_cols=stream62;
            xx.f62_overlap=numel(intersect(teacher62,stream62));
            xx.f62_order_exact=isequal(teacher62(:),stream62(:));
            xx.f62_score_err=max(abs(teacherScore-f62stream.score));
            xx.f62_score_rel=xx.f62_score_err/max(1,max(abs(teacherScore)));
            if ~isempty(stream62)
                [rh62,z62,tm62]=f53_margin_lp_subset([G;Dc],[g;dc],c,opt,stream62);
                xx.f62_solve_ms=tm62; xx.f62_rho=rh62;
                if ~isempty(z62)
                    xx.f62_fullviol=max(Aall*z62-ball);
                    P62=apply_z(c,z62);
                    cc62=certify_candidate_global(P62,c,cfgN,limits,obs,opt);
                    xx.f62_cert=cc62.pass; xx.f62_g=cc62.min_g_lower;
                    [e62s,e62e]=f32_c6(P62,c,Dstart,Dend);
                    xx.f62_c6=max(e62s,e62e);
                end
            end

            % F63: production-path timing/fusion experiment.
            % Route A: reuse the already-built exact full G and slice 24 cols.
            % Route B: after exact streaming selects the same 24 cols, rebuild
            % ONLY those exact affine row columns from the final F49 normals.
            % Both routes must be numerically equivalent before timing matters.
            if ~isempty(stream62)
                t63=tic;
                G24A=G(:,stream62);
                Dc24A=Dc(:,stream62);
                xx.f63_slice_ms=1e3*toc(t63);

                t63=tic;
                [G24B,g24B]=f63_rebuild_selected_exact_rows(c,cfgN,obsA,opt,info,stream62);
                xx.f63_rebuild24_ms=1e3*toc(t63);

                xx.f63_G24_err=max(abs(G24A-G24B),[],'all');
                xx.f63_g_err=max(abs(g-g24B),[],'all');

                [rh63A,z63A,tm63A]=f63_margin_lp_reduced(G24A,g,Dc24A,dc,c,opt,stream62);
                [rh63B,z63B,tm63B]=f63_margin_lp_reduced(G24B,g24B,Dc24A,dc,c,opt,stream62);
                xx.f63_solve_slice_ms=tm63A; xx.f63_solve_rebuild_ms=tm63B;
                xx.f63_rho_slice=rh63A; xx.f63_rho_rebuild=rh63B;

                if ~isempty(z63A) && ~isempty(z63B)
                    xx.f63_z_err=max(abs(z63A-z63B));
                    t63=tic; P63=apply_z(c,z63B); xx.f63_apply_ms=1e3*toc(t63);
                    t63=tic; cc63=certify_candidate_global(P63,c,cfgN,limits,obs,opt);
                    xx.f63_cert_ms=1e3*toc(t63);
                    xx.f63_cert=cc63.pass; xx.f63_g=cc63.min_g_lower;
                    [e63s,e63e]=f32_c6(P63,c,Dstart,Dend);
                    xx.f63_c6=max(e63s,e63e);
                    xx.f63_fullviol=max(Aall*z63B-ball);
                end
                xx.f63_path_slice_ms=f62stream.score_ms+xx.f63_slice_ms+xx.f63_solve_slice_ms+xx.f63_apply_ms+xx.f63_cert_ms;
                xx.f63_path_rebuild_ms=f62stream.score_ms+xx.f63_rebuild24_ms+xx.f63_solve_rebuild_ms+xx.f63_apply_ms+xx.f63_cert_ms;

                % F64-A: reproduce F53/F62 LP exactly: normalize by FULL 66-column
                % row norm first, then restrict to the selected 24 columns.
                [rh64,z64,tm64]=f64_margin_lp_fullnorm(G,g,Dc,dc,c,opt,stream62);
                xx.f64_lp_ms=tm64; xx.f64_rho=rh64;
                xx.f64_rho_err=abs(rh64-rh62);
                if ~isempty(z64) && ~isempty(z62), xx.f64_z_err=max(abs(z64-z62)); end

                % F64-B: profile unchanged scalar theorem gate and compare with
                % an algebraically equivalent batched direction evaluation.
                [cs64,prof64]=f64_certify_profile(P63,c,cfgN,limits,obs,opt,false);
                [cb64,profb64]=f64_certify_profile(P63,c,cfgN,limits,obs,opt,true);
                xx.f64_scalar_cert_ms=prof64.total_ms; xx.f64_batch_cert_ms=profb64.total_ms;
                xx.f64_deriv_ms=profb64.deriv_ms; xx.f64_dirs_ms=profb64.dirs_ms;
                xx.f64_bezier_ms=profb64.bezier_ms; xx.f64_tension_ms=profb64.tension_ms;
                xx.f64_sep_ms=profb64.separator_ms;
                xx.f64_cert_match=(cs64.pass==cb64.pass);
                xx.f64_ming_err=abs(cs64.min_g_lower-cb64.min_g_lower);
                xx.f64_minM_err=abs(cs64.min_M_LB-cb64.min_M_LB);
                xx.f64_batch_cert=cb64.pass;

                % F65: precompute exact span->Bezier linear operators from the
                % B-spline mathematical structure only. Operator construction
                % is offline/setup work; online gate applies H0/H2 to P.
                t65=tic; OP65=f65_build_span_bezier_operators(c); xx.f65_build_ms=1e3*toc(t65);
                [eP65,eA65]=f65_audit_span_bezier_operator(P63,c,OP65);
                xx.f65_pos_err=eP65; xx.f65_acc_err=eA65;
                [cf65,pf65]=f65_certify_operator(P63,c,cfgN,limits,obs,opt,OP65);
                xx.f65_cert_ms=pf65.total_ms; xx.f65_bezier_ms=pf65.bezier_ms;
                xx.f65_deriv_ms=pf65.deriv_ms; xx.f65_dirs_ms=pf65.dirs_ms;
                xx.f65_tension_ms=pf65.tension_ms; xx.f65_sep_ms=pf65.separator_ms;
                xx.f65_cert_match=(cf65.pass==cb64.pass);
                xx.f65_ming_err=abs(cf65.min_g_lower-cb64.min_g_lower);
                xx.f65_minM_err=abs(cf65.min_M_LB-cb64.min_M_LB);
                xx.f65_cert=cf65.pass;

                % F66: end-to-end 2--3 ms budget audit. No acceptance semantics changed.
                % Measure unavoidable current-path pieces and MATLAB linprog fixed overhead.
                xx.f66_stream_ms=f62stream.score_ms;
                xx.f66_lp_ms=tm64;
                xx.f66_gate_ms=pf65.total_ms;
                xx.f66_current_path_ms=xx.f66_stream_ms+xx.f66_lp_ms+xx.f66_gate_ms;
                [xx.f66_lp_empty_ms,xx.f66_lp_tiny_ms]=f66_linprog_overhead_probe();
                xx.f66_nonlp_ms=xx.f66_stream_ms+xx.f66_gate_ms;
                xx.f66_required_lp_for3=max(0,3-xx.f66_nonlp_ms);
                xx.f66_required_lp_for2=max(0,2-xx.f66_nonlp_ms);
                xx.f66_possible3_current_nonlp=(xx.f66_nonlp_ms<3);
                xx.f66_possible2_current_nonlp=(xx.f66_nonlp_ms<2);
                xx.f67_cache_full_ms=cache_this_ms; xx.f67_cache_lean_ms=f67_lean_cache_ms; xx.f67_cache_err=f67_cache_err;
                xx.f67_dyn_ms=dyn_this_ms; xx.f67_active_ms=active_this_ms; xx.f67_corridor_full_ms=corridor_this_ms;
                xx.f67_corr_grid_ms=f62stream.grid_ms; xx.f67_corr_select_ms=f62stream.select_ms; xx.f67_corr_rows_ms=f62stream.score_ms;
                xx.f67_corr_other_ms=max(0,corridor_this_ms-f62stream.grid_ms-f62stream.select_ms-f62stream.score_ms);
                xx.f67_front_ms=rr.front_ms;
                xx.f67_prod_fullcache_ms=rr.front_ms+cache_this_ms+dyn_this_ms+active_this_ms+corridor_this_ms+tm64+pf65.total_ms;
                xx.f67_prod_leancache_ms=rr.front_ms+f67_lean_cache_ms+dyn_this_ms+active_this_ms+corridor_this_ms+tm64+pf65.total_ms;
                xx.f67_zeroLP_floor_ms=rr.front_ms+f67_lean_cache_ms+dyn_this_ms+active_this_ms+corridor_this_ms+pf65.total_ms;
                xx.f67_need_reduce_for3=max(0,xx.f67_prod_leancache_ms-3); xx.f67_need_reduce_for2=max(0,xx.f67_prod_leancache_ms-2);
            end
            for ib=1:3
                kk=min(budgets57(ib),numel(authCols));
                if kk==0, continue; end
                cols=authCols(1:kk);
                xx.f57_n(ib)=kk;
                xx.f57_overlap(ib)=numel(intersect(cols,teacher));
                xx.f57_Gcover(ib)=sum(Gn(:,cols).^2,'all')/max(Gtot,eps);
                [rh,zs,tm]=f53_margin_lp_subset([G;Dc],[g;dc],c,opt,cols);
                xx.f57_solve_ms(ib)=tm; xx.f57_rho(ib)=rh;
                if ~isempty(zs)
                    xx.f57_fullviol(ib)=max(Aall*zs-ball);
                    P57=apply_z(c,zs);
                    cc57=certify_candidate_global(P57,c,cfgN,limits,obs,opt);
                    xx.f57_cert(ib)=cc57.pass; xx.f57_g(ib)=cc57.min_g_lower;
                    [e57s,e57e]=f32_c6(P57,c,Dstart,Dend);
                    xx.f57_c6(ib)=max(e57s,e57e);
                end
            end
            budgets58=[18 24 30];
            for ib=1:3
                kk=min(budgets58(ib),numel(urgCols));
                if kk==0, continue; end
                cols=urgCols(1:kk);
                xx.f58_n(ib)=kk;
                xx.f58_overlap(ib)=numel(intersect(cols,teacher));
                xx.f58_Gcover(ib)=sum(Gn(:,cols).^2,'all')/max(Gtot,eps);
                [rh,zs,tm]=f53_margin_lp_subset([G;Dc],[g;dc],c,opt,cols);
                xx.f58_solve_ms(ib)=tm; xx.f58_rho(ib)=rh;
                if ~isempty(zs)
                    xx.f58_fullviol(ib)=max(Aall*zs-ball);
                    P58=apply_z(c,zs);
                    cc58=certify_candidate_global(P58,c,cfgN,limits,obs,opt);
                    xx.f58_cert(ib)=cc58.pass; xx.f58_g(ib)=cc58.min_g_lower;
                    [e58s,e58e]=f32_c6(P58,c,Dstart,Dend);
                    xx.f58_c6(ib)=max(e58s,e58e);
                end
            end
            budgets59=[18 24 30];
            for ib=1:3
                kk=min(budgets59(ib),numel(setCols));
                if kk==0, continue; end
                cols=setCols(1:kk);
                xx.f59_n(ib)=kk;
                xx.f59_overlap(ib)=numel(intersect(cols,teacher));
                xx.f59_Gcover(ib)=sum(Gn(:,cols).^2,'all')/max(Gtot,eps);
                [rh,zs,tm]=f53_margin_lp_subset([G;Dc],[g;dc],c,opt,cols);
                xx.f59_solve_ms(ib)=tm; xx.f59_rho(ib)=rh;
                if ~isempty(zs)
                    xx.f59_fullviol(ib)=max(Aall*zs-ball);
                    P59=apply_z(c,zs);
                    cc59=certify_candidate_global(P59,c,cfgN,limits,obs,opt);
                    xx.f59_cert(ib)=cc59.pass; xx.f59_g(ib)=cc59.min_g_lower;
                    [e59s,e59e]=f32_c6(P59,c,Dstart,Dend);
                    xx.f59_c6(ib)=max(e59s,e59e);
                end
            end
            budgets61=[18 24 30];
            for ib=1:3
                kk=min(budgets61(ib),numel(sigCols));
                if kk==0, continue; end
                cols=sigCols(1:kk);
                xx.f61_n(ib)=kk;
                xx.f61_overlap(ib)=numel(intersect(cols,teacher));
                xx.f61_Gcover(ib)=sum(Gn(:,cols).^2,'all')/max(Gtot,eps);
                xx.f61_signagree(ib)=f61_teacher_sign_agreement(sigCols(1:kk),sigPref(1:kk),teacher,G,g,Dc,dc,c,opt);
                [rh,zs,tm]=f53_margin_lp_subset([G;Dc],[g;dc],c,opt,cols);
                xx.f61_solve_ms(ib)=tm; xx.f61_rho(ib)=rh;
                if ~isempty(zs)
                    xx.f61_fullviol(ib)=max(Aall*zs-ball);
                    P61=apply_z(c,zs);
                    cc61=certify_candidate_global(P61,c,cfgN,limits,obs,opt);
                    xx.f61_cert(ib)=cc61.pass; xx.f61_g(ib)=cc61.min_g_lower;
                    [e61s,e61e]=f32_c6(P61,c,Dstart,Dend);
                    xx.f61_c6(ib)=max(e61s,e61e);
                end
            end
            % F60 signed feasible-subspace forensic comparison.
            % Compare exactly 24 columns from teacher/F57/F58/F59 on the
            % SAME full G + compressed D system. No acceptance decision.
            sets60=cell(1,4);
            sets60{1}=teacher(1:min(24,numel(teacher)));
            sets60{2}=authCols(1:min(24,numel(authCols)));
            sets60{3}=urgCols(1:min(24,numel(urgCols)));
            sets60{4}=setCols(1:min(24,numel(setCols)));
            names60={'TEACH','F57','F58','F59'};
            for iq=1:4
                xx.f60(iq)=f60_subspace_forensic(G,g,Dc,dc,c,opt,sets60{iq},names60{iq});
            end
        end
        X(end+1)=xx; %#ok<AGROW>

        aud=f39_dynamic_invariance(c,G,g,Dmat,dvec,opt);
        rr.qp_ms=rr.qp_ms+aud.ip_ms; rr.qp_calls=rr.qp_calls+1;
        if ~aud.ip_ok
            rr.reason='IP_GD_INFEASIBLE';continue;
        end
        rr.GD=true;

        Pip=apply_z(c,aud.zip);
        certIP=certify_candidate_global(Pip,c,cfgN,limits,obs,opt);
        cert=certIP; P=Pip;
        [c6s,c6e]=f32_c6(P,c,Dstart,Dend);
        rr.min_g=cert.min_g_lower;rr.c6s=c6s;rr.c6e=c6e;
        rr.v=cert.v_bound;rr.a=cert.a_bound;rr.j=cert.j_bound;
        if cert.pass && c6s<=opt.c6_tol && c6e<=opt.c6_tol
            rr.cert=true;rr.reason='IP_BASELINE_CERTIFIED';
            rr.T=T;rr.mult=T/T0;break;
        elseif ~cert.pass
            rr.reason='IP_BASELINE_CERT_REJECT';
        elseif c6s>opt.c6_tol
            rr.reason='START_C6_FAIL';
        else
            rr.reason='END_C6_FAIL';
        end
    end

    rr.wall_ms=1000*toc(tw);
    R(ii)=rr;
    f101aa_silent_fprintf('CASE %3d | %-10s sf=%.2f obs=%d active<=%d | %-30s | att=%d | front=%6.3f wall=%7.2f ms\n',...
        rr.id,rr.family,rr.sf,rr.nobs,rr.active_max,rr.reason,rr.attempts,rr.front_ms,rr.wall_ms);
    Xi=X([X.case_id]==id);
    if ~isempty(Xi)
        x=Xi(end);
        f101aa_silent_fprintf(['   EXP rows G/D/Dc=%d/%d/%d | Dcomp %.3fms | IPc %.3fms cert=%d g=%+.3g ',...
                 '| MM %.3fms rho=%.3g cert=%d g=%+.3g | activeGap(1e-6/1e-4/1e-2)=%d/%d/%d\n'],...
            x.nG,x.nD,x.nDc,x.Dcompress_ms,x.ipc_ms,x.ipc_cert,x.ipc_g,...
            x.mm_ms,x.rho,x.mm_cert,x.mm_g,x.near1e6,x.near1e4,x.near1e2);
        f101aa_silent_fprintf(['   RED-LP rows=%d/%d/%d | ms=%.3f/%.3f/%.3f | cert=%d/%d/%d ',...
                 '| fullviol=%+.1e/%+.1e/%+.1e\n'],...
            x.red_n(1),x.red_n(2),x.red_n(3),x.red_ms(1),x.red_ms(2),x.red_ms(3),...
            x.red_cert(1),x.red_cert(2),x.red_cert(3),...
            x.red_fullviol(1),x.red_fullviol(2),x.red_fullviol(3));
        f101aa_silent_fprintf(['   LOCAL vars=%d | budgets=%d/%d/%d | ms=%.3f/%.3f/%.3f ',...
                 '| cert=%d/%d/%d | fullviol=%+.1e/%+.1e/%+.1e | guards=%d/%d (%.3fms)\n'],...
            x.nLocal,x.loc_n(1),x.loc_n(2),x.loc_n(3),...
            x.loc_ms(1),x.loc_ms(2),x.loc_ms(3),...
            x.loc_cert(1),x.loc_cert(2),x.loc_cert(3),...
            x.loc_fullviol(1),x.loc_fullviol(2),x.loc_fullviol(3),...
            x.guard_n,x.nobs,x.guard_ms);
        f101aa_silent_fprintf(['   PRE-G vars=%d | select=%.3fms | budgets=%d/%d/%d | solve=%.3f/%.3f/%.3f ',...
                 '| cert=%d/%d/%d | fullviol=%+.1e/%+.1e/%+.1e\n'],...
            x.nPre,x.pre_ms,x.pre_n(1),x.pre_n(2),x.pre_n(3),...
            x.pre_solve_ms(1),x.pre_solve_ms(2),x.pre_solve_ms(3),...
            x.pre_cert(1),x.pre_cert(2),x.pre_cert(3),...
            x.pre_fullviol(1),x.pre_fullviol(2),x.pre_fullviol(3));
        f101aa_silent_fprintf(['   BLOCK center=%d guard=%d | select=%.3fms | vars=%d/%d/%d/%d ',...
                 '| solve=%.3f/%.3f/%.3f/%.3f | cert=%d/%d/%d/%d\n'],...
            x.blk_center,x.blk_guard_n,x.blk_ms,x.blk_n(1),x.blk_n(2),x.blk_n(3),x.blk_n(4),...
            x.blk_solve_ms(1),x.blk_solve_ms(2),x.blk_solve_ms(3),x.blk_solve_ms(4),...
            x.blk_cert(1),x.blk_cert(2),x.blk_cert(3),x.blk_cert(4));
        f101aa_silent_fprintf(['         fullviol=%+.1e/%+.1e/%+.1e/%+.1e | C6=%.1e/%.1e/%.1e/%.1e\n'],...
            x.blk_fullviol(1),x.blk_fullviol(2),x.blk_fullviol(3),x.blk_fullviol(4),...
            x.blk_c6(1),x.blk_c6(2),x.blk_c6(3),x.blk_c6(4));
        if ~isempty(x.f56)
            q=x.f56;
            f101aa_silent_fprintf(['   F56-24 cp=%s | xyzCounts=%d/%d/%d | completeCP=%d | spanDist med/max=%.1f/%.1f ',...
                     '| Gcov=%.3f Dv/Da/Dj=%.3f/%.3f/%.3f | %.3fms\n'],...
                mat2str(q.cp_ids),q.xyz_count(1),q.xyz_count(2),q.xyz_count(3),q.n_complete_cp,...
                q.span_dist_median,q.span_dist_max,q.G_energy_cover,...
                q.D_energy_cover(1),q.D_energy_cover(2),q.D_energy_cover(3),x.f56_ms);
        end
        f101aa_silent_fprintf(['   F57-AUTH select=%.3fms dirs=%d spans=%d | n=%d/%d/%d | overlap24=%d/%d/%d ',...
                 '| Gcov=%.3f/%.3f/%.3f\n'],...
            x.f57_select_ms,x.f57_meta.n_dirs,x.f57_meta.n_spans,...
            x.f57_n(1),x.f57_n(2),x.f57_n(3),...
            x.f57_overlap(1),x.f57_overlap(2),x.f57_overlap(3),...
            x.f57_Gcover(1),x.f57_Gcover(2),x.f57_Gcover(3));
        f101aa_silent_fprintf(['            solve=%.3f/%.3f/%.3fms | cert=%d/%d/%d | fullviol=%+.1e/%+.1e/%+.1e ',...
                 '| C6=%.1e/%.1e/%.1e\n'],...
            x.f57_solve_ms(1),x.f57_solve_ms(2),x.f57_solve_ms(3),...
            x.f57_cert(1),x.f57_cert(2),x.f57_cert(3),...
            x.f57_fullviol(1),x.f57_fullviol(2),x.f57_fullviol(3),...
            x.f57_c6(1),x.f57_c6(2),x.f57_c6(3));
        f101aa_silent_fprintf(['   F58-URG select=%.3fms rows=%d critical=%d infeas=%d | n=%d/%d/%d ',...
                 '| overlap24=%d/%d/%d | Gcov=%.3f/%.3f/%.3f\n'],...
            x.f58_select_ms,x.f58_meta.n_rows,x.f58_meta.n_critical,x.f58_meta.n_infeasible,...
            x.f58_n(1),x.f58_n(2),x.f58_n(3),...
            x.f58_overlap(1),x.f58_overlap(2),x.f58_overlap(3),...
            x.f58_Gcover(1),x.f58_Gcover(2),x.f58_Gcover(3));
        f101aa_silent_fprintf(['           solve=%.3f/%.3f/%.3fms | cert=%d/%d/%d | fullviol=%+.1e/%+.1e/%+.1e ',...
                 '| C6=%.1e/%.1e/%.1e\n'],...
            x.f58_solve_ms(1),x.f58_solve_ms(2),x.f58_solve_ms(3),...
            x.f58_cert(1),x.f58_cert(2),x.f58_cert(3),...
