function [Dc,dc,keep,ms]=f51_compress_D(D,d)
% Exact for rows with identical normalized left-hand direction:
% keep the tightest normalized RHS. Zero rows are kept only if needed.
t=tic;
rn=vecnorm(D,2,2); nzr=rn>1e-12;
Dn=D(nzr,:)./rn(nzr); dn=d(nzr)./rn(nzr);
% Quantization is ONLY a grouping key; representatives retain original rows.
key=round(Dn*1e12)/1e12;
[~,~,ic]=unique(key,'rows','stable');
ng=max(ic); keepLocal=zeros(ng,1);
ids=find(nzr);
for q=1:ng
    jj=find(ic==q);
    [~,m]=min(dn(jj));
    keepLocal(q)=ids(jj(m));
end
zids=find(~nzr);
if any(d(zids)<0)
    [~,m]=min(d(zids)); keepLocal(end+1)=zids(m);
end
keep=keepLocal(:);
Dc=D(keep,:); dc=d(keep);
ms=1e3*toc(t);
end

function [ok,z,ms]=f51_ip(c,A,b,opt)
nz=c.nz; lb=-opt.box_z_max*ones(nz,1); ub=opt.box_z_max*ones(nz,1);
qo=optimoptions('quadprog','Display','off','Algorithm','interior-point-convex',...
    'ConstraintTolerance',1e-9,'OptimalityTolerance',1e-9,'MaxIterations',1500);
t=tic; ok=false; z=[];
try
    [zz,~,fl]=quadprog(1e-10*eye(nz),zeros(nz,1),A,b,[],[],lb,ub,[],qo);
    if fl>0 && max([A*zz-b;lb-zz;zz-ub])<=1e-8, ok=true; z=zz; end
catch
end
ms=1e3*toc(t);
end

function [rho,z,ms]=f51_margin_lp_fast(A,b,c,opt)
nz=c.nz; lb=-opt.box_z_max*ones(nz,1); ub=opt.box_z_max*ones(nz,1);
rs=max(vecnorm(A,2,2),1e-12);
As=A./rs; bs=b./rs;
% A z + rho <= b  -> maximize rho.
AA=[As,ones(size(As,1),1)];
ff=[zeros(nz,1);-1];
lo=optimoptions('linprog','Display','none','Algorithm','dual-simplex',...
    'ConstraintTolerance',1e-9,'OptimalityTolerance',1e-9,'MaxIterations',1000);
rho=NaN; z=[]; t=tic;
try
    [x,~,fl]=linprog(ff,AA,bs,[],[],[lb;0],[ub;inf],lo);
    if fl>0, z=x(1:nz); rho=x(end); end
catch
end
ms=1e3*toc(t);
end










function [cols,pref,META,ms]=f61_signed_consensus_selector(c,cfg,obs,opt)
% Signed critical-row consensus selector.
%
% Build the same compact pre-G surrogate rows used in F58/F59:
%       a_i z <= b_i.
% Starting at zhat=0, choose (column j, sign sigma) that maximally reduces
% the CURRENT positive violation
%       r_i=[a_i zhat-b_i]_+,
% with a temporary full-box step z_j=sigma*zmax.
%
% The temporary signs are NOT imposed on the final optimization. They only
% choose a low-dimensional subspace. Final z is re-solved by max-margin LP.
t=tic; nz=c.nz; zmax=opt.box_z_max;
B=zeros(0,1); A=zeros(0,nz);

for sp=1:c.nspans
    Bp=c.B0{sp}; Bz=c.Bz{sp};
    [Abez,Az]=f58_accel_bezier_affine(c,sp); %#ok<ASGLU>
    for o=1:numel(obs)
        N=direction_grid_from_geometry(Bp,obs(o),cfg,opt);
        if isempty(N), continue; end
        [bb,aa]=f58_batch_rows_for_selector(Bp,Bz,Abez,Az,N,obs(o),cfg,opt);
        % f58 helper returns the signed affine coefficient n'*M.
        B=[B;bb]; %#ok<AGROW>
        A=[A;aa]; %#ok<AGROW>
    end
end

valid=vecnorm(A,1,2)>1e-14 & isfinite(B);
A=A(valid,:); B=B(valid);
nRows=numel(B);
critical=B<0;

% Focus selection on violated but individually box-reachable rows.
rowL1=sum(abs(A),2);
reach=B+zmax*rowL1;
use=critical & reach>=0 & rowL1>1e-14;
Au=A(use,:); Bu=B(use);
if isempty(Bu)
    cols=1:nz; pref=ones(1,nz);
    META=struct('n_rows',nRows,'n_critical',nnz(critical),'n_used',0,...
        'residual',zeros(1,nz),'initial_violation',0);
    ms=1e3*toc(t); return
end

% Harder rows receive somewhat larger dimensionless weight.
need=max(0,-Bu);
authority=zmax*sum(abs(Au),2);
eta=need./max(authority,eps);
w=1+min(10,eta);

zhat=zeros(nz,1);
chosen=false(1,nz);
cols=zeros(1,nz); pref=zeros(1,nz); residual=zeros(1,nz);
r=max(0,Au*zhat-Bu);
initial=sum(w.*r);

for q=1:nz
    % Evaluate +zmax and -zmax for every unused scalar DOF.
    % Current signed lhs is Au*zhat. For candidate j:
    % lhs_new = lhs + sigma*zmax*Au(:,j).
    lhs=Au*zhat;
    Rplus=max(0,lhs + zmax*Au - Bu);   % nUse x nz
    Rminus=max(0,lhs - zmax*Au - Bu);
    costPlus=sum(w.*Rplus,1);
    costMinus=sum(w.*Rminus,1);
    [bestCost,bestSign]=min([costPlus;costMinus],[],1);
    bestCost(chosen)=inf;
    [~,j]=min(bestCost);
    if ~isfinite(bestCost(j))
        break
    end
    sigma=1;
    if bestSign(j)==2, sigma=-1; end
    chosen(j)=true; cols(q)=j; pref(q)=sigma;
    zhat(j)=sigma*zmax;
    r=max(0,Au*zhat-Bu);
    residual(q)=sum(w.*r)/max(initial,eps);
end

% Fill any unused tail deterministically by signed one-column consensus.
nsel=nnz(cols);
if nsel<nz
    left=find(~chosen);
    base=sum(w.*max(0,-Bu));
    cp=sum(w.*max(0,zmax*Au(:,left)-Bu),1);
    cm=sum(w.*max(0,-zmax*Au(:,left)-Bu),1);
    [~,ord]=sort(min(cp,cm),'ascend');
    left=left(ord);
    for kk=1:numel(left)
        j=left(kk); nsel=nsel+1; cols(nsel)=j;
        if cm(ord(kk))<cp(ord(kk)), pref(nsel)=-1; else, pref(nsel)=1; end
        residual(nsel)=residual(max(1,nsel-1));
    end
end
cols=cols(cols>0); pref=pref(1:numel(cols));

META=struct('n_rows',nRows,'n_critical',nnz(critical),'n_used',nnz(use),...
    'residual',residual,'initial_violation',initial);
ms=1e3*toc(t);
end

function agree=f61_teacher_sign_agreement(cols,pref,teacher,G,g,D,d,c,opt)
% Diagnostic only: compare temporary selector sign with the sign of the
% teacher-24 max-margin solution on overlapping columns.
agree=NaN;
[~,zt,~]=f53_margin_lp_subset([G;D],[g;d],c,opt,teacher);
if isempty(zt), return; end
[common,ia,~]=intersect(cols,teacher,'stable');
if isempty(common), return; end
sgn=sign(zt(common)); pp=pref(ia).';
nz=sgn~=0;
if ~any(nz), return; end
agree=mean(pp(nz)==sgn(nz));
end

function Q=f60_empty()
Q=struct('name','','cols',[],'rank',0,'cond',Inf,'coherence',1,...
    'rho',-Inf,'feasible',false,'fullviol',Inf,...
    'nz_pos',0,'nz_neg',0,'nz_zero',0,...
    'ncritG',0,'nsatG',0,'conflict_ratio',NaN,'signed_gain',NaN,...
    'row_margin_min',-Inf,'row_margin_med',-Inf);
end

function Q=f60_subspace_forensic(G,g,D,d,c,opt,cols,name)
% Compare a fixed 24-DOF subspace using the SAME signed inequalities.
% System convention:
%       A z <= b,  A=[G;D], b=[g;d].
% We inspect rank/conditioning, signed max-margin feasibility, sign pattern
% of z*, and whether critical G rows request mutually opposed motion.
Q=f60_empty(); Q.name=name; Q.cols=cols(:).';
if isempty(cols), return; end

A=[G;D]; b=[g;d];
AJ=A(:,cols);
Q.rank=rank(AJ,1e-10);

% Column conditioning after normalization; avoid reporting arbitrary scale.
cn=vecnorm(AJ,2,1);
Jn=AJ(:,cn>1e-13)./cn(cn>1e-13);
if isempty(Jn)
    Q.cond=Inf; Q.coherence=1;
else
    sv=svd(Jn,'econ');
    if isempty(sv) || sv(end)<=1e-14, Q.cond=Inf;
    else, Q.cond=sv(1)/sv(end); end
    C=abs(Jn.'*Jn); C(1:size(C,1)+1:end)=0;
    if isempty(C), Q.coherence=0; else, Q.coherence=max(C,[],'all'); end
end

% Solve the same normalized max-margin LP restricted to these columns.
[rho,zfull,~]=f53_margin_lp_subset(A,b,c,opt,cols);
Q.rho=rho;
Q.feasible=~isempty(zfull);
if isempty(zfull), return; end
Q.fullviol=max(A*zfull-b);
z=zfull(cols);
tolz=1e-8*max(1,max(abs(z)));
Q.nz_pos=nnz(z>tolz); Q.nz_neg=nnz(z<-tolz); Q.nz_zero=numel(z)-Q.nz_pos-Q.nz_neg;

% Critical collision rows at z=0.
crit=find(g<0);
Q.ncritG=numel(crit);
if isempty(crit)
    Q.nsatG=0; Q.conflict_ratio=0; Q.signed_gain=0;
    return
end
GC=G(crit,cols);
gc=g(crit);
Q.nsatG=nnz(G(crit,:)*zfull <= gc+1e-9);

% Signed compatibility diagnostic.
% For each selected column, critical rows may ask for opposite z signs.
% For G_i z <= g_i with g_i<0, a negative contribution is helpful.
% Count authority carried by columns that have substantial coefficients
% of BOTH signs across critical rows.
absSum=sum(abs(GC),1);
pos=sum(max(GC,0),1);
neg=sum(max(-GC,0),1);
both=min(pos,neg);
Q.conflict_ratio=sum(both)/max(sum(absSum),eps);

% Actual signed useful motion of the max-margin solution on critical G rows.
% Positive value means the solution moves rows in the required negative
% direction, normalized by total critical required correction.
move=-(GC*z);
need=max(0,-gc);
Q.signed_gain=sum(max(0,move))/max(sum(need),eps);

marg=gc-GC*z;
Q.row_margin_min=min(marg);
Q.row_margin_med=median(marg);
end

function [cols,META,ms]=f59_greedy_set_selector(c,cfg,obs,opt)
% F59 set-authority selector.
%
% Builds a compact batch of candidate row surrogates, then selects DOFs as
% a SET. For selected set J, each row has box-authority residual
%
%   R_i(J)=b_i + zmax*sum_{j in J}|a_ij|.
%
% Only rows with b_i<0 need repair. At each greedy step choose the DOF that
% covers the largest weighted portion of the CURRENT residual deficit:
%
% gain_j = sum_i w_i min(zmax|a_ij|, [-R_i(J)]_+).
%
% This is candidate generation only. It does not certify collision safety.
t=tic; nz=c.nz; zmax=opt.box_z_max;

% Batch candidate rows. Preallocate conservatively and grow if necessary.
B=zeros(0,1); AA=zeros(0,nz);
for sp=1:c.nspans
    Bp=c.B0{sp}; Bz=c.Bz{sp};
    [Abez,Az]=f58_accel_bezier_affine(c,sp); %#ok<ASGLU>
    for o=1:numel(obs)
        N=direction_grid_from_geometry(Bp,obs(o),cfg,opt);
        if isempty(N), continue; end
        [bb,aa]=f58_batch_rows_for_selector(Bp,Bz,Abez,Az,N,obs(o),cfg,opt);
        B=[B;bb]; %#ok<AGROW>
        AA=[AA;abs(aa)]; %#ok<AGROW>
    end
end

valid=sum(AA,2)>1e-14 & isfinite(B);
B=B(valid); AA=AA(valid,:);
nRows=numel(B);
rowL1=sum(AA,2);
authority=zmax*rowL1;
critical=B<0;
infeas=(B+authority)<0;

% Rows impossible even with all box variables cannot be repaired by column
% selection. Keep them diagnostically, but do not let their unbounded
% deficit dominate every greedy step.
use=critical & ~infeas & authority>1e-14;
Bu=B(use); Au=AA(use,:); authu=authority(use);
def=max(0,-Bu);

% Dimensionless row weight: harder-but-reachable rows receive more weight.
eta=def./max(authu,eps);
w=1+min(10,eta);
initialWeighted=sum(w.*def);

chosen=false(1,nz); cols=zeros(1,nz);
residual=zeros(1,nz);
if isempty(def)
    % No violated surrogate row: fall back to aggregate normalized authority.
    S=sum(AA./max(rowL1,eps),1);
    [~,ord]=sort(S,'descend');
    cols=ord;
    residual(:)=0;
else
    rem=def;
    for q=1:nz
        % Vectorized marginal coverage for every candidate column.
        cap=zmax*Au;                 % nUse x nz
        cover=min(cap,rem);          % implicit expansion
        gain=sum(w.*cover,1);
        gain(chosen)=-inf;
        [best,j]=max(gain);
        if ~isfinite(best) || best<=1e-15
            left=find(~chosen);
            cols(q:q+numel(left)-1)=left;
            residual(q:end)=sum(w.*rem)/max(initialWeighted,eps);
            break
        end
        chosen(j)=true; cols(q)=j;
        rem=max(0,rem-zmax*Au(:,j));
        residual(q)=sum(w.*rem)/max(initialWeighted,eps);
    end
end
cols=cols(cols>0);

META=struct();
META.n_rows=nRows;
META.n_critical=nnz(critical);
META.n_infeasible=nnz(infeas);
META.n_used=nnz(use);
META.residual=residual;
META.initial_weighted_deficit=initialWeighted;
ms=1e3*toc(t);
end

function [cols,score,META,ms]=f58_streaming_urgency_selector(c,cfg,obs,opt)
% Urgency-weighted streaming selector derived from the exact box-authority
% inequality for each candidate corridor row:
%       a_i z <= b_i, |z_j|<=zmax
% row feasibility requires
%       b_i + zmax ||a_i||_1 >= 0.
%
% We never store full G here. For each span/obstacle, use the validated F48
% batch separator evaluator, then stream its rows into a 1 x nz score.
%
% For a row:
%   required=max(0,-b)
%   authority=zmax*||a||_1
%   eta=required/max(authority,eps)
% and scalar DOF contribution is |a_j|/||a||_1.
%
% Rows with b>=0 still receive a small near-boundary weight so the selector
% can preserve margin rather than only repair already violated rows.
t=tic; nz=c.nz; score=zeros(1,nz);
nRows=0; nCritical=0; nInfeas=0; etaMax=0;
zmax=opt.box_z_max;

for sp=1:c.nspans
    Bp=c.B0{sp}; Bz=c.Bz{sp};

    % Exact acceleration Bezier and affine map by differentiating position
    % Bezier points. Same algebra used by the validated fast corridor.
    [Abez,Az]=f58_accel_bezier_affine(c,sp);

    for o=1:numel(obs)
        % Use exactly the corridor direction grid; F48 evaluator is already
        % numerically audited against the scalar formulas.
        N=direction_grid_from_geometry(Bp,obs(o),cfg,opt);
        if isempty(N), continue; end

        [Gall,authall]=f58_batch_rows_for_selector(Bp,Bz,Abez,Az,N,obs(o),cfg,opt);
        % Gall is g_lower at z=0. Corridor convention is A z <= b with
        % A=-rowCoeff and b=Gall, hence |A_j|=|rowCoeff_j|.
        for k=1:size(authall,1)
            b=Gall(k);
            aabs=abs(authall(k,:));
            l1=sum(aabs);
            if l1<=1e-14, continue; end
            nRows=nRows+1;
            authority=zmax*l1;
            required=max(0,-b);
            eta=required/max(authority,eps);
            etaMax=max(etaMax,eta);
            if b<0, nCritical=nCritical+1; end
            if b+authority<0, nInfeas=nInfeas+1; end

            frac=aabs/l1;
            if b<0
                % Critical-row weight comes directly from required/available
                % correction. +1 keeps moderately violated rows represented.
                w=1+min(10,eta);
            else
                % Feasible rows matter only when close to the box authority
                % scale. This term vanishes smoothly for large positive b.
                w=0.15/(1+b/max(authority,eps));
            end
            score=score+w*frac;
        end
    end
end

[~,ord]=sort(score,'descend');
cols=ord(score(ord)>1e-14);
META=struct('n_rows',nRows,'n_critical',nCritical,'n_infeasible',nInfeas,...
    'eta_max',etaMax);
ms=1e3*toc(t);
end

function [Abez,Az]=f58_accel_bezier_affine(c,sp)
% Exact second derivative of degree-p Bezier position representation.
Bp=c.B0{sp}; Bz=c.Bz{sp}; p=c.p;
% infer physical span duration from cache knots (already at current T)
du=c.knots(c.p+sp+1)-c.knots(c.p+sp);
fac=p*(p-1)/(du^2);
Abez=fac*(Bp(:,3:end)-2*Bp(:,2:end-1)+Bp(:,1:end-2));
Az=fac*(Bz(:,:,3:end)-2*Bz(:,:,2:end-1)+Bz(:,:,1:end-2));
end

function N=direction_grid_from_geometry(Bp,ob,cfg,opt)
% Reuse the same algebraic direction construction as the corridor whenever
% available in this file. This helper intentionally returns a modest fixed
% geometry-derived bundle; final safety never depends on this bundle.
pc=mean(Bp,2); d=pc-ob.center(:); nd=norm(d);
if nd<=1e-12, n0=[1;0;0]; else, n0=d/nd; end
N=n0;
if isfield(ob,'R') && all(size(ob.R)==[3 3])
    for q=1:3
        v=ob.R(:,q);
        if dot(v,n0)<0, v=-v; end
        N(:,end+1)=v; %#ok<AGROW>
    end
end
% Add transverse directions generated by cross products to avoid the F57
% failure mode of purely radial/principal-axis authority.
axes3=eye(3);
for q=1:3
    v=cross(n0,axes3(:,q)); nv=norm(v);
    if nv>1e-10, N(:,end+1)=v/nv; end %#ok<AGROW>
end
% normalize / de-duplicate
NN=zeros(3,0);
for q=1:size(N,2)
    v=N(:,q); nv=norm(v); if nv<=1e-12, continue; end; v=v/nv;
    if isempty(NN) || all(abs(NN.'*v)<1-1e-8), NN(:,end+1)=v; end %#ok<AGROW>
end
N=NN;
end

function [Gall,AabsRows]=f58_batch_rows_for_selector(Bp,Bz,Abez,Az,N,ob,cfg,opt)
% Lightweight streaming row surrogate using the exact position affine
% authority and the same zero-z lower-bound ingredients. It does not claim
% to replace the final corridor/certificate.
K=size(N,2); nz=size(Bz,2);
Gall=-inf(K,1); AabsRows=zeros(K,nz);
for k=1:K
    n=N(:,k);
    vals=n.'*Bp;
    [plow,jstar]=min(vals);
    M=squeeze(Bz(:,:,jstar));
    row=n.'*M;

    % Suspended-system separation at base acceleration. Use midpoint of
    % acceleration Bezier hull for ranking only.
    amid=mean(Abez,2);
    W=amid+[0;0;cfg.g_acc];
    if norm(W)>1e-12, nT=W/norm(W); else, nT=[0;0;1]; end
    sep=delta_sep_exact(n,nT,cfg.sys);
    hs=obstacle_support(ob,n);
    Gall(k)=plow-sep-hs-cfg.d_margin;
    AabsRows(k,:)=row;
end
end

function [cols,score,META,ms]=f57_directional_authority_selector(c,obs,cfg,opt,threat)
% Analytic pre-G directional-authority selector.
%
% For each span s, Bezier point l and algebraic separator direction n:
%   B_{s,l}(z)=B0_{s,l}+M_{s,l}z
%   n'B_{s,l}(z)=n'B0_{s,l}+(n'M_{s,l})z.
% Therefore |n'M(:,j)| is direct authority of scalar DOF z_j in that
% separating direction. No corridor matrix G or optimization solution is
% used here.
%
% Candidate generation only. Final safety remains certify_candidate_global.
t=tic; nz=c.nz; ns=c.nspans; no=numel(obs);
score=zeros(1,nz);

% Small algebraic direction bundle per obstacle/span:
% center direction + two ellipsoid principal transverse directions.
% These directions are geometry-derived online; no physical parameter table.
nEval=0; activeSpan=false(1,ns);

for sp=1:ns
    B0=c.B0{sp}; Bz=c.Bz{sp};
    pc=mean(B0,2);
    for o=1:no
        d=obs(o).center(:)-pc;
        nd=norm(d);
        if nd<=1e-12, n0=[1;0;0]; else, n0=d/nd; end

        % Relevance weighting only affects ranking, never safety.
        ro=max(obs(o).radii);
        sys=cfg.sys.L_cable+cfg.sys.R_uav+cfg.sys.R_payload+cfg.sys.R_cable+cfg.d_margin;
        gap=max(0.10,nd-ro-sys);
        urgency=1/gap;
        if isfield(threat,'tau') && o<=numel(threat.tau) && isfinite(threat.tau(o))
            urgency=urgency/(1+max(0,threat.tau(o)));
        end

        N=n0;
        if isfield(obs(o),'R') && all(size(obs(o).R)==[3 3])
            R=obs(o).R;
            % Add principal axes with sign chosen toward center direction.
            for q=1:3
                v=R(:,q);
                if dot(v,n0)<0, v=-v; end
                N(:,end+1)=v; %#ok<AGROW>
            end
        end
        % Normalize and remove nearly duplicate directions.
        NN=zeros(3,0);
        for q=1:size(N,2)
            v=N(:,q); nv=norm(v); if nv<=1e-12, continue; end; v=v/nv;
            if isempty(NN) || all(abs(NN.'*v)<1-1e-8)
                NN(:,end+1)=v; %#ok<AGROW>
            end
        end
        nEval=nEval+size(NN,2);

        % Span is only a ranking emphasis. Do not hard-discard remote spans.
        if gap <= 2.5+opt.box_z_max
            activeSpan(sp)=true;
            spanw=1.0;
        else
            spanw=1/(1+gap);
        end

        for l=1:c.p+1
            M=squeeze(Bz(:,:,l)); % 3 x nz
            for q=1:size(NN,2)
                n=NN(:,q);
                a=abs(n.'*M);
                % Normalize direction-row authority so ranking is not
                % dominated by arbitrary affine-map scale.
                an=norm(a);
                if an>1e-14, a=a/an; end
                score=max(score,spanw*urgency*a);
            end
        end
    end
end

% Axis-balance regularization without forcing xyz blocks: each scalar DOF
% remains individually ranked. Tiny structural tie-breaker favors DOFs with
% broader exact B-spline support.
supportCount=zeros(1,nz);
for sp=1:ns
    M=c.Bz{sp};
    supportCount=supportCount+squeeze(any(any(abs(M)>1e-13,1),3));
end
if max(supportCount)>0
    score=score.*(1+1e-6*supportCount/max(supportCount));
end

[~,ord]=sort(score,'descend');
cols=ord(score(ord)>1e-14);
META=struct('n_dirs',nEval,'n_spans',nnz(activeSpan),'active_spans',find(activeSpan));
ms=1e3*toc(t);
end

function [Q,ms]=f56_forensic24(c,G,g,D,d,obs,cfg,opt,info)
% Explain the F53 successful 24-variable choice.
% The selector is exactly F53's normalized-G influence ranking.
% Outputs structural diagnostics only; no safety decision is made here.
t=tic; Q=[];
[cols,score]=f53_local_columns(G,c.nz);
if numel(cols)<24, ms=1e3*toc(t); return; end
sel=cols(1:24);
nf=c.nf;
cp=ceil(sel/3);
ax=mod(sel-1,3)+1;
cpids=unique(cp,'stable');

% Complete xyz blocks among the 24 selected scalar DOFs.
ncomplete=0;
for j=cpids
    if all(ismember(3*(j-1)+(1:3),sel)), ncomplete=ncomplete+1; end
end
xyz=[nnz(ax==1),nnz(ax==2),nnz(ax==3)];

% Map each free control point to the spans on which it has nonzero Bezier
% affine influence. This is an exact structural support audit of c.Bz.
supp=cell(1,nf);
for j=1:nf
    cc=3*(j-1)+(1:3); ss=[];
    for sp=1:c.nspans
        M=c.Bz{sp};
        if any(abs(M(:,cc,:))>1e-13,'all'), ss(end+1)=sp; end %#ok<AGROW>
    end
    supp{j}=ss;
end

% Collision/corridor active span set from the already constructed candidate
% generator. It is used only to explain the teacher selector.
activeSp=find(any(info.active,2)).';
if isempty(activeSp), activeSp=1:c.nspans; end
dist=zeros(1,numel(cpids));
for k=1:numel(cpids)
    ss=supp{cpids(k)};
    if isempty(ss), dist(k)=inf;
    else
        % Minimum distance between the selected control-point support-span
        % set and the corridor-active span set:
        %   d_k = min_{s in S_k, a in S_active} |s-a|.
        DD=abs(ss(:)-activeSp(:).');
        dist(k)=min(DD,[],'all');
    end
end

% Normalized row energy captured by selected columns.
Gn=G./max(vecnorm(G,2,2),1e-12);
allGE=sum(Gn.^2,'all');
selGE=sum(Gn(:,sel).^2,'all');
Gcov=selGE/max(allGE,eps);

% Split D by the known construction ordering if divisible into v/a/j thirds.
% If exact thirds are not available, report total D coverage in all slots.
Dn=D./max(vecnorm(D,2,2),1e-12);
nr=size(Dn,1); Dcov=zeros(1,3);
if mod(nr,3)==0
    m=nr/3;
    for r=1:3
        R=(r-1)*m+(1:m);
        Dcov(r)=sum(Dn(R,sel).^2,'all')/max(sum(Dn(R,:).^2,'all'),eps);
    end
else
    z=sum(Dn(:,sel).^2,'all')/max(sum(Dn.^2,'all'),eps);
    Dcov(:)=z;
end

% Per-control-point teacher score, useful for seeing whether the successful
% 24 scalar variables form blocks or directional DOFs.
cpscore=zeros(1,nf);
for j=1:nf, cpscore(j)=max(score(3*(j-1)+(1:3))); end

Q=struct('cols',sel,'scalar_score',score(sel),'cp_ids',cpids,...
    'axis_ids',ax,'xyz_count',xyz,'n_complete_cp',ncomplete,...
    'cp_score',cpscore(cpids),'cp_support',{supp(cpids)},...
    'active_spans',activeSp,'span_distance',dist,...
    'span_dist_median',median(dist(isfinite(dist))),...
    'span_dist_max',max(dist(isfinite(dist))),...
    'G_energy_cover',Gcov,'D_energy_cover',Dcov);
ms=1e3*toc(t);
end

function [COLS,META,ms]=f55_structured_blocks(c,obs,cfg,opt,threat)
% Structured local-support selector.
% This selector is NOT a safety proof.  It only chooses candidate variables.
% Safety theorem remains the unchanged global continuous-time certificate.
%
% A free B-spline control point is retained as a COMPLETE xyz block when its
% position-affine Bezier influence is nonzero on a selected span window.
t=tic; ns=c.nspans; no=numel(obs);
score=inf(ns,no);
rb=cfg.sys.L_cable+cfg.sys.R_uav+cfg.sys.R_payload+cfg.sys.R_cable+cfg.d_margin;
for sp=1:ns
    B0=c.B0{sp};
    for o=1:no
        ro=max(obs(o).radii);
        % Distance of obstacle center to convex-hull vertices; only locates
        % a candidate window. It is never used to certify collision freedom.
        score(sp,o)=min(vecnorm(B0-obs(o).center(:),2,1))-ro-rb;
    end
end
% Prefer the urgent obstacle supplied by the front end, but locate its
% nearest span geometrically. Other obstacles become guards if their nearest
% span overlaps the widest tested window.
if isempty(threat.order), op=1; else, op=threat.order(1); end
[~,center]=min(score(:,op));
COLS=cell(1,4);
for w=1:4
    S=max(1,center-w):min(ns,center+w);
    infl=false(1,c.nz);
    for sp=S
        M=c.Bz{sp};
        infl=infl | squeeze(any(any(abs(M)>1e-13,1),3));
    end
    % Preserve complete xyz block for every selected free control point.
    cp=false(1,c.nf);
    for j=1:c.nf
        cp(j)=any(infl(3*(j-1)+(1:3)));
    end
    cols=[];
    for j=find(cp)
        cols=[cols,3*(j-1)+(1:3)]; %#ok<AGROW>
    end
    COLS{w}=cols;
end
guard=false(1,no);
wide=max(1,center-4):min(ns,center+4);
for o=1:no
    [~,so]=min(score(:,o));
    guard(o)=any(wide==so);
end
META=struct('center_span',center,'primary_obs',op,'guard_ids',find(guard),'guard_n',nnz(guard));
ms=1e3*toc(t);
end

function [cols,score,ms]=f54_preselect_columns(c,obs,cfg,opt,threat)
% PRE-G local-DOF selector.
% Uses no G rows, no QP/LP solution, and no physical-parameter-specific
% offline table. It scores each z column by how strongly it can move Bezier
% control points near detected obstacles, with urgency weighting.
t=tic; nz=c.nz; score=zeros(1,nz);
if isempty(obs), cols=1:nz; ms=1e3*toc(t); return; end
% Directional suspended-system inflation for broad relevance only.
rb0=cfg.sys.L_cable+max(cfg.sys.R_uav,cfg.sys.R_payload)+cfg.sys.R_cable+cfg.d_margin;
tau=inf(1,numel(obs));
if isfield(threat,'tau'), tau=threat.tau; end
for sp=1:c.nspans
    B0=c.B0{sp}; Bz=c.Bz{sp};
    for o=1:numel(obs)
        co=obs(o).center(:);
        ro=max(obs(o).radii);
        urgency=1/(1+max(0,tau(o)));
        for j=1:c.p+1
            d=co-B0(:,j); nd=norm(d);
            if nd<=1e-12, n=[1;0;0]; else, n=d/nd; end
            M=squeeze(Bz(:,:,j)); % 3 x nz
            % Column influence in obstacle radial direction plus a small
            % transverse term so side-step authority is not discarded.
            radial=abs(n.'*M);
            total=sqrt(sum(M.^2,1));
            proximity=1/max(0.10,nd-ro-rb0);
            score=max(score,urgency*proximity.*(radial+0.25*total));
        end
    end
end
[~,ord]=sort(score,'descend');
cols=ord(score(ord)>1e-14);
% Always retain all nonzero candidates in ranking; budgets choose prefix.
ms=1e3*toc(t);
end

function [cols,score]=f53_local_columns(G,nz)
% Rank z variables by their influence on obstacle corridor rows.
% Purely diagnostic.  This exploits local support already encoded in G.
if isempty(G), cols=1:nz; score=zeros(1,nz); return; end
rs=max(vecnorm(G,2,2),1e-12);
Gn=G./rs;
score=max(abs(Gn),[],1);
[~,ord]=sort(score,'descend');
cols=ord(score(ord)>1e-12);
end

function [rho,zfull,ms]=f53_margin_lp_subset(A,b,c,opt,cols)
% Max normalized common margin with only selected z columns free.
% Nonselected z variables are exactly zero; result is lifted to full z.
nz=c.nz; nc=numel(cols);
rs=max(vecnorm(A,2,2),1e-12);
As=A(:,cols)./rs; bs=b./rs;
AA=[As,ones(size(A,1),1)];
ff=[zeros(nc,1);-1];
lb=[-opt.box_z_max*ones(nc,1);0];
ub=[ opt.box_z_max*ones(nc,1);inf];
lo=optimoptions('linprog','Display','none','Algorithm','dual-simplex',...
    'ConstraintTolerance',1e-9,'OptimalityTolerance',1e-9,'MaxIterations',1000);
rho=NaN; zfull=[]; t=tic;
try
    [x,~,fl]=linprog(ff,AA,bs,[],[],lb,ub,lo);
    if fl>0
        rho=x(end); zfull=zeros(nz,1); zfull(cols)=x(1:nc);
    end
catch
end
ms=1e3*toc(t);
end

function [ng,ids,ms]=f53_guard_set(c,obs,cfg,opt)
% Conservative candidate-generation guard set.
% A detected obstacle is guarded if its bounding sphere can intersect a
% reachable envelope of any position Bezier control point under |z|<=zmax,
% inflated by suspended-system geometry + safety margin.
%
% IMPORTANT: this is only a broad phase. It never grants safety and never
% replaces certify_candidate_global(all detected obstacles).
t=tic; ids=[];
% Conservative system inflation independent of obstacle orientation.
% Use the benchmark's actual system-field names (same as the existing
% active-obstacle broad phase and delta_sep_* functions).
sysrad=max([cfg.sys.R_payload,cfg.sys.R_uav,cfg.sys.R_cable]);
sysrad=sysrad+cfg.sys.L_cable;
inflate=sysrad+cfg.d_margin;
for o=1:numel(obs)
    % Ellipsoid bounding radius. F53 benchmark obstacles use S and center.
    if isfield(obs(o),'S')
        ro=sqrt(max(eig(obs(o).S)));
    else
        ro=0;
    end
    co=obs(o).center(:);
    hit=false;
    for sp=1:c.nspans
        B0=c.B0{sp}; Bz=c.Bz{sp};
        for j=1:c.p+1
            % Exact box upper bound on displacement norm, using componentwise
            % box bounds then Euclidean radius.
            M=squeeze(Bz(:,:,j));
            dr=opt.box_z_max*sum(abs(M),2);
            reach=norm(dr);
            if norm(B0(:,j)-co) <= ro+inflate+reach
                hit=true; break;
            end
        end
        if hit, break; end
    end
    if hit, ids(end+1)=o; end %#ok<AGROW>
end
ng=numel(ids); ms=1e3*toc(t);
end

function r=f32_empty()
r=struct('id',0,'family','','sf',NaN,'nobs',0,'tdetect',NaN,'T0',NaN,'T',NaN,...
    'mult',NaN,'N',NaN,'attempts',0,'cert',false,'G_constructed',false,'GD',false,...
    'reason','NOT_RUN','front_ms',0,'cache_ms',0,'dynamics_ms',0,'active_ms',0,...
    'corridor_ms',0,'qp_ms',0,'apply_ms',0,'cert_ms',0,'wall_ms',0,'qp_calls',0,...
    'n_screen',0,'active_max',0,'min_g',-inf,'c6s',inf,'c6e',inf,'v',inf,'a',inf,'j',inf);
end


function [T0,threat]=f32_fast_horizon(D,obs,cfg,limits)
% Cheap deterministic horizon seed from CURRENT state and newly detected
% obstacle geometry.  No future trajectory scan.
pL=D(:,1);vL=D(:,2);aL=D(:,3);
W=aL+cfg.g_acc*cfg.e3;
if norm(W)<=1e-12,nT=cfg.e3;else,nT=W/norm(W);end
pQ=pL+cfg.sys.L_cable*nT;

no=numel(obs);score=inf(1,no);tau=inf(1,no);
v=max(norm(vL),0.25);
for k=1:no
    d=obs(k).center-pL;
    L=norm(d);
    if L<=1e-12,n=[1;0;0];else,n=d/L;end
    ext=obstacle_support(obs(k),-n)+delta_sep_exact(-n,nT,cfg.sys);
    gap=max(0,L-ext-cfg.d_margin);
    closing=max(0,vL'*n);
    veff=max(closing,0.35*v);
    tau(k)=gap/max(veff,0.25);
    % prioritize small time-to-contact and proximity to current UAV/load line
    score(k)=tau(k);
end
[taumin,ord]=sort(tau,'ascend');
threat.order=ord;threat.tau=tau;threat.score=score;

% State/geometry based seed.  Braking/curvature room is represented by a
% minimum maneuver time from v/a limits.  This chooses a candidate only.
vmax=max(limits.v_max,1e-6);amax=max(limits.a_max,1e-6);
tman=max(2.0,0.70*v/amax+0.35*v/vmax);
if isempty(taumin)||~isfinite(taumin(1)),T0=4.0;
else,T0=max(tman,min(18.0,1.15*taumin(1)+1.5));end
T0=max(3.0,T0);
end


function active=f32_active_obstacles(c,obs,threat,cfg,opt)
% Cheap broad phase.  Keep obstacles whose conservative center distance to
% the base trajectory can plausibly interact with the candidate horizon.
% At least the two most urgent obstacles are retained when available.
no=numel(obs);keep=false(1,no);
ns=min(7,max(3,numel(c.spans)));
us=linspace(0,1,ns);
for io=1:no
    ro=max(obs(io).radii);
    % Conservative broad-phase radius ONLY for rejection/prioritization.
    % It is NOT the final system safety model/certificate.
    rb=ro+cfg.sys.L_cable+cfg.sys.R_uav+cfg.sys.R_payload+cfg.d_margin+1.0;
    for u=us
        p=eval_spline(c,c.Pbase,u,0);
        if norm(p-obs(io).center)<=rb
            keep(io)=true;break;
        end
    end
end
m=min(2,no);keep(threat.order(1:m))=true;
active=find(keep);
if isempty(active),active=threat.order(1);end
end


function obs=f32_detected_ellipsoids(obs0,nom_fun,cfg,id,no,tdetect,SCALE_SET,SHAPES,TMISSION)
obs=repmat(obs0(1),1,no);
for io=1:no
    th=min(TMISSION-2,tdetect+5.5+2.8*(io-1)+.35*mod(id+io,5));
    D=nom_fun(th);
    W=D(:,3)+cfg.g_acc*cfg.e3;
    if norm(W)<=1e-12,nT=cfg.e3;else,nT=W/norm(W);end
    v=D(:,2);if norm(v)<=1e-9,v=[1;0;0];else,v=v/norm(v);end
    side=cross(v,cfg.e3);if norm(side)<=1e-9,side=[1;0;0];else,side=side/norm(side);end
    bin=cross(v,side);if norm(bin)>1e-12,bin=bin/norm(bin);end
    sg=1-2*mod(id+io,2);
    off=sg*(.10+.10*mod(id+2*io,4))*side+.08*mod(id+io,3)*bin;
    obs(io).center=D(:,1)+cfg.sys.L_cable*nT+off;
    shape=SHAPES(1+mod(id+3*io-1,size(SHAPES,1)),:)';
    sc=SCALE_SET(1+mod(id+io-2,numel(SCALE_SET)));
    obs(io).radii=sc*shape;
    ang=[mod(29*id+37*io,180),-55+mod(17*id+23*io,110),...
         -70+mod(31*id+19*io,140)]*pi/180;
    obs(io).R=eul2rotm_local(ang);
    obs(io).S=obs(io).R*diag(obs(io).radii.^2)*obs(io).R';
end
end


function [es,ee]=f32_c6(P,c,D0,D1)
a=zeros(7,1);b=zeros(7,1);
for r=0:6
    a(r+1)=norm(eval_spline(c,P,0,r)-D0(:,r+1),inf);
    b(r+1)=norm(eval_spline(c,P,1,r)-D1(:,r+1),inf);
end
es=max(a);ee=max(b);
end


function f32_stat(name,x)
x=x(isfinite(x));if isempty(x),return;end
f101aa_silent_fprintf(' %-20s median=%8.3f  max=%8.3f ms\n',name,median(x),max(x));
end


