function r=f23_record_template()
r=struct('id',NaN,'group',"",'family',"",'sf',NaN,'tplan',NaN,'mult',NaN,'T',NaN,...
    'N',NaN,'K',NaN,'n_obs',NaN,'c6_start',NaN,'c6_end',NaN,...
    'n_bundle_added',0,'n_authority_reject',0,'qp_ok',false,'certified',false,...
    'min_g',NaN,'qp_ms',NaN,'cert_ms',NaN,'total_ms',NaN,'stop_reason',"");
end

function W=f23_unique_witnesses(H)
if isempty(H)
    W=H; return
end
keep=false(height(H),1); keys=strings(0,1); normals=zeros(0,3);
for i=1:height(H)
    if ~isfinite(H.span(i)) || ~isfinite(H.obs(i)) || ~all(isfinite([H.nx(i) H.ny(i) H.nz(i)])), continue; end
    n=[H.nx(i) H.ny(i) H.nz(i)]; if norm(n)<=1e-12, continue; end; n=n/norm(n);
    key=sprintf('%d_%d',H.span(i),H.obs(i));
    dup=false;
    for j=1:numel(keys)
        if keys(j)==key && dot(normals(j,:),n)>cosd(3), dup=true; break; end
    end
    if ~dup
        keep(i)=true; keys(end+1)=key; normals(end+1,:)=n; %#ok<AGROW>
    end
end
W=H(keep,:);
end

function row=f12_one_support(r,q,cfg,limits,obs,nom_fun,T0,N,opt,alpha,mult,maxCuts,tmission,room)
row=f12_row_template();
row.id=r.id; row.f9_class=r.class; row.group=r.group; row.family=r.family;
row.sf=r.sf; row.tplan=r.tplan; row.mult=mult; row.T=mult*T0;
row.speed_now=room.speed_now; row.min_uav_surface_clearance=room.min_uav_surface_clearance;
row.ttc_indicator=room.ttc_indicator; row.braking_distance_indicator=room.braking_distance_indicator;
if ~isfinite(row.T) || q.tplan+row.T>tmission
    row.horizon_ok=false; row.reason='HORIZON_OUTSIDE_MISSION'; return;
end
row.horizon_ok=true;
D0=nom_fun(q.tplan); D1=nom_fun(q.tplan+row.T); cfgN=cfg; cfgN.N_ctrl=N;
c=build_static_cache_boundary(cfgN,q.tplan,q.tplan+row.T,nom_fun,D0,D1,opt);
row.c6s=0; row.c6e=0;
for rr=0:6
    row.c6s=max(row.c6s,norm(eval_spline(c,c.Pbase,0,rr)-D0(:,rr+1),inf));
    row.c6e=max(row.c6e,norm(eval_spline(c,c.Pbase,1,rr)-D1(:,rr+1),inf));
end
row.c6_ok=(row.c6s<=opt.c6_tol && row.c6e<=opt.c6_tol);
if ~row.c6_ok, row.reason='C6_NUMERICAL_AUDIT_FAIL'; return; end

[Gmat,gvec,info]=build_coherent_guided_corridor(c,cfgN,obs,opt);
md=build_dyn_E(c); [Dmat,dvec]=dyn_E(md,limits,alpha);

row.screen=isfield(info,'authority_screen_pass') && info.authority_screen_pass;
row.G_constructed = row.screen && ~isempty(Gmat);
row.G_rows = size(Gmat,1);
row.D_rows = size(Dmat,1);

if isfield(info,'authority_fail_span'), row.authority_fail_span=info.authority_fail_span; end
if isfield(info,'authority_fail_obs'),  row.authority_fail_obs =info.authority_fail_obs;  end

% CRITICAL F25 SEMANTICS:
% An empty G returned after authority-screen failure is NOT a feasible G.
% Do not send it to the QP solver and do not call D-only feasibility "G+D".
if ~row.screen
    row.G=false;
    row.GD=false;
    row.D=false;

    if isfield(info,'authority_margin') && row.authority_fail_span>0 && row.authority_fail_obs>0
        am=squeeze(info.authority_margin(row.authority_fail_span,:,row.authority_fail_obs));
        row.authority_reachable_normals=nnz(am >= -opt.authority_tol);
        if any(isfinite(am))
            row.authority_best_margin=max(am(isfinite(am)));
        end
    end

    row.reason='G_NOT_CONSTRUCTED_AUTHORITY_SCREEN_FAIL';
    return;
end

% From here onward G really exists.
sg=p8r6_feas_online(c,Gmat,gvec,opt);
sd=p8r6_feas_online(c,Dmat,dvec,opt);
sgd=p8r6_feas_online(c,[Gmat;Dmat],[gvec;dvec],opt);
row.G=sg.flag>0;
row.D=sd.flag>0;
row.GD=sgd.flag>0;

if ~row.G
    row.reason='G_CONSTRUCTED_BUT_QP_INFEASIBLE'; return;
end
if ~row.GD
    row.reason='G_AND_D_CONSTRUCTED_BUT_QP_INFEASIBLE'; return;
end

% Actual feasible G+D candidate, even when the pre-screen says reject.
% This is diagnostic only; it is NOT used as an execution path.
P=apply_z(c,sgd.z);
cert=certify_candidate_global(P,c,cfgN,limits,obs,opt);
row.cert_pass=cert.pass; row.cert_g=cert.min_g_lower;
row.cert_dynamic=cert.dynamic_pass;
if ~row.cert_pass
    wd=f15_witness_crosscheck(P,c,cfgN,obs,info,cert,sgd.z,opt);
    fn=fieldnames(wd);
    for kk=1:numel(fn), row.(fn{kk})=wd.(fn{kk}); end
end
if row.cert_pass
    if row.screen, row.reason='SCREEN_AND_CERT_PASS';
    else, row.reason='SCREEN_FALSE_NEGATIVE_CERTIFIED'; end
    return;
end

% Apply the already-established rigorous witness cuts only as a diagnostic:
% no new algorithm and no relaxed threshold.
Ac=zeros(0,c.nz); bc=zeros(0,1); seen={};
for it=0:maxCuts
    sol=p8r6_feas_online(c,[Gmat;Dmat;Ac],[gvec;dvec;bc],opt);
    if sol.flag<=0, row.repair_reason='QP_INFEASIBLE_AFTER_CUT'; break; end
    P=apply_z(c,sol.z);
    cr=certify_candidate_global(P,c,cfgN,limits,obs,opt);
    row.repair_iterations=it+1; row.repair_g=cr.min_g_lower;
    if cr.pass
        row.repair_cert_pass=true; row.repair_reason='CERTIFIED_WITH_EXISTING_RIGOROUS_CUTS'; break;
    end
    if it==maxCuts, row.repair_reason='MAX_CUTS_REACHED'; break; end
    sp=cr.worst.span; o=cr.worst.obs; n=cr.worst.n; n=n/norm(n);
    key=sprintf('%d_%d_%.12g_%.12g_%.12g',sp,o,n(1),n(2),n(3));
    if any(strcmp(seen,key)), row.repair_reason='REPEATED_FAILED_WITNESS'; break; end
    [Aa,bb,rowAuth,~]=r8f8_rigorous_pair_cut(c,cfgN,obs(o),sp,n,opt);
    if rowAuth < -10*opt.authority_tol
        row.repair_reason='CUT_OUTSIDE_C6_BOX_AUTHORITY'; break;
    end
    Ac=[Ac;Aa]; bc=[bc;bb]; seen{end+1}=key; %#ok<AGROW>
    row.repair_cuts=numel(seen);
end
if row.repair_cert_pass
    if row.screen, row.reason='CERTIFIED_AFTER_EXISTING_CUTS';
    else, row.reason='SCREEN_FALSE_NEGATIVE_CERTIFIED_AFTER_CUTS'; end
else
    row.reason='GD_FEASIBLE_BUT_GLOBAL_CERT_REJECT';
end
end


function wd=f15_witness_crosscheck(P,c,cfg,obs,info,cert,z,opt)
% Exact decomposition of the unchanged certificate's worst witness, plus
% correspondence to the candidate-generator G constraint for the same pair.
sp=cert.worst.span; o=cert.worst.obs; n=cert.worst.n(:); n=n/norm(n);
ua=c.spans(sp,1); ub=c.spans(sp,2);
Pbez=span_bezier_points(c,P,ua,ub,0);
Abez=span_bezier_points(c,P,ua,ub,2);
Wbez=Abez+repmat(cfg.g_acc*cfg.e3,1,size(Abez,2));
Mlb=compute_certified_tension_lower_bound_cols(Wbez);
p_low=min(n'*Pbez); wmin=min(n'*Wbez); Mmax=max(vecnorm(Wbez,2,1));
if Mmax<=1e-12
    qlow=-1;
elseif wmin>=0
    qlow=wmin/Mmax;
elseif Mlb>0
    qlow=max(-1,wmin/Mlb);
else
    qlow=-1;
end
Dup=delta_sep_from_q_lower(qlow,cfg.sys);
h=obstacle_support(obs(o),n);
vals=[cfg.sys.R_payload, cfg.sys.R_uav-cfg.sys.L_cable*qlow, ...
      cfg.sys.R_cable+max(0,-cfg.sys.L_cable*qlow)];
[~,ic]=max(vals); nm={'PAYLOAD','UAV','CABLE'};

pairActive=false; ang=NaN; qpmarg=NaN; qpnear=false; frozenDelta=NaN;
if sp<=size(info.active,1) && o<=size(info.active,2) && info.active(sp,o)
    pairActive=true;
    nq=info.normal(:,sp,o); nq=nq/norm(nq);
    ang=acosd(max(-1,min(1,n'*nq)));
    um=mean([ua ub]); a0=eval_spline(c,c.Pbase,um,2);
    w0=a0+cfg.g_acc*cfg.e3;
    if norm(w0)<=opt.a_net_min, nT0=cfg.e3; else, nT0=w0/norm(w0); end
    frozenDelta=delta_sep_exact(nq,nT0,cfg.sys);
    rhs=obstacle_support(obs(o),nq)+frozenDelta+cfg.d_margin+opt.guide_extra;
    qpmarg=min(nq'*Pbez-rhs);
    qpnear=abs(qpmarg)<=1e-6;
end

[~,~,rowAuth,~]=r8f8_rigorous_pair_cut(c,cfg,obs(o),sp,n,opt);
boxOK=rowAuth>=-10*opt.authority_tol;

% Descriptive hierarchy, not a theorem about physical impossibility.
if ~pairActive
    cls='PAIR_MISSING_FROM_G';
elseif ~boxOK
    cls='CERT_WITNESS_OUTSIDE_C6_BOX_AUTHORITY';
elseif isfinite(ang) && ang>20
    cls='QP_CERT_NORMAL_MISMATCH_GT20DEG';
elseif isfinite(ang) && ang>5
    cls='QP_CERT_NORMAL_MISMATCH_5TO20DEG';
elseif ~qpnear
    cls='SAME_PAIR_QP_ROW_INACTIVE';
elseif ic==2 || ic==3
    cls=['CABLE_OR_UAV_EXTENT_DOMINATED_' nm{ic}];
else
    cls='POSITION_SUPPORT_OR_OTHER_GAP';
end

wd=struct('cert_worst_span',sp,'cert_worst_obs',o,'cert_p_low',p_low, ...
    'cert_q_lower',qlow,'cert_delta_up',Dup,'cert_h_obs',h, ...
    'cert_margin',cfg.d_margin,'cert_M_LB',Mlb,'cert_delta_component',nm{ic}, ...
    'qp_pair_active',pairActive,'qp_normal_angle_deg',ang, ...
    'qp_pair_min_margin',qpmarg,'qp_pair_near_active',qpnear, ...
    'witness_cut_authority',rowAuth,'witness_cut_feasible_box',boxOK, ...
    'frozen_qp_delta',frozenDelta,'delta_gap_vs_qp',Dup-frozenDelta, ...
    'crosscheck_class',cls);
end

function room=f12_avoidance_room(nom_fun,obs,cfg,limits,tplan,tmission)
D=nom_fun(tplan); pL=D(:,1); vL=D(:,2); aL=D(:,3);
W=aL+cfg.g_acc*cfg.e3;
if norm(W)<1e-12, nT=cfg.e3; else, nT=W/norm(W); end
pQ=pL+cfg.sys.L_cable*nT;
speed=norm(vL);
cp=inf; cq=inf; maxClosing=0; bestTTC=inf;
for o=1:numel(obs)
    rp=f12_ellipsoid_radial_radius(obs(o),pL-obs(o).center);
    rq=f12_ellipsoid_radial_radius(obs(o),pQ-obs(o).center);
    dp=norm(pL-obs(o).center)-rp-cfg.sys.R_payload-cfg.d_margin;
    dq=norm(pQ-obs(o).center)-rq-cfg.sys.R_uav-cfg.d_margin;
    cp=min(cp,dp); cq=min(cq,dq);
    e=obs(o).center-pQ; de=norm(e);
    if de>1e-12, closing=max(0,dot(vL,e/de)); else, closing=inf; end
    maxClosing=max(maxClosing,closing);
    if closing>1e-12, bestTTC=min(bestTTC,max(0,dq)/closing); end
end
% Simple acceleration-only braking indicator. It is intentionally NOT
% labelled a proof because jerk, cable dynamics and 3-D avoidance matter.
if limits.a_max>0, db=speed^2/(2*limits.a_max); else, db=inf; end
room=struct('speed_now',speed,'remaining_mission',tmission-tplan, ...
    'min_payload_surface_clearance',cp,'min_uav_surface_clearance',cq, ...
    'max_closing_speed',maxClosing,'ttc_indicator',bestTTC, ...
    'braking_distance_indicator',db,'clearance_over_braking',cq/max(db,eps));
end

function rr=f12_ellipsoid_radial_radius(o,d)
nd=norm(d); if nd<1e-12, rr=max(o.radii); return; end
u=d/nd;
if isfield(o,'S')
    rr=1/sqrt(max(u'*(o.S\u),eps));
elseif isfield(o,'radii') && isfield(o,'R')
    ul=o.R'*u; rr=1/sqrt(sum((ul./o.radii).^2));
else
    rr=0;
end
end

function cls=f12_classify_case(r,rows,room)
ok=[rows.c6_ok];
if ~any(ok)
    if all(~[rows.horizon_ok]), cls='NO_MISSION_HORIZON_FOR_SUPPORTED_T';
    else, cls='C6_CONSTRUCTION_NUMERICAL_LIMIT'; end
    return;
end
if any([rows.cert_pass] & ok)
    if strcmp(r.class,'NO_SCREENED_T')
        cls='SCREEN_FALSE_NEGATIVE_CERTIFIED';
    elseif strcmp(r.class,'ORIGINAL_GD_INFEASIBLE')
        cls='T_SELECTION_FALSE_NEGATIVE_CERTIFIED';
    else
        cls='ALTERNATIVE_SUPPORTED_T_CERTIFIED';
    end
    return;
end
if any([rows.repair_cert_pass] & ok)
    if strcmp(r.class,'NO_SCREENED_T')
        cls='SCREEN_FALSE_NEGATIVE_REPAIR_CERTIFIED';
    elseif strcmp(r.class,'ORIGINAL_GD_INFEASIBLE')
        cls='T_SELECTION_REPAIR_CERTIFIED';
    else
        cls='ALTERNATIVE_T_REPAIR_CERTIFIED';
    end
    return;
end
if any([rows.GD] & ok)
    cls='GD_EXISTS_BUT_CERTIFICATE_NOT_REACHED';
elseif room.ttc_indicator<1 || room.clearance_over_braking<1
    cls='LOW_AVOIDANCE_ROOM_AND_NO_GD_IN_TESTED_SUPPORT';
else
    cls='NO_GD_IN_TESTED_SUPPORT';
end
end

