function f12_print_summary(CASE,ROW)
f101aa_silent_fprintf('\n================================================================================\n');
f101aa_silent_fprintf('[F12 REJECT-ONLY DECISION-STAGE SUMMARY]\n');
f101aa_silent_fprintf('cases analyzed: %d\n',numel(CASE));
U=unique({CASE.stage_class},'stable');
for i=1:numel(U), f101aa_silent_fprintf(' %-48s : %3d\n',U{i},sum(strcmp({CASE.stage_class},U{i}))); end
f101aa_silent_fprintf('\nSupport-level facts (diagnostic, not execution):\n');
f101aa_silent_fprintf(' C6-valid support rows                         : %d / %d\n',sum([ROW.c6_ok]),numel(ROW));
f101aa_silent_fprintf(' authority-screen pass rows                   : %d\n',sum([ROW.screen]&[ROW.c6_ok]));
f101aa_silent_fprintf(' G+D feasible rows                            : %d\n',sum([ROW.GD]&[ROW.c6_ok]));
f101aa_silent_fprintf(' unchanged-global-certificate pass rows       : %d\n',sum([ROW.cert_pass]&[ROW.c6_ok]));
f101aa_silent_fprintf(' existing-cut certificate pass rows           : %d\n',sum([ROW.repair_cert_pass]&[ROW.c6_ok]));
f101aa_silent_fprintf(' screen=0 but unchanged certificate C=1 rows  : %d\n',sum(~[ROW.screen]&[ROW.cert_pass]&[ROW.c6_ok]));
f101aa_silent_fprintf('\nAvoidance-room indicators (NOT impossibility proofs):\n');
f101aa_silent_fprintf(' TTC indicator <1 s cases                     : %d\n',sum([CASE.ttc_indicator]<1));
f101aa_silent_fprintf(' clearance/braking-distance indicator <1      : %d\n',sum([CASE.clearance_over_braking]<1));
f101aa_silent_fprintf('\nInterpretation rule:\n');
f101aa_silent_fprintf(' A certified alternative proves the F9 reject was planner/selection conservatism\n');
f101aa_silent_fprintf(' for that tested case. Absence of one does NOT prove physical impossibility.\n');
f101aa_silent_fprintf('================================================================================\n');
f101aa_silent_fprintf('CSV written: Phase9CR8F14_case_forensic.csv\n');
f101aa_silent_fprintf('CSV written: Phase9CR8F14_support_forensic.csv\n');
end

function q=f9_case_template()
q=struct('id',0,'group','','family','STRAIGHT','sf',1,'tplan',20,'sys',[1 1 1 1],'sys_name','BASE','limit_scale',[1 1 1],'limit_name','BASE','margin_scale',1,'og',[1 1 1 1 35 15 -20],'obs_name','BASE_ROTATED','n_obs',2,'obs_layout','FROZEN_TWO');
end
function r=f9_record_template()
r=struct('id',0,'group','','family','','sf',NaN,'tplan',NaN,'sys',[NaN NaN NaN NaN],'limit_scale',[NaN NaN NaN],'margin_scale',NaN,'obs_name','','n_obs',0,'obs_layout','','T0',NaN,'N',0,'selected_mult',NaN,'selection_score',-inf,'n_screen_pass',0,'screen',false,'original_GD',false,'original_C',false,'original_g',-inf,'final_GD',false,'final_C',false,'final_g',-inf,'n_cuts',0,'n_iterations',0,'total_time',0,'qp_time',0,'cert_time',0,'cut_time',0,'c6s',inf,'c6e',inf,'v',NaN,'a',NaN,'j',NaN,'dynamic_pass',false,'runtime_pass',false,'failure_reason','','class','UNRUN','cut_authority',zeros(1,0));
end
function r=f9_merge(r,q,target)
F={'screen','original_GD','original_C','original_g','final_GD','final_C','final_g','n_cuts','n_iterations','total_time','qp_time','cert_time','cut_time','c6s','c6e','v','a','j','dynamic_pass','failure_reason'};
for i=1:numel(F),r.(F{i})=q.(F{i});end; r.cut_authority=[q.cuts.row_authority]; r.runtime_pass=q.total_time<target;
if q.final_C, if r.runtime_pass,r.class='CERTIFIED_LT3S';else,r.class='CERTIFIED_OVER3S';end
elseif ~q.screen,r.class='AUTHORITY_SCREEN_REJECT'; elseif ~q.original_GD && q.n_cuts==0,r.class='ORIGINAL_GD_INFEASIBLE';
elseif strcmp(q.failure_reason,'RIGOROUS_WORST-CABLE_CUT_OUTSIDE_C6_BOX_AUTHORITY'),r.class='CUT_AUTHORITY_REJECT';
elseif strcmp(q.failure_reason,'QP_INFEASIBLE_AFTER_RIGOROUS_CUTS'),r.class='REPAIRED_QP_INFEASIBLE';
elseif strcmp(q.failure_reason,'REPEATED_FAILED_WITNESS'),r.class='REPEATED_FAILED_WITNESS'; elseif strcmp(q.failure_reason,'MAX_CUTS_REACHED'),r.class='MAX_CUTS_REACHED'; else,r.class=['CERT_REJECT_' q.failure_reason];end
end
function f9_summary(R,target)
C=[R.final_C]; RT=[R.runtime_pass]; O=[R.original_C]; f101aa_silent_fprintf('\n[F9 GLOBAL SUMMARY]\n'); f101aa_silent_fprintf('total cases                 : %d\n',numel(R)); f101aa_silent_fprintf('certified                   : %d/%d = %.1f%%\n',sum(C),numel(R),100*mean(C)); f101aa_silent_fprintf('original certified          : %d/%d = %.1f%%\n',sum(O),numel(R),100*mean(O)); f101aa_silent_fprintf('rescued by rigorous cuts    : %d\n',sum(C&~O)); f101aa_silent_fprintf('certified AND < %.1f s      : %d/%d\n',target,sum(C&RT),numel(R));
if any(C), f101aa_silent_fprintf('certified min margin g      : %+.6f\n',min([R(C).final_g])); f101aa_silent_fprintf('runtime certified mean/max  : %.3f / %.3f s\n',mean([R(C).total_time]),max([R(C).total_time])); f101aa_silent_fprintf('max cuts / iterations       : %d / %d\n',max([R(C).n_cuts]),max([R(C).n_iterations])); end
G=unique({R.group},'stable'); f101aa_silent_fprintf('\nBy experiment group:\n'); for i=1:numel(G),ix=strcmp({R.group},G{i});f101aa_silent_fprintf(' %-16s certified %3d/%3d (%5.1f%%), <3s %3d/%3d\n',G{i},sum(C(ix)),sum(ix),100*sum(C(ix))/sum(ix),sum(C(ix)&RT(ix)),sum(ix));end
CL=unique({R.class}); f101aa_silent_fprintf('\nStatus decomposition:\n');for i=1:numel(CL),f101aa_silent_fprintf(' %-46s : %d\n',CL{i},sum(strcmp({R.class},CL{i})));end
% factor summaries useful for feasibility-envelope plots
f101aa_silent_fprintf('\nSpeed scale envelope:\n'); V=unique([R.sf]); for v=V,ix=abs([R.sf]-v)<1e-12;f101aa_silent_fprintf(' sf=%4.2f : %3d/%3d certified\n',v,sum(C(ix)),sum(ix));end
f101aa_silent_fprintf('\nDetection/replan time envelope:\n'); V=unique([R.tplan]); for v=V,ix=abs([R.tplan]-v)<1e-12;f101aa_silent_fprintf(' tplan=%4.0f : %3d/%3d certified\n',v,sum(C(ix)),sum(ix));end
ixJ=strcmp({R.group},'J_MULTI_OBS');
if any(ixJ)
 f101aa_silent_fprintf('\nExplicit simultaneous multi-obstacle envelope:\n');
 NV=unique([R(ixJ).n_obs]); for nv=NV,ix=ixJ & ([R.n_obs]==nv);f101aa_silent_fprintf(' nObs=%2d : %3d/%3d certified, mean/max cuts %.2f/%d, mean/max runtime %.3f/%.3f s\n',nv,sum(C(ix)),sum(ix),mean([R(ix).n_cuts]),max([R(ix).n_cuts]),mean([R(ix).total_time]),max([R(ix).total_time]));end
 LV=unique({R(ixJ).obs_layout},'stable'); for ii=1:numel(LV),ix=ixJ & strcmp({R.obs_layout},LV{ii});f101aa_silent_fprintf(' layout=%-12s : %3d/%3d certified\n',LV{ii},sum(C(ix)),sum(ix));end
end
end

function result = f9_embedded_f8_reference()
% =========================================================================
% Phase 9C-R8-F8: 48-CASE GENERALIZATION REGRESSION OF F7 REPAIR
%
% PURPOSE
%   Generalization test of the unchanged F7 selective rigorous separator-cut
%   planner over the established 8 system geometries x 6 obstacle geometries.
%
% IMPORTANT
%   - fixed-length, no-sag/no-bending cable model;
%   - no obstacle/system sphere approximation;
%   - no sampled-time safety proof;
%   - C6, dynamics, correction box and global certificate are unchanged;
%   - final success requires the unchanged continuous-time certificate C=1;
%   - runtime target (<3 s) is reported separately from mathematical safety.
%
% HORIZON POLICY
%   Deterministic ONE-SHOT selection from SUPPORT=[1 1.15 1.35 1.65 2 2.4].
%   For every T, only the PRE-QP authority screen is evaluated.  The selected
%   T is the screen-passing candidate with maximum selected-row authority
%   score.  Exactly ONE F7 repair run is then performed.  No certificate is
%   inspected during horizon selection, so there is no post-hoc best-T search.
% =========================================================================
clc;
scenario=setup_benchmark();
[cfg0,limits,obs0,~,~,~]=unpack_scenario(scenario);
opt=setup_options(); alpha=1/sqrt(3);
opt.coherent_lambda=1.25; opt.coherent_flip_cos=-0.15;
opt.coherent_topK=min(48,opt.separator_grid_N);
opt.compat_enable=true; opt.compat_min_dot=0.05; opt.compat_lambda=1.00;
opt.geom_guide_enable=true; opt.geom_guide_lambda=0.85;
opt.geom_guide_min_dot=0.35; opt.quality_enable=false;
opt.authority_tol=1e-10; opt.authority_lambda=0.15;
p9cf_preflight(cfg0,limits,opt);
p9cf_runtime_smoke(cfg0,limits,obs0,opt,alpha);

SYS=[.70 .70 .70 .70;1 1 1 1;1.30 1 1 1;1 1.30 1 1;1 1 1.50 1; ...
     1 1 1 1.35;1.25 1.25 1.25 1.25;1.50 1.30 1.50 1.40];
SYSNAME={'SMALL_ALL','BASE','BIG_PAYLOAD','BIG_UAV','THICK_CABLE','LONG_CABLE','BIG_ALL','XL_MIXED'};
OG=[.70 1 1 1 0 0 0;1 1 1 1 35 15 -20;1.20 1.50 .70 1 70 -25 30; ...
    1.30 .65 1.60 .85 115 35 -40;1.10 .75 .80 1.70 155 -35 55; ...
    1.35 1.70 .60 .70 205 20 65];
OGNAME={'SMALL_SPHEROID','BASE_ROTATED','LONG_X','LONG_Y','TALL_Z','FLAT_LONG'};
FAM={'STRAIGHT','CIRCLE','HELIX','S_CURVE','CLIMB_TURN'};
SF=[.75 1.00 1.25];
SUPPORT=[1.00 1.15 1.35 1.65 2.00 2.40];
MAX_CUTS=12; RUNTIME_TARGET=3.0; tplan=20; tmission=72;

empty=f8_empty_record(); REC=repmat(empty,1,size(SYS,1)*size(OG,1)); icase=0;
f101aa_silent_fprintf('\n================================================================================\n');
f101aa_silent_fprintf(' Phase 9C-R8-F8: 48-CASE GENERALIZATION REGRESSION\n');
f101aa_silent_fprintf(' one-shot authority-selected T | F7 rigorous cuts | global certificate unchanged\n');
f101aa_silent_fprintf(' fixed-length/no-sag cable | safety and <3 s runtime reported separately\n');
f101aa_silent_fprintf('================================================================================\n');
f101aa_silent_fprintf(' id | system          obstacle        family     sf | T/T0 | O/R | cuts it | g_final   | time ms | class\n');

for is=1:size(SYS,1)
  for io=1:size(OG,1)
    icase=icase+1; fam=FAM{mod(icase-1,numel(FAM))+1};
    sf=SF(mod(floor((icase-1)/numel(FAM)),numel(SF))+1);
    nom_fun=@(t) p9a_nominal(t,fam,sf);
    cfg=cfg0;
    cfg.sys.R_payload=cfg0.sys.R_payload*SYS(is,1);
    cfg.sys.R_uav=cfg0.sys.R_uav*SYS(is,2);
    cfg.sys.R_cable=cfg0.sys.R_cable*SYS(is,3);
    cfg.sys.L_cable=cfg0.sys.L_cable*SYS(is,4);
    obs=p9cf_make_obstacles(obs0,nom_fun,cfg,OG(io,:),icase);
    D0=nom_fun(tplan); risk=audit_nominal_risk_window(nom_fun,obs,cfg,opt,tplan,tmission,.04);
    H=p6_predict_horizon(tplan,D0,risk,obs,nom_fun,cfg,limits,opt); T0=H.T_plan;
    N=max(30,min(42,ceil(2*T0))); if mod(N,2),N=N+1; end

    [mult,selScore,nScreen]=f8_select_one_shot_T(cfg,obs,nom_fun,tplan,T0,N,opt,SUPPORT,tmission);
    r=empty; r.id=icase; r.is=is; r.io=io; r.sys=SYSNAME{is}; r.obs=OGNAME{io};
    r.family=fam; r.sf=sf; r.T0=T0; r.N=N; r.selected_mult=mult;
    r.selection_score=selScore; r.n_screen_pass=nScreen;
    if isnan(mult)
        r.class='NO_SCREENED_T'; REC(icase)=r;
    else
        q=r8f8_probe(cfg,limits,obs,nom_fun,tplan,mult*T0,N,opt,alpha,MAX_CUTS);
        r=f8_merge_probe(r,q,RUNTIME_TARGET); REC(icase)=r;
    end
    rr=REC(icase);
    f101aa_silent_fprintf('%3d | %-15s %-15s %-10s %.2f | %4.2f | %d/%d | %2d %2d | %+9.5f | %7.1f | %s\n', ...
        rr.id,rr.sys,rr.obs,rr.family,rr.sf,rr.selected_mult,rr.original_C,rr.final_C, ...
        rr.n_cuts,rr.n_iterations,rr.final_g,1e3*rr.total_time,rr.class);
  end
end

C=[REC.final_C]; RT=[REC.runtime_pass]; OC=[REC.original_C]; repaired=C & ~OC;
f101aa_silent_fprintf('\n================================================================================\n');
f101aa_silent_fprintf('[F8 SUMMARY]\n');
f101aa_silent_fprintf(' certified after F7 repair : %d/%d = %.1f%%\n',sum(C),numel(C),100*mean(C));
f101aa_silent_fprintf(' original one-shot certified: %d/%d = %.1f%%\n',sum(OC),numel(OC),100*mean(OC));
f101aa_silent_fprintf(' rescued by rigorous cuts   : %d\n',sum(repaired));
f101aa_silent_fprintf(' certified AND < %.1f s     : %d/%d = %.1f%%\n',RUNTIME_TARGET,sum(C&RT),sum(C),100*sum(C&RT)/max(1,sum(C)));
if any(C)
  f101aa_silent_fprintf(' certified min g            : %+.6f\n',min([REC(C).final_g]));
  f101aa_silent_fprintf(' certified max cuts/iters   : %d / %d\n',max([REC(C).n_cuts]),max([REC(C).n_iterations]));
  f101aa_silent_fprintf(' certified runtime mean/max : %.3f / %.3f s\n',mean([REC(C).total_time]),max([REC(C).total_time]));
  f101aa_silent_fprintf(' certified max C6 start/end : %.3e / %.3e\n',max([REC(C).c6s]),max([REC(C).c6e]));
  f101aa_silent_fprintf(' certified max v/a/j        : %.3f / %.3f / %.3f\n',max([REC(C).v]),max([REC(C).a]),max([REC(C).j]));
end
classes=unique({REC.class});
f101aa_silent_fprintf('\nFailure/status decomposition:\n');
for k=1:numel(classes), f101aa_silent_fprintf(' %-46s : %d\n',classes{k},sum(strcmp({REC.class},classes{k}))); end
f101aa_silent_fprintf('\nBy system geometry:\n');
for is=1:numel(SYSNAME), ix=[REC.is]==is; f101aa_silent_fprintf(' %-15s certified %d/%d, <3s %d/%d\n',SYSNAME{is},sum(C(ix)),sum(ix),sum(C(ix)&RT(ix)),sum(ix)); end
f101aa_silent_fprintf('\nBy obstacle geometry:\n');
for io=1:numel(OGNAME), ix=[REC.io]==io; f101aa_silent_fprintf(' %-15s certified %d/%d, <3s %d/%d\n',OGNAME{io},sum(C(ix)),sum(ix),sum(C(ix)&RT(ix)),sum(ix)); end

% Hard invariants: no unsafe result may be counted as certified.
for k=1:numel(REC)
  r=REC(k);
  if r.final_C
    if ~r.final_GD || r.final_g < -opt.cert_tol || r.c6s>opt.c6_tol || r.c6e>opt.c6_tol
      error('F8 invariant failure in case %d: invalid certified result.',r.id);
    end
    if ~r.dynamic_pass, error('F8 invariant failure in case %d: certified but dynamic gate failed.',r.id); end
  end
  for j=1:numel(r.cut_authority)
    if r.cut_authority(j)<-10*opt.authority_tol
      error('F8 invariant failure in case %d: infeasible rigorous cut was used.',r.id);
    end
  end
end
f101aa_silent_fprintf('\nHard C6/dynamic/cut/global-certificate invariants: PASS\n');
f101aa_silent_fprintf('NOTE: <3 s is an empirical runtime target, not part of the safety theorem.\n');
f101aa_silent_fprintf('================================================================================\n');
result=struct('records',REC,'support',SUPPORT,'max_cuts',MAX_CUTS, ...
    'runtime_target',RUNTIME_TARGET,'certified_count',sum(C), ...
    'original_certified_count',sum(OC),'rescued_count',sum(repaired), ...
    'certified_runtime_count',sum(C&RT));
end

function r=f8_empty_record()
r=struct('id',0,'is',0,'io',0,'sys','','obs','','family','','sf',NaN,'T0',NaN,'N',0, ...
 'selected_mult',NaN,'selection_score',-inf,'n_screen_pass',0,'screen',false, ...
 'original_GD',false,'original_C',false,'original_g',-inf,'final_GD',false,'final_C',false, ...
 'final_g',-inf,'n_cuts',0,'n_iterations',0,'total_time',0,'qp_time',0,'cert_time',0,'cut_time',0, ...
 'c6s',inf,'c6e',inf,'v',NaN,'a',NaN,'j',NaN,'dynamic_pass',false,'runtime_pass',false, ...
 'failure_reason','','class','UNRUN','cut_authority',zeros(1,0));
end

function [bestMult,bestScore,nPass]=f8_select_one_shot_T(cfg,obs,nom_fun,tplan,T0,N,opt,support,tmission)
bestMult=NaN; bestScore=-inf; nPass=0;
for k=1:numel(support)
  mult=support(k); T=mult*T0; if tplan+T>tmission, continue; end
  cfgN=cfg; cfgN.N_ctrl=N; D0=nom_fun(tplan); D1=nom_fun(tplan+T);
  c=build_static_cache_boundary(cfgN,tplan,tplan+T,nom_fun,D0,D1,opt);
  [~,~,info]=build_coherent_guided_corridor(c,cfgN,obs,opt);
  if ~(isfield(info,'authority_screen_pass') && info.authority_screen_pass), continue; end
  nPass=nPass+1; score=inf;
  if any(info.active(:))
    dirs=fibonacci_sphere(opt.separator_grid_N);
    for sp=1:c.nspans
      for o=1:numel(obs)
        if ~info.active(sp,o), continue; end
        n=info.normal(:,sp,o); [~,kk]=max(n'*dirs);
        score=min(score,info.authority_margin(sp,kk,o));
      end
    end
  end
  if isinf(score), score=0; end
  if score>bestScore+1e-12 || (abs(score-bestScore)<=1e-12 && (isnan(bestMult)||mult<bestMult))
    bestScore=score; bestMult=mult;
  end
end
end

function r=f8_merge_probe(r,q,target)
fields={'screen','original_GD','original_C','original_g','final_GD','final_C','final_g', ...
 'n_cuts','n_iterations','total_time','qp_time','cert_time','cut_time','c6s','c6e','v','a','j','dynamic_pass','failure_reason'};
for k=1:numel(fields), r.(fields{k})=q.(fields{k}); end
r.cut_authority=[q.cuts.row_authority]; r.runtime_pass=q.total_time<target;
if q.final_C
  if r.runtime_pass, r.class='CERTIFIED_LT3S'; else, r.class='CERTIFIED_RUNTIME_OVER_3S'; end
elseif ~q.screen, r.class='AUTHORITY_SCREEN_REJECT';
elseif ~q.original_GD && q.n_cuts==0, r.class='ORIGINAL_GD_INFEASIBLE';
elseif strcmp(q.failure_reason,'RIGOROUS_WORST-CABLE_CUT_OUTSIDE_C6_BOX_AUTHORITY'), r.class='CUT_AUTHORITY_REJECT';
elseif strcmp(q.failure_reason,'QP_INFEASIBLE_AFTER_RIGOROUS_CUTS'), r.class='REPAIRED_QP_INFEASIBLE';
elseif strcmp(q.failure_reason,'REPEATED_FAILED_WITNESS'), r.class='REPEATED_FAILED_WITNESS';
elseif strcmp(q.failure_reason,'MAX_CUTS_REACHED'), r.class='MAX_CUTS_REACHED';
else, r.class=['CERT_REJECT_' q.failure_reason]; end
end

function r=r8f8_probe(cfg,limits,obs,nom_fun,tplan,T,N,opt,alpha,maxCuts)
D0=nom_fun(tplan); D1=nom_fun(tplan+T); cfgN=cfg; cfgN.N_ctrl=N;
c=build_static_cache_boundary(cfgN,tplan,tplan+T,nom_fun,D0,D1,opt);
[Gmat,gvec,info]=build_coherent_guided_corridor(c,cfgN,obs,opt);
md=build_dyn_E(c); [Dmat,dvec]=dyn_E(md,limits,alpha);
emptyCut=struct('span',0,'obs',0,'pre_g',NaN,'n',[NaN;NaN;NaN],'row_authority',NaN,'delta_max',NaN);
r=struct('screen',false,'original_GD',false,'original_C',false,'original_g',-inf, ...
 'final_GD',false,'final_C',false,'final_g',-inf,'n_cuts',0,'n_iterations',0, ...
 'cuts',repmat(emptyCut,1,0),'total_time',0,'qp_time',0,'cert_time',0,'cut_time',0, ...
 'c6s',inf,'c6e',inf,'v',NaN,'a',NaN,'j',NaN,'dynamic_pass',false,'failure_reason','');
r.screen=isfield(info,'authority_screen_pass') && info.authority_screen_pass;
if ~r.screen, r.failure_reason='ORIGINAL_AUTHORITY_SCREEN_REJECT'; return; end
Ac=zeros(0,c.nz); bc=zeros(0,1); seen={}; totalT=tic; P=[]; cert=[];
for it=0:maxCuts
  r.n_iterations=it+1; tq=tic;
  sol=p8r6_feas_online(c,[Gmat;Dmat;Ac],[gvec;dvec;bc],opt); r.qp_time=r.qp_time+toc(tq);
  if sol.flag<=0
    if it==0, r.original_GD=false; end
    r.final_GD=false; r.failure_reason='QP_INFEASIBLE_AFTER_RIGOROUS_CUTS'; break;
  end
  if it==0, r.original_GD=true; end
  r.final_GD=true; P=apply_z(c,sol.z); tc=tic;
  cert=certify_candidate_global(P,c,cfgN,limits,obs,opt); r.cert_time=r.cert_time+toc(tc);
  if it==0, r.original_C=cert.pass; r.original_g=cert.min_g_lower; end
  r.final_C=cert.pass; r.final_g=cert.min_g_lower;
  if cert.pass, r.failure_reason=''; break; end
  if it==maxCuts, r.failure_reason='MAX_CUTS_REACHED'; break; end
  sp=cert.worst.span; o=cert.worst.obs; n=cert.worst.n; n=n/norm(n);
  key=sprintf('%d_%d_%.12g_%.12g_%.12g',sp,o,n(1),n(2),n(3));
  if any(strcmp(seen,key)), r.failure_reason='REPEATED_FAILED_WITNESS'; break; end
  tb=tic; [Aa,bb,rowAuth,Dmax]=r8f8_rigorous_pair_cut(c,cfgN,obs(o),sp,n,opt); r.cut_time=r.cut_time+toc(tb);
  if rowAuth < -10*opt.authority_tol, r.failure_reason='RIGOROUS_WORST-CABLE_CUT_OUTSIDE_C6_BOX_AUTHORITY'; break; end
  Ac=[Ac;Aa]; bc=[bc;bb]; seen{end+1}=key; %#ok<AGROW>
  q=emptyCut; q.span=sp; q.obs=o; q.pre_g=cert.min_g_lower; q.n=n; q.row_authority=rowAuth; q.delta_max=Dmax;
  r.cuts(end+1)=q; r.n_cuts=numel(r.cuts); %#ok<AGROW>
end
r.total_time=toc(totalT);
if r.final_GD && ~isempty(P)
  r.c6s=0; r.c6e=0;
  for rr=0:6
    r.c6s=max(r.c6s,norm(eval_spline(c,P,0,rr)-D0(:,rr+1),inf));
    r.c6e=max(r.c6e,norm(eval_spline(c,P,1,rr)-D1(:,rr+1),inf));
  end
  if ~isempty(cert)
    r.v=cert.v_bound; r.a=cert.a_bound; r.j=cert.j_bound; r.dynamic_pass=cert.dynamic_pass;
  end
end
end

function [A,b,rowAuthority,Dmax]=r8f8_rigorous_pair_cut(c,cfg,ob,sp,n,opt)
n=n/norm(n); Dmax=delta_sep_from_q_lower(-1,cfg.sys);
rhs=obstacle_support(ob,n)+Dmax+cfg.d_margin; B0=c.B0{sp}; Bz=c.Bz{sp};
A=zeros(c.p+1,c.nz); b=zeros(c.p+1,1); rowAuthority=inf;
for j=1:c.p+1
  A(j,:)=-n'*Bz(:,:,j); b(j)=n'*B0(:,j)-rhs;
  rowAuthority=min(rowAuthority,b(j)+opt.box_z_max*sum(abs(A(j,:))));
end
end

% ===== Frozen F6/R8 helper chain retained below =====
function result = test_C6_BSPLINE_PHASE9CR8F6_THEOREM_CRITICAL_PAIR_PRESCREEN()
% =========================================================================
% Phase 9C-R8-F6: THEOREM-BASED CRITICAL-PAIR PRE-QP SCREEN
%
% PURPOSE
%   Before solving the correction QP, classify EVERY span x obstacle pair
%   using rigorous bounds over the frozen C6 correction box |z_i|<=zmax.
%
% For a fixed unit separator n and Bezier point j,
%   B_j(z)=B0_j+Bz_j z.
% Hence exactly over the box:
%   min_z n'B_j(z) = n'B0_j-zmax*||n'Bz_j||_1,
%   max_z n'B_j(z) = n'B0_j+zmax*||n'Bz_j||_1.
%
% ROBUST_SAFE witness:
%   gROB(n)=min_j min_z n'B_j(z) - Delta(q=-1)-h_O(n)-d_margin.
%   If max_n gROB(n)>=0, one fixed n proves continuous-time separation for
%   EVERY z in the box, regardless of cable attitude. This pair need not be
%   constrained for safety by the candidate QP.
%
% GRID_IMPOSSIBLE witness (finite separator set only):
%   gOPT(n)=min_j max_z n'B_j(z) - Delta(q=+1)-h_O(n)-d_margin.
%   For any z, min_j n'B_j(z) <= min_j max_z n'B_j(z), while Delta(q)>=
%   Delta(q=+1). Thus gOPT is an optimistic upper bound for this n.
%   If max over the TESTED separator grid is <0, no tested n can certify the
%   pair anywhere in the box, even before dynamic constraints are imposed.
%   This is NOT a proof over all n on S^2.
%
% Otherwise the pair is CRITICAL and must be handled by candidate generation
% / separator logic and finally by the unchanged global certificate.
%
% IMPORTANT
%   - no obstacle sphere approximation;
%   - no full suspended-system sphere;
%   - no sampled-time collision proof;
%   - no C6/QP/certificate threshold is weakened;
%   - final execution gate remains certify_candidate_global().
% =========================================================================
clc;
scenario=setup_benchmark();
[cfg0,limits,obs0,~,~,~]=unpack_scenario(scenario);
opt=setup_options(); alpha=1/sqrt(3);
opt.coherent_lambda=1.25; opt.coherent_flip_cos=-0.15;
opt.coherent_topK=min(48,opt.separator_grid_N);
opt.compat_enable=true; opt.compat_min_dot=0.05; opt.compat_lambda=1.00;
opt.geom_guide_enable=true; opt.geom_guide_lambda=0.85;
opt.geom_guide_min_dot=0.35; opt.quality_enable=false;
opt.authority_tol=1e-10; opt.authority_lambda=0.15;
p9cf_preflight(cfg0,limits,opt);
p9cf_runtime_smoke(cfg0,limits,obs0,opt,alpha);

sys_scale=[1 1.30 1 1]; og=[1 1 1 1 35 15 -20];
case_id=20; family='CLIMB_TURN'; sf=.75;
nom_fun=@(t) p9a_nominal(t,family,sf);
cfg=cfg0;
cfg.sys.R_payload=cfg0.sys.R_payload*sys_scale(1);
cfg.sys.R_uav=cfg0.sys.R_uav*sys_scale(2);
cfg.sys.R_cable=cfg0.sys.R_cable*sys_scale(3);
cfg.sys.L_cable=cfg0.sys.L_cable*sys_scale(4);
obs=p9cf_make_obstacles(obs0,nom_fun,cfg,og,case_id);

tplan=20; tmission=72; D0=nom_fun(tplan);
risk=audit_nominal_risk_window(nom_fun,obs,cfg,opt,tplan,tmission,.04);
H=p6_predict_horizon(tplan,D0,risk,obs,nom_fun,cfg,limits,opt);
T0=H.T_plan; N=max(30,min(42,ceil(2*T0))); if mod(N,2), N=N+1; end
TMULT=[1.00 1.15 1.35 1.65 2.00 2.40];

f101aa_silent_fprintf('\n================================================================================\n');
f101aa_silent_fprintf(' Phase 9C-R8-F6: THEOREM-BASED CRITICAL-PAIR PRE-QP SCREEN\n');
f101aa_silent_fprintf(' Case #20 | intended for sensor-triggered online replanning\n');
f101aa_silent_fprintf(' NO obstacle/system sphere approximation; NO sampled-time safety proof.\n');
f101aa_silent_fprintf(' T0=%.6f, N=%d, zmax=%.3f | unchanged final global certificate\n',T0,N,opt.box_z_max);
f101aa_silent_fprintf('================================================================================\n');
f101aa_silent_fprintf(' xT0 | robustSafe/critical/gridImp | oldActive | worstPairClass | GD/C | cert_g\n');

R=[];
for k=1:numel(TMULT)
    rk=r8f6_probe(cfg,limits,obs,nom_fun,tplan,TMULT(k)*T0,N,opt,alpha);
    if isempty(R), R=repmat(rk,1,numel(TMULT)); else
        if ~isequal(sort(fieldnames(rk)),sort(fieldnames(R(1))))
            error('F6 internal schema error: dissimilar probe struct.');
        end
    end
    R(k)=rk;
    f101aa_silent_fprintf(' %.2f | %3d/%3d/%3d              | %3d       | %-13s | %d/%d  | %+9.6f\n', ...
        TMULT(k),rk.n_robust_safe,rk.n_critical,rk.n_grid_impossible,rk.n_old_active, ...
        rk.cert_worst_class,rk.GD,rk.C,rk.cert_g);
end

f101aa_silent_fprintf('\n[DETAIL: x2.00 and x2.40]\n');
for k=1:numel(R)
    if abs(TMULT(k)-2.0)>1e-12 && abs(TMULT(k)-2.4)>1e-12, continue; end
    r=R(k);
    f101aa_silent_fprintf('\n--- T/T0=%.2f ---\n',TMULT(k));
    f101aa_silent_fprintf('pre-screen time = %.3f ms for %d span-obstacle pairs x %d directions\n', ...
        1e3*r.screen_time,r.n_pairs,r.n_dirs);
    f101aa_silent_fprintf('robustSafe=%d critical=%d gridImpossible=%d | oldActive=%d\n', ...
        r.n_robust_safe,r.n_critical,r.n_grid_impossible,r.n_old_active);
    f101aa_silent_fprintf('old inactive but F6 critical = %d | old inactive but gridImpossible = %d\n', ...
        r.n_inactive_critical,r.n_inactive_grid_impossible);
    if r.GD
        f101aa_silent_fprintf('certificate worst=%d/%d class=%s oldActive=%d | cert_g=%+.9f\n', ...
            r.cert_worst_span,r.cert_worst_obs,r.cert_worst_class,r.cert_worst_old_active,r.cert_g);
        f101aa_silent_fprintf('  max robust LB = %+.9f using n=[%+.5f %+.5f %+.5f]^T\n', ...
            r.cert_worst_robust,r.cert_worst_n_robust);
        f101aa_silent_fprintf('  max optimistic UB(grid) = %+.9f using n=[%+.5f %+.5f %+.5f]^T\n', ...
            r.cert_worst_optimistic,r.cert_worst_n_optimistic);
    end
end

% Hard logical checks.
for k=1:numel(R)
    r=R(k);
    if r.n_robust_safe+r.n_critical+r.n_grid_impossible~=r.n_pairs
        error('F6 classification partition failure.');
    end
    if any(r.robust_best > r.optimistic_best + 1e-10)
        error('F6 bound ordering failure: robust lower bound exceeds optimistic upper bound.');
    end
    if any(r.class_code==1 & r.robust_best < -opt.cert_tol)
        error('F6 ROBUST_SAFE classification invariant failed.');
    end
    if any(r.class_code==3 & r.optimistic_best >= -opt.cert_tol)
        error('F6 GRID_IMPOSSIBLE classification invariant failed.');
    end
end

f101aa_silent_fprintf('\n[INTERPRETATION]\n');
f101aa_silent_fprintf(' ROBUST_SAFE: one tested fixed normal certifies the pair for EVERY z in the C6 box,\n');
f101aa_silent_fprintf('              even with worst cable orientation q=-1. This is a rigorous safety result.\n');
f101aa_silent_fprintf(' CRITICAL:    box-level theorem cannot decide; candidate generation must handle this pair.\n');
f101aa_silent_fprintf(' GRID_IMPOSSIBLE: even an optimistic box/cable bound cannot certify any TESTED normal.\n');
f101aa_silent_fprintf('              This is finite-grid impossibility only, not impossibility over all S^2.\n');
f101aa_silent_fprintf(' Final execution authorization is STILL only the unchanged global certificate C=1.\n');
f101aa_silent_fprintf('\nHard bound/classification checks: PASS\n');
f101aa_silent_fprintf('No C6 condition, obstacle geometry, QP constraint, or certificate threshold was weakened.\n');
f101aa_silent_fprintf('================================================================================\n');
result=struct('case_id',case_id,'T0',T0,'N',N,'T_support',TMULT,'records',R,'H',H);
end

function r=r8f6_probe(cfg,limits,obs,nom_fun,tplan,T,N,opt,alpha)
D0=nom_fun(tplan); D1=nom_fun(tplan+T); cfgN=cfg; cfgN.N_ctrl=N;
c=build_static_cache_boundary(cfgN,tplan,tplan+T,nom_fun,D0,D1,opt);
[Gmat,gvec,info]=build_coherent_guided_corridor(c,cfgN,obs,opt);
dirs=fibonacci_sphere(max(162,opt.separator_grid_N));
ns=c.nspans; no=numel(obs); np=ns*no;
rob=-inf(ns,no); opti=-inf(ns,no);
nrob=zeros(3,ns,no); nopti=zeros(3,ns,no);

Dmax=delta_sep_from_q_lower(-1,cfgN.sys);
Dmin=delta_sep_from_q_lower(+1,cfgN.sys);
zmax=opt.box_z_max;
ticScreen=tic;
for sp=1:ns
    B0=c.B0{sp}; Bz=c.Bz{sp};
    for o=1:no
        br=-inf; bo=-inf; nr=[1;0;0]; no2=[1;0;0];
        for kk=1:size(dirs,2)
            n=dirs(:,kk); n=n/norm(n);
            lowj=inf(1,c.p+1); upj=inf(1,c.p+1);
            for j=1:c.p+1
                a=n'*Bz(:,:,j);
                ctr=n'*B0(:,j); rad=zmax*sum(abs(a));
                lowj(j)=ctr-rad;
                upj(j)=ctr+rad;
            end
            h=obstacle_support(obs(o),n);
            gr=min(lowj)-Dmax-h-cfgN.d_margin;
            go=min(upj)-Dmin-h-cfgN.d_margin;
            if gr>br, br=gr; nr=n; end
            if go>bo, bo=go; no2=n; end
        end
        rob(sp,o)=br; opti(sp,o)=bo; nrob(:,sp,o)=nr; nopti(:,sp,o)=no2;
    end
end
screen_time=toc(ticScreen);

% class: 1 ROBUST_SAFE, 2 CRITICAL, 3 GRID_IMPOSSIBLE
cls=2*ones(ns,no);
cls(rob>=-opt.cert_tol)=1;
cls(rob < -opt.cert_tol & opti < -opt.cert_tol)=3;

r=struct('screen',false,'GD',false,'C',false,'cert_g',-inf, ...
    'n_pairs',np,'n_dirs',size(dirs,2),'screen_time',screen_time, ...
    'n_robust_safe',sum(cls(:)==1),'n_critical',sum(cls(:)==2), ...
    'n_grid_impossible',sum(cls(:)==3),'n_old_active',sum(info.active(:)), ...
    'n_inactive_critical',sum(~info.active(:) & cls(:)==2), ...
    'n_inactive_grid_impossible',sum(~info.active(:) & cls(:)==3), ...
    'class_code',cls,'robust_best',rob,'optimistic_best',opti, ...
    'cert_worst_span',0,'cert_worst_obs',0,'cert_worst_class','N/A', ...
    'cert_worst_old_active',false,'cert_worst_robust',NaN,'cert_worst_optimistic',NaN, ...
    'cert_worst_n_robust',[NaN;NaN;NaN],'cert_worst_n_optimistic',[NaN;NaN;NaN]);

r.screen=isfield(info,'authority_screen_pass') && info.authority_screen_pass;
if ~r.screen, return; end
md=build_dyn_E(c); [Dmat,dvec]=dyn_E(md,limits,alpha);
rgd=p8r6_feas_online(c,[Gmat;Dmat],[gvec;dvec],opt);
r.GD=rgd.flag>0; if ~r.GD, return; end
P=apply_z(c,rgd.z);
cert=certify_candidate_global(P,c,cfgN,limits,obs,opt);
r.C=cert.pass; r.cert_g=cert.min_g_lower;
sp=cert.worst.span; o=cert.worst.obs;
r.cert_worst_span=sp; r.cert_worst_obs=o; r.cert_worst_old_active=info.active(sp,o);
r.cert_worst_robust=rob(sp,o); r.cert_worst_optimistic=opti(sp,o);
r.cert_worst_n_robust=nrob(:,sp,o); r.cert_worst_n_optimistic=nopti(:,sp,o);
r.cert_worst_class=r8f6_class_name(cls(sp,o));
end

function s=r8f6_class_name(c)
if c==1, s='ROBUST_SAFE'; elseif c==2, s='CRITICAL'; else, s='GRID_IMPOSSIBLE'; end
end

function r=r8f5_probe(cfg,limits,obs,nom_fun,tplan,T,N,opt,alpha)
D0=nom_fun(tplan); D1=nom_fun(tplan+T); cfgN=cfg; cfgN.N_ctrl=N;
c=build_static_cache_boundary(cfgN,tplan,tplan+T,nom_fun,D0,D1,opt);
[Gmat,gvec,info]=build_coherent_guided_corridor(c,cfgN,obs,opt);
r=struct('screen',false,'GD',false,'C',false,'cert_g',-inf, ...
    'worst_span',0,'worst_obs',0,'worst_active',false, ...
    'worst_g_gen',NaN,'worst_g_grid',NaN,'worst_dot',NaN,'worst_angle_deg',NaN, ...
    'worst_n_gen',[NaN;NaN;NaN],'worst_n_cert',[NaN;NaN;NaN], ...
    'min_g_gen_all',inf,'min_g_gen_span',0,'min_g_gen_obs',0,'min_g_gen_active',false, ...
    'min_g_gen_active_pairs',inf,'min_g_gen_inactive_pairs',inf, ...
    'min_grid_minus_gen',inf,'grid_false_negative_count',0);
r.screen=isfield(info,'authority_screen_pass') && info.authority_screen_pass;
if ~r.screen, return; end
md=build_dyn_E(c); [Dmat,dvec]=dyn_E(md,limits,alpha);
rgd=p8r6_feas_online(c,[Gmat;Dmat],[gvec;dvec],opt);
r.GD=rgd.flag>0; if ~r.GD, return; end
P=apply_z(c,rgd.z);
cert=certify_candidate_global(P,c,cfgN,limits,obs,opt);
r.cert_g=cert.min_g_lower; r.worst_span=cert.worst.span; r.worst_obs=cert.worst.obs;
r.C=cert.pass;

% IMPORTANT: exactly the same direction grid size as certify_candidate_global.
dirsC=fibonacci_sphere(max(162,opt.separator_grid_N));
minGrid=inf;
for sp=1:c.nspans
    ua=c.spans(sp,1); ub=c.spans(sp,2);
    Pbez=span_bezier_points(c,P,ua,ub,0);
    Abez=span_bezier_points(c,P,ua,ub,2);
    Wbez=Abez+repmat(cfgN.g_acc*cfgN.e3,1,size(Abez,2));
    Mlb=compute_certified_tension_lower_bound_cols(Wbez);
    for o=1:numel(obs)
        nG=info.normal(:,sp,o); nG=nG/norm(nG);
        gG=span_system_g_lower_M(nG,Pbez,Wbez,Mlb,obs(o),cfgN);
        [gC,nC]=best_separator_grid(Pbez,Wbez,Mlb,obs(o),cfgN,dirsC);
        minGrid=min(minGrid,gC);
        r.min_grid_minus_gen=min(r.min_grid_minus_gen,gC-gG);
        if gC < -opt.cert_tol && gG >= -opt.cert_tol
            r.grid_false_negative_count=r.grid_false_negative_count+1;
        end
        if gG<r.min_g_gen_all
            r.min_g_gen_all=gG; r.min_g_gen_span=sp; r.min_g_gen_obs=o;
            r.min_g_gen_active=info.active(sp,o);
        end
        if info.active(sp,o)
            r.min_g_gen_active_pairs=min(r.min_g_gen_active_pairs,gG);
        else
            r.min_g_gen_inactive_pairs=min(r.min_g_gen_inactive_pairs,gG);
        end
        if sp==r.worst_span && o==r.worst_obs
            r.worst_active=info.active(sp,o);
            r.worst_g_gen=gG; r.worst_g_grid=gC;
            r.worst_n_gen=nG; r.worst_n_cert=nC;
            dd=max(-1,min(1,nG'*nC)); r.worst_dot=dd;
            r.worst_angle_deg=acos(dd)*180/pi;
        end
    end
end
if abs(minGrid-r.cert_g)>1e-10
    error('F5 independent all-pair grid reconstruction mismatch.');
end
end

function r=r8f4_probe(cfg,limits,obs,nom_fun,tplan,T,N,opt,alpha)
D0=nom_fun(tplan); D1=nom_fun(tplan+T); cfgN=cfg; cfgN.N_ctrl=N;
c=build_static_cache_boundary(cfgN,tplan,tplan+T,nom_fun,D0,D1,opt);
[Gmat,gvec,info]=build_coherent_guided_corridor(c,cfgN,obs,opt);
r=struct('screen',false,'GD',false,'C',false,'affine_error',0, ...
    'min_generator_row',NaN,'max_cable_gap',NaN,'min_safe_row',NaN, ...
    'cert_g',-inf,'c6s',inf,'c6e',inf,'n_rows',0,'worst_span',0,'worst_obs',0);
r.screen=isfield(info,'authority_screen_pass') && info.authority_screen_pass;
if ~r.screen, return; end
md=build_dyn_E(c); [Dmat,dvec]=dyn_E(md,limits,alpha);
rgd=p8r6_feas_online(c,[Gmat;Dmat],[gvec;dvec],opt);
r.GD=rgd.flag>0; if ~r.GD, return; end
z=rgd.z; P=apply_z(c,z);

% Exact affine Bezier identity audit on every span/control point.
for sp=1:c.nspans
    Baff=zeros(3,c.p+1);
    for j=1:c.p+1, Baff(:,j)=c.B0{sp}(:,j)+c.Bz{sp}(:,:,j)*z; end
    Bdir=span_bezier_points(c,P,c.spans(sp,1),c.spans(sp,2),0);
    r.affine_error=max(r.affine_error,max(abs(Baff(:)-Bdir(:))));
end

% Generator rows: A*z<=b => row slack b-A*z.  These are exact for the
% frozen generator RHS, but that RHS contains Delta_frozen.
if isempty(Gmat), r.min_generator_row=inf; else, r.min_generator_row=min(gvec-Gmat*z); end

% Rebuild the SAME active normal/span pairs and quantify the missing cable
% term using the candidate's rigorous continuous-time bound.
minSafe=inf; maxGap=-inf; nrows=0;
for sp=1:c.nspans
    ua=c.spans(sp,1); ub=c.spans(sp,2);
    Pbez=span_bezier_points(c,P,ua,ub,0);
    Abez=span_bezier_points(c,P,ua,ub,2);
    Wbez=Abez+repmat(cfgN.g_acc*cfgN.e3,1,size(Abez,2));
    Mlb=compute_certified_tension_lower_bound_cols(Wbez);
    for o=1:numel(obs)
        if ~info.active(sp,o), continue; end
        n=info.normal(:,sp,o); n=n/norm(n);
        um=mean([ua ub]); a0=eval_spline(c,c.Pbase,um,2);
        w0=a0+cfgN.g_acc*cfgN.e3;
        if norm(w0)<=opt.a_net_min, nT0=cfgN.e3; else, nT0=w0/norm(w0); end
        Df=delta_sep_exact(n,nT0,cfgN.sys);
        wmin=min(n'*Wbez); Mmax=max(vecnorm(Wbez,2,1));
        if Mmax<=1e-12, qlb=-1;
        elseif wmin>=0, qlb=wmin/Mmax;
        elseif Mlb>0, qlb=max(-1,wmin/Mlb);
        else, qlb=-1; end
        Dub=delta_sep_from_q_lower(qlb,cfgN.sys);
        maxGap=max(maxGap,Dub-Df);
        rhsSafe=obstacle_support(obs(o),n)+Dub+cfgN.d_margin;
        for j=1:c.p+1
            minSafe=min(minSafe,n'*Pbez(:,j)-rhsSafe); nrows=nrows+1;
        end
    end
end
if nrows==0, minSafe=inf; maxGap=NaN; end
r.min_safe_row=minSafe; r.max_cable_gap=maxGap; r.n_rows=nrows;

cert=certify_candidate_global(P,c,cfgN,limits,obs,opt);
r.cert_g=cert.min_g_lower; r.worst_span=cert.worst.span; r.worst_obs=cert.worst.obs;
r.c6s=0; r.c6e=0;
for rr=0:6
    r.c6s=max(r.c6s,norm(eval_spline(c,P,0,rr)-D0(:,rr+1),inf));
    r.c6e=max(r.c6e,norm(eval_spline(c,P,1,rr)-D1(:,rr+1),inf));
end
r.C=cert.pass && r.c6s<=opt.c6_tol && r.c6e<=opt.c6_tol;
end

function r8f4_print(mult,r)
f101aa_silent_fprintf(' %.2f |  %d  | %d/%d  | %.2e | %+8.3e | %+11.3e | %+10.3e | %+8.5f\n', ...
    mult,r.screen,r.GD,r.C,r.affine_error,r.min_generator_row, ...
    r.max_cable_gap,r.min_safe_row,r.cert_g);
end


function q=p9cr6_probe(cfg,limits,obs,nom_fun,tplan,T,N,opt,alpha)
D0=nom_fun(tplan); D1=nom_fun(tplan+T);
cfgN=cfg; cfgN.N_ctrl=N;
c=build_static_cache_boundary(cfgN,tplan,tplan+T,nom_fun,D0,D1,opt);

for r=0:6
    if norm(eval_spline(c,c.Pbase,0,r)-D0(:,r+1),inf)>opt.c6_tol || ...
       norm(eval_spline(c,c.Pbase,1,r)-D1(:,r+1),inf)>opt.c6_tol
        error('R6 boundary construction error: start/end C6 mismatch.');
    end
end

[Gmat,gvec,info]=build_coherent_guided_corridor(c,cfgN,obs,opt);
q=p9cr6_empty_sample(); q.T=T;
q.screen=isfield(info,'authority_screen_pass') && info.authority_screen_pass;
q.fail_span=info.authority_fail_span; q.fail_obs=info.authority_fail_obs;
if ~q.screen, return; end

dirs=fibonacci_sphere(opt.separator_grid_N);
minAuth=inf;
for sp=1:c.nspans
    for o=1:numel(obs)
        if ~info.active(sp,o), continue; end
        n=info.normal(:,sp,o);
        [~,kk]=max(n'*dirs);
        minAuth=min(minAuth,info.authority_margin(sp,kk,o));
    end
end
if isinf(minAuth), minAuth=NaN; end
q.min_selected_authority=minAuth;
if isfinite(minAuth) && minAuth < -10*opt.authority_tol
    error('R6 internal error: authority-negative normal survived screen.');
end

md=build_dyn_E(c); [Dmat,dvec]=dyn_E(md,limits,alpha);
rg=p8r6_feas_online(c,Gmat,gvec,opt);
rd=p8r6_feas_online(c,Dmat,dvec,opt);
rgd=p8r6_feas_online(c,[Gmat;Dmat],[gvec;dvec],opt);
q.G=rg.flag>0; q.D=rd.flag>0; q.GD=rgd.flag>0;

if q.GD
    P=apply_z(c,rgd.z);
    cert=certify_candidate_global(P,c,cfgN,limits,obs,opt);
    q.min_g=cert.min_g_lower;
    q.v=cert.v_bound; q.a=cert.a_bound; q.j=cert.j_bound;
    q.c6s=0; q.c6e=0;
    for r=0:6
        q.c6s=max(q.c6s,norm(eval_spline(c,P,0,r)-D0(:,r+1),inf));
        q.c6e=max(q.c6e,norm(eval_spline(c,P,1,r)-D1(:,r+1),inf));
    end
    q.C=cert.pass && q.c6s<=opt.c6_tol && q.c6e<=opt.c6_tol;
end
end

function r=p9cr6_summarize_case(r)
if isempty(r.samples), return; end
m=[r.samples.mult];
S=[r.samples.screen]; G=[r.samples.G]; GD=[r.samples.GD]; C=[r.samples.C];
i=find(S,1,'first'); if ~isempty(i),r.first_screen=m(i);end
i=find(G,1,'first'); if ~isempty(i),r.first_G=m(i);end
i=find(GD,1,'first'); if ~isempty(i),r.first_GD=m(i);end
i=find(C,1,'first'); if ~isempty(i),r.first_cert=m(i);end

% Contiguous certified intervals on the sampled grid only.
idx=find(C);
if isempty(idx), return; end
cuts=[1 find(diff(idx)>1)+1 numel(idx)+1];
I=zeros(numel(cuts)-1,2);
for k=1:numel(cuts)-1
    jj=idx(cuts(k):cuts(k+1)-1);
    I(k,:)=[m(jj(1)) m(jj(end))];
end
r.cert_intervals=I;
end

function s=p9cr6_numstr(x)
if isfinite(x), s=sprintf('x%.2f',x); else, s='NONE'; end
end

function s=p9cr6_interval_string(I)
if isempty(I), s='NONE'; return; end
parts=cell(1,size(I,1));
for k=1:size(I,1)
    if abs(I(k,1)-I(k,2))<1e-12
        parts{k}=sprintf('[x%.2f]',I(k,1));
    else
        parts{k}=sprintf('[x%.2f,x%.2f]',I(k,1),I(k,2));
    end
end
s=strjoin(parts,' U ');
end

function result = p9cr5_embedded_unused()
% =========================================================================
% Phase 9C-R5: 48-CASE AUTHORITY-SCREENED GENERALIZATION REGRESSION
%
% Basis:
%   - exact Phase 9C 48-case geometry/pose/shape matrix
%   - R4 per-span terminal-authority repair
%   - start/end C6 unchanged
%   - frozen |z| <= box_z_max
%   - independent continuous-time certificate unchanged
%
% IMPORTANT:
%   This is OFFLINE regression/teacher validation, NOT the final <=3 ms path.
%   We intentionally retain the same three Phase-9C candidate multipliers
%       [1.10, 1.25, 1.50] * T0
%   so the result is directly comparable with the original 33/48 baseline.
%
% New failure decomposition:
%   SCREEN_REJECT_ALL : all three T candidates rejected before QP
%   G_INFEASIBLE      : screened candidate(s), but no G-feasible candidate
%   GD_INFEASIBLE     : G and D individually feasible but no combined G+D
%   CERT_REJECT       : G+D feasible, independent certificate rejects
%   CERTIFIED         : unchanged certificate + C6 gates pass
% =========================================================================
clc;
scenario=setup_benchmark();
[cfg0,limits,obs0,~,~,~]=unpack_scenario(scenario);
opt=setup_options(); alpha=1/sqrt(3);

% Frozen 9A-G + R4 generator-side authority repair.
opt.coherent_lambda=1.25; opt.coherent_flip_cos=-0.15;
opt.coherent_topK=min(48,opt.separator_grid_N);
opt.compat_enable=true; opt.compat_min_dot=0.05; opt.compat_lambda=1.00;
opt.geom_guide_enable=true; opt.geom_guide_lambda=0.85;
opt.geom_guide_min_dot=0.35; opt.quality_enable=false;
opt.authority_tol=1e-10;
opt.authority_lambda=0.15;

p9cf_preflight(cfg0,limits,opt);
p9cf_runtime_smoke(cfg0,limits,obs0,opt,alpha);

SYS=[.70 .70 .70 .70; ...
     1.00 1.00 1.00 1.00; ...
     1.30 1.00 1.00 1.00; ...
     1.00 1.30 1.00 1.00; ...
     1.00 1.00 1.50 1.00; ...
     1.00 1.00 1.00 1.35; ...
     1.25 1.25 1.25 1.25; ...
     1.50 1.30 1.50 1.40];
SYSNAME={'SMALL_ALL','BASE','BIG_PAYLOAD','BIG_UAV','THICK_CABLE', ...
         'LONG_CABLE','LARGE_ALL','EXTREME_LARGE'};

OG=[.70 1.00 1.00 1.00   0   0   0; ...
    1.00 1.00 1.00 1.00  35  15 -20; ...
    1.20 1.50 .70 1.00   70 -25  30; ...
    1.30 .65 1.60 .85   115  35 -40; ...
    1.10 .75 .80 1.70   155 -35  55; ...
    1.35 1.70 .60 .70   205  20  65];
OGNAME={'SMALL_SPHEROID','BASE_ROTATED','LONG_X','LONG_Y','TALL_Z','FLAT_LONG'};

FAM={'STRAIGHT','CIRCLE','HELIX','S_CURVE','CLIMB_TURN'};
SF=[.75 1.00 1.25];
TMULT=[1.10 1.25 1.50]; % exact original Phase-9C offline attempts

tplan=20; tmission=72;
REC=repmat(p9cr5_empty_case(),1,size(SYS,1)*size(OG,1));
icase=0;

f101aa_silent_fprintf('================================================================================\n');
f101aa_silent_fprintf(' Phase 9C-R5: 48-CASE AUTHORITY-SCREENED GENERALIZATION REGRESSION\n');
f101aa_silent_fprintf(' original Phase-9C matrix / R4 repair / certificate unchanged\n');
f101aa_silent_fprintf(' offline T attempts = [1.10 1.25 1.50] * T0\n');
f101aa_silent_fprintf('================================================================================\n');

for is=1:size(SYS,1)
    for io=1:size(OG,1)
        icase=icase+1;
        fam=FAM{mod(icase-1,numel(FAM))+1};
        sf=SF(mod(floor((icase-1)/numel(FAM)),numel(SF))+1);
        nom_fun=@(t) p9a_nominal(t,fam,sf);

        cfg=cfg0;
        cfg.sys.R_payload=cfg0.sys.R_payload*SYS(is,1);
        cfg.sys.R_uav=cfg0.sys.R_uav*SYS(is,2);
        cfg.sys.R_cable=cfg0.sys.R_cable*SYS(is,3);
        cfg.sys.L_cable=cfg0.sys.L_cable*SYS(is,4);
        obs=p9cf_make_obstacles(obs0,nom_fun,cfg,OG(io,:),icase);

        D0=nom_fun(tplan);
        risk=audit_nominal_risk_window(nom_fun,obs,cfg,opt,tplan,tmission,.04);
        H=p6_predict_horizon(tplan,D0,risk,obs,nom_fun,cfg,limits,opt);
        T0=H.T_plan;
        N=max(30,min(42,ceil(2*T0))); if mod(N,2),N=N+1; end

        r=p9cr5_empty_case();
        r.id=icase; r.is=is; r.io=io; r.sys=SYSNAME{is}; r.obs=OGNAME{io};
        r.fam=fam; r.sf=sf; r.T0=T0; r.N=N;

        best=[];
        for ia=1:numel(TMULT)
            T=TMULT(ia)*T0;
            if tplan+T>tmission, continue; end
            q=p9cr5_probe(cfg,limits,obs,nom_fun,tplan,T,N,opt,alpha);
            q.mult=TMULT(ia);
            r.attempts(end+1)=q; %#ok<AGROW>

            r.n_attempt=r.n_attempt+1;
            if ~q.screen
                r.n_screen_reject=r.n_screen_reject+1;
                continue;
            end
            r.n_screen_pass=r.n_screen_pass+1;
            r.anyG=r.anyG||q.G; r.anyD=r.anyD||q.D; r.anyGD=r.anyGD||q.GD;
            if q.C
                best=q;
                break; % same Phase-9C first-certified semantics
            end
        end

        if ~isempty(best)
            r.pass=true; r.class='CERTIFIED';
            r.Tcert=best.T; r.multcert=best.mult; r.min_g=best.min_g;
            r.c6s=best.c6s; r.c6e=best.c6e;
            r.v=best.v; r.a=best.a; r.j=best.j;
            r.minAuth=best.min_selected_authority;
        else
            if r.n_screen_pass==0
                r.class='SCREEN_REJECT_ALL';
            elseif ~r.anyG
                r.class='G_INFEASIBLE';
            elseif r.anyG && r.anyD && ~r.anyGD
                r.class='GD_INFEASIBLE';
            elseif r.anyGD
                r.class='CERT_REJECT';
            else
                r.class='MIXED_INFEASIBLE';
            end
        end

        REC(icase)=r;
        f101aa_silent_fprintf('#%02d %-13s %-14s %-10s sf=%.2f | %s | screen %d/%d', ...
            r.id,r.sys,r.obs,r.fam,r.sf,r.class,r.n_screen_pass,r.n_attempt);
        if r.pass
            f101aa_silent_fprintf(' | T/T0=%.2f g=%+.4f C6=%.1e\n',r.multcert,r.min_g,max(r.c6s,r.c6e));
        else
            f101aa_silent_fprintf(' | G/D/GD=%d/%d/%d\n',r.anyG,r.anyD,r.anyGD);
        end
    end
end

% ------------------------------ summary -----------------------------------
PASS=[REC.pass];
f101aa_silent_fprintf('\n================================================================================\n');
f101aa_silent_fprintf('[PHASE 9C-R5 SUMMARY]\n');
f101aa_silent_fprintf(' Certified = %d/%d = %.1f%%\n',sum(PASS),numel(REC),100*mean(PASS));
f101aa_silent_fprintf(' Original Phase 9C baseline = 33/48 = 68.8%%\n');
f101aa_silent_fprintf(' Delta = %+d certified cases\n',sum(PASS)-33);

classes={'SCREEN_REJECT_ALL','G_INFEASIBLE','GD_INFEASIBLE','CERT_REJECT','MIXED_INFEASIBLE'};
for k=1:numel(classes)
    f101aa_silent_fprintf(' %-22s : %d\n',classes{k},sum(strcmp({REC.class},classes{k})));
end
f101aa_silent_fprintf(' Total candidate attempts       : %d\n',sum([REC.n_attempt]));
f101aa_silent_fprintf(' Pre-QP screen rejects          : %d\n',sum([REC.n_screen_reject]));
f101aa_silent_fprintf(' Screen-passed candidate QPs    : %d\n',sum([REC.n_screen_pass]));

f101aa_silent_fprintf('\nBy system geometry:\n');
for is=1:numel(SYSNAME)
    ix=[REC.is]==is;
    f101aa_silent_fprintf(' %-15s %d/%d\n',SYSNAME{is},sum(PASS(ix)),sum(ix));
end
f101aa_silent_fprintf('\nBy obstacle shape/pose:\n');
for io=1:numel(OGNAME)
    ix=[REC.io]==io;
    f101aa_silent_fprintf(' %-15s %d/%d\n',OGNAME{io},sum(PASS(ix)),sum(ix));
end

if any(PASS)
    f101aa_silent_fprintf('\nCertified envelope:\n');
    f101aa_silent_fprintf(' min min_g = %+.6f\n',min([REC(PASS).min_g]));
    f101aa_silent_fprintf(' max C6 start/end = %.3e / %.3e\n',max([REC(PASS).c6s]),max([REC(PASS).c6e]));
    f101aa_silent_fprintf(' max v/a/j = %.3f / %.3f / %.3f\n', ...
        max([REC(PASS).v]),max([REC(PASS).a]),max([REC(PASS).j]));
    f101aa_silent_fprintf(' min selected authority = %+.6e\n',min([REC(PASS).minAuth]));
end

f101aa_silent_fprintf('\nFailed cases:\n');
for k=find(~PASS)
    r=REC(k);
    f101aa_silent_fprintf(' #%02d %-15s %-15s %-10s sf=%.2f : %s (screen %d/%d, G/D/GD=%d/%d/%d)\n', ...
        r.id,r.sys,r.obs,r.fam,r.sf,r.class,r.n_screen_pass,r.n_attempt,r.anyG,r.anyD,r.anyGD);
end

% Hard invariants.
for k=1:numel(REC)
    for a=1:numel(REC(k).attempts)
        q=REC(k).attempts(a);
        if q.screen && q.min_selected_authority < -10*opt.authority_tol
            error('R5 invariant failure: negative selected authority survived screen.');
        end
        if q.C && (~q.screen || ~q.GD || q.min_g<0 || ...
                q.c6s>opt.c6_tol || q.c6e>opt.c6_tol)
            error('R5 invariant failure: invalid certified candidate.');
        end
    end
end
f101aa_silent_fprintf('\nHard invariant checks: PASS\n');
f101aa_silent_fprintf(' NOTE: this remains an offline regression, not the final one-shot/<=3 ms path.\n');
f101aa_silent_fprintf('================================================================================\n');

result=struct('records',REC,'pass_count',sum(PASS),'pass_rate',mean(PASS), ...
    'baseline_pass_count',33,'baseline_total',48);
end

function r=p9cr5_empty_case()
r=struct('id',0,'is',0,'io',0,'sys','','obs','','fam','','sf',NaN,'T0',NaN,'N',0, ...
    'attempts',repmat(p9cr5_empty_attempt(),1,0), ...
    'n_attempt',0,'n_screen_reject',0,'n_screen_pass',0, ...
    'anyG',false,'anyD',false,'anyGD',false,'pass',false,'class','', ...
    'Tcert',NaN,'multcert',NaN,'min_g',NaN,'c6s',NaN,'c6e',NaN, ...
    'v',NaN,'a',NaN,'j',NaN,'minAuth',NaN);
end

function q=p9cr5_empty_attempt()
q=struct('mult',NaN,'T',NaN,'screen',false,'fail_span',0,'fail_obs',0, ...
    'min_selected_authority',NaN,'G',false,'D',false,'GD',false,'C',false, ...
    'min_g',-inf,'c6s',inf,'c6e',inf,'v',NaN,'a',NaN,'j',NaN);
end

function q=p9cr5_probe(cfg,limits,obs,nom_fun,tplan,T,N,opt,alpha)
D0=nom_fun(tplan); D1=nom_fun(tplan+T);
cfgN=cfg; cfgN.N_ctrl=N;
c=build_static_cache_boundary(cfgN,tplan,tplan+T,nom_fun,D0,D1,opt);

% Explicit C6 construction audit.
for r=0:6
    if norm(eval_spline(c,c.Pbase,0,r)-D0(:,r+1),inf)>opt.c6_tol || ...
       norm(eval_spline(c,c.Pbase,1,r)-D1(:,r+1),inf)>opt.c6_tol
        error('R5 boundary construction error: start/end C6 mismatch.');
    end
end

[Gmat,gvec,info]=build_coherent_guided_corridor(c,cfgN,obs,opt);
q=p9cr5_empty_attempt(); q.T=T;
q.screen=isfield(info,'authority_screen_pass') && info.authority_screen_pass;
q.fail_span=info.authority_fail_span; q.fail_obs=info.authority_fail_obs;

if ~q.screen
    return; % No QP for a structurally rejected rejoin time.
end

dirs=fibonacci_sphere(opt.separator_grid_N);
minAuth=inf;
for sp=1:c.nspans
    for o=1:numel(obs)
        if ~info.active(sp,o), continue; end
        n=info.normal(:,sp,o);
        [~,kk]=max(n'*dirs);
        minAuth=min(minAuth,info.authority_margin(sp,kk,o));
    end
end
if isinf(minAuth), minAuth=NaN; end
q.min_selected_authority=minAuth;
if isfinite(minAuth) && minAuth < -10*opt.authority_tol
    error('R5 internal error: authority-negative normal survived screen.');
end

md=build_dyn_E(c); [Dmat,dvec]=dyn_E(md,limits,alpha);
rg=p8r6_feas_online(c,Gmat,gvec,opt);
rd=p8r6_feas_online(c,Dmat,dvec,opt);
rgd=p8r6_feas_online(c,[Gmat;Dmat],[gvec;dvec],opt);
q.G=rg.flag>0; q.D=rd.flag>0; q.GD=rgd.flag>0;

if q.GD
    P=apply_z(c,rgd.z);
    cert=certify_candidate_global(P,c,cfgN,limits,obs,opt);
    q.min_g=cert.min_g_lower;
    q.v=cert.v_bound; q.a=cert.a_bound; q.j=cert.j_bound;
    q.c6s=0; q.c6e=0;
    for r=0:6
        q.c6s=max(q.c6s,norm(eval_spline(c,P,0,r)-D0(:,r+1),inf));
        q.c6e=max(q.c6e,norm(eval_spline(c,P,1,r)-D1(:,r+1),inf));
    end
    q.C=cert.pass && q.c6s<=opt.c6_tol && q.c6e<=opt.c6_tol;
end
end

function result = p9cr4_embedded_unused()
% =========================================================================
% Phase 9C-R4: TERMINAL-AUTHORITY-SCREENED REJOIN
%
% Targeted validation before the full 48-case regression.
%
% Fixes relative to R3:
%   (1) authority-reachable directions cannot be dropped by top-K pruning;
%   (2) authority feasibility is checked PER ACTIVE SPAN;
%   (3) an all-Inf span is never allowed to leak into the temporal DP;
%   (4) a disconnected DP path is rejected explicitly;
%   (5) selected rejoin time T is screened BEFORE the G/D/GD QPs.
%
% C6 semantics are unchanged:
%   - T itself is selectable;
%   - once T is selected, start/end derivatives r=0..6 are fixed;
%   - C6 is never weakened to make a case pass.
%
% Independent continuous-time certificate is unchanged.
% =========================================================================
clc;
scenario=setup_benchmark();
[cfg0,limits,obs0,~,~,~]=unpack_scenario(scenario);
opt=setup_options(); alpha=1/sqrt(3);
opt.coherent_lambda=1.25; opt.coherent_flip_cos=-0.15;
opt.coherent_topK=min(48,opt.separator_grid_N);
opt.compat_enable=true; opt.compat_min_dot=0.05; opt.compat_lambda=1.00;
opt.geom_guide_enable=true; opt.geom_guide_lambda=0.85;
opt.geom_guide_min_dot=0.35; opt.quality_enable=false;
opt.authority_tol=1e-10;
opt.authority_lambda=0.15;

p9cf_preflight(cfg0,limits,opt);
p9cf_runtime_smoke(cfg0,limits,obs0,opt,alpha);

SYS=[.70 .70 .70 .70;1 1 1 1;1.30 1 1 1;1 1.30 1 1;1 1 1.50 1; ...
     1 1 1 1.35;1.25 1.25 1.25 1.25;1.50 1.30 1.50 1.40];
OG=[.70 1 1 1 0 0 0;1 1 1 1 35 15 -20;1.20 1.50 .70 1 70 -25 30; ...
    1.30 .65 1.60 .85 115 35 -40;1.10 .75 .80 1.70 155 -35 55; ...
    1.35 1.70 .60 .70 205 20 65];
FAM={'STRAIGHT','CIRCLE','HELIX','S_CURVE','CLIMB_TURN'};
SF=[.75 1 1.25];

CASEID=[7 40];
% Dense only around the known transition zones. This is offline validation,
% not the final online horizon search.
MULT={ [1.50 1.55 1.60 1.65 1.90 1.95 2.00 2.05 2.10 2.15], ...
       [1.05 1.10 1.15 1.20 1.90 1.95 2.00 2.05 2.10 2.15 2.25 2.50] };
tplan=20; tmission=72;
REC=[];

f101aa_silent_fprintf('================================================================================\n');
f101aa_silent_fprintf(' Phase 9C-R4: TERMINAL-AUTHORITY-SCREENED REJOIN\n');
f101aa_silent_fprintf(' C6 unchanged / per-span authority gate / independent certificate unchanged\n');
f101aa_silent_fprintf('================================================================================\n');

for ic=1:numel(CASEID)
    id=CASEID(ic);
    is=floor((id-1)/size(OG,1))+1; io=mod(id-1,size(OG,1))+1;
    fam=FAM{mod(id-1,numel(FAM))+1};
    sf=SF(mod(floor((id-1)/numel(FAM)),numel(SF))+1);
    nom_fun=@(t) p9a_nominal(t,fam,sf);

    cfg=cfg0;
    cfg.sys.R_payload=cfg0.sys.R_payload*SYS(is,1);
    cfg.sys.R_uav=cfg0.sys.R_uav*SYS(is,2);
    cfg.sys.R_cable=cfg0.sys.R_cable*SYS(is,3);
    cfg.sys.L_cable=cfg0.sys.L_cable*SYS(is,4);
    obs=p9cf_make_obstacles(obs0,nom_fun,cfg,OG(io,:),id);

    D0=nom_fun(tplan);
    risk=audit_nominal_risk_window(nom_fun,obs,cfg,opt,tplan,tmission,.04);
    H=p6_predict_horizon(tplan,D0,risk,obs,nom_fun,cfg,limits,opt);
    T0=H.T_plan;
    N=max(30,min(42,ceil(2*T0))); if mod(N,2),N=N+1; end

    f101aa_silent_fprintf('\n--------------------------------------------------------------------------------\n');
    f101aa_silent_fprintf('[CASE #%02d] %-10s sf=%.2f T0=%.3f N=%d\n',id,fam,sf,T0,N);
    f101aa_silent_fprintf('--------------------------------------------------------------------------------\n');

    for im=1:numel(MULT{ic})
        mult=MULT{ic}(im); T=mult*T0;
        if tplan+T>tmission, continue; end

        q=p9cr4_probe(cfg,limits,obs,nom_fun,tplan,T,N,opt,alpha);
        q.id=id; q.mult=mult; REC=[REC q]; %#ok<AGROW>

        if ~q.screen
            f101aa_silent_fprintf(' x%.2f | SCREEN=0 QP=SKIPPED | fail sp=%d obs=%d | minAuth=%+.3e | C6base=%.1e/%.1e\n', ...
                mult,q.fail_span,q.fail_obs,q.min_selected_authority,q.base_c6s,q.base_c6e);
        else
            f101aa_silent_fprintf(' x%.2f | SCREEN=1 G/D/GD/C=%d/%d/%d/%d g=%+.4f | minAuth=%+.3e | C6=%.1e/%.1e\n', ...
                mult,q.G,q.D,q.GD,q.C,q.min_g,q.min_selected_authority,q.c6s,q.c6e);
        end
    end
end

f101aa_silent_fprintf('\n================================================================================\n');
f101aa_silent_fprintf('[PHASE 9C-R4 SUMMARY]\n');
for id=CASEID
    rr=REC([REC.id]==id);
    f101aa_silent_fprintf(' CASE #%02d: screened %d/%d, certified %d/%d\n',id,sum([rr.screen]),numel(rr),sum([rr.C]),numel(rr));
    for k=1:numel(rr)
        f101aa_silent_fprintf('   x%.2f screen=%d G/D/GD/C=%d/%d/%d/%d auth=%+.2e fail=(%d,%d)\n', ...
            rr(k).mult,rr(k).screen,rr(k).G,rr(k).D,rr(k).GD,rr(k).C, ...
            rr(k).min_selected_authority,rr(k).fail_span,rr(k).fail_obs);
    end
end
f101aa_silent_fprintf('\nHard checks:\n');
f101aa_silent_fprintf('  - Any SCREEN=1 case must have minSelectedAuth >= -authority_tol.\n');
f101aa_silent_fprintf('  - SCREEN=0 performs no G/D/GD QP; C6 is not relaxed.\n');
f101aa_silent_fprintf('  - C=1 still requires the unchanged independent continuous-time certificate.\n');
f101aa_silent_fprintf('================================================================================\n');

% Programmatic invariant: no negative-authority selected normal may survive.
for k=1:numel(REC)
    if REC(k).screen && REC(k).min_selected_authority < -10*opt.authority_tol
        error('R4 invariant failure: negative selected authority survived screening.');
    end
end

result=struct('records',REC,'case_ids',CASEID);
end

function q=p9cr4_probe(cfg,limits,obs,nom_fun,tplan,T,N,opt,alpha)
D0=nom_fun(tplan); D1=nom_fun(tplan+T);
cfgN=cfg; cfgN.N_ctrl=N;
c=build_static_cache_boundary(cfgN,tplan,tplan+T,nom_fun,D0,D1,opt);

baseS=0; baseE=0;
for r=0:6
    baseS=max(baseS,norm(eval_spline(c,c.Pbase,0,r)-D0(:,r+1),inf));
    baseE=max(baseE,norm(eval_spline(c,c.Pbase,1,r)-D1(:,r+1),inf));
end
if baseS>opt.c6_tol || baseE>opt.c6_tol
    error('R4 boundary construction error: start/end C6 mismatch.');
end

[Gmat,gvec,info]=build_coherent_guided_corridor(c,cfgN,obs,opt);

% Pre-QP terminal/corridor authority screening.
screen=isfield(info,'authority_screen_pass') && info.authority_screen_pass;
minAuth=inf;
if screen
    dirs=fibonacci_sphere(opt.separator_grid_N);
    for sp=1:c.nspans
        for o=1:numel(obs)
            if ~info.active(sp,o), continue; end
            n=info.normal(:,sp,o);
            [~,kk]=max(n'*dirs);
            minAuth=min(minAuth,info.authority_margin(sp,kk,o));
        end
    end
end
if isinf(minAuth), minAuth=NaN; end

q=struct('id',0,'mult',NaN,'T',T,'N',N,'screen',screen, ...
    'fail_span',info.authority_fail_span,'fail_obs',info.authority_fail_obs, ...
    'min_selected_authority',minAuth,'base_c6s',baseS,'base_c6e',baseE, ...
    'G',0,'D',0,'GD',0,'C',0,'min_g',-inf,'c6s',inf,'c6e',inf);

if ~screen
    return; % QP intentionally skipped.
end
if minAuth < -10*opt.authority_tol
    error('R4 internal error: authority-negative normal selected after screen.');
end

md=build_dyn_E(c); [Dmat,dvec]=dyn_E(md,limits,alpha);
rg=p8r6_feas_online(c,Gmat,gvec,opt);
rd=p8r6_feas_online(c,Dmat,dvec,opt);
rgd=p8r6_feas_online(c,[Gmat;Dmat],[gvec;dvec],opt);
q.G=rg.flag>0; q.D=rd.flag>0; q.GD=rgd.flag>0;

if q.GD
    P=apply_z(c,rgd.z);
    cert=certify_candidate_global(P,c,cfgN,limits,obs,opt);
    q.min_g=cert.min_g_lower;
    q.c6s=0; q.c6e=0;
    for r=0:6
        q.c6s=max(q.c6s,norm(eval_spline(c,P,0,r)-D0(:,r+1),inf));
        q.c6e=max(q.c6e,norm(eval_spline(c,P,1,r)-D1(:,r+1),inf));
    end
    q.C=cert.pass && q.c6s<=opt.c6_tol && q.c6e<=opt.c6_tol;
end
end

function result = p9cr3_embedded_unused()
% =========================================================================
% Phase 9C-R3: BOUNDARY-AUTHORITY-AWARE CORRIDOR REPAIR
%
% Key facts preserved:
%   - Rejoin time T is selectable.
%   - Once T is selected, start AND end derivatives r=0..6 are fixed.
%   - C6 is NOT weakened.
%   - Independent continuous-time certificate is unchanged.
%
% Repair:
%   1) reject separator normals whose Bezier rows are individually
%      unreachable under the exact frozen |z| <= box_z_max authority;
%   2) retain 9A-G temporal + multi-obstacle coherence;
%   3) never relax the authority gate in generator fallback;
%   4) validate the known F5 toggle points before a full 48-case retest.
%
% This is a targeted repair validation, not the final <=3 ms implementation.
% =========================================================================
clc;
scenario=setup_benchmark();
[cfg0,limits,obs0,~,~,~]=unpack_scenario(scenario);
opt=setup_options(); alpha=1/sqrt(3);
opt.coherent_lambda=1.25; opt.coherent_flip_cos=-0.15;
opt.coherent_topK=min(48,opt.separator_grid_N);
opt.compat_enable=true; opt.compat_min_dot=0.05; opt.compat_lambda=1.00;
opt.geom_guide_enable=true; opt.geom_guide_lambda=0.85;
opt.geom_guide_min_dot=0.35; opt.quality_enable=false;

% New generator-only parameters. Certificate is unchanged.
opt.authority_tol=1e-10;
opt.authority_lambda=0.15;

p9cf_preflight(cfg0,limits,opt);
p9cf_runtime_smoke(cfg0,limits,obs0,opt,alpha);

SYS=[.70 .70 .70 .70;1 1 1 1;1.30 1 1 1;1 1.30 1 1;1 1 1.50 1; ...
     1 1 1 1.35;1.25 1.25 1.25 1.25;1.50 1.30 1.50 1.40];
OG=[.70 1 1 1 0 0 0;1 1 1 1 35 15 -20;1.20 1.50 .70 1 70 -25 30; ...
    1.30 .65 1.60 .85 115 35 -40;1.10 .75 .80 1.70 155 -35 55; ...
    1.35 1.70 .60 .70 205 20 65];
FAM={'STRAIGHT','CIRCLE','HELIX','S_CURVE','CLIMB_TURN'};
SF=[.75 1 1.25];

% F5 points: test both the boundary-zero-authority and normal-selection cases.
CASEID=[7 40];
MULT={ [1.55 1.60 1.90 2.00 2.15], [1.10 1.15 1.95 2.00 2.10 2.25 2.50] };
tplan=20; tmission=72;
REC=[];

f101aa_silent_fprintf('================================================================================\n');
f101aa_silent_fprintf(' Phase 9C-R3: BOUNDARY-AUTHORITY-AWARE CORRIDOR REPAIR\n');
f101aa_silent_fprintf(' start/end C6 unchanged | frozen box bounds | independent cert unchanged\n');
f101aa_silent_fprintf('================================================================================\n');

for ic=1:numel(CASEID)
    id=CASEID(ic);
    is=floor((id-1)/size(OG,1))+1; io=mod(id-1,size(OG,1))+1;
    fam=FAM{mod(id-1,numel(FAM))+1};
    sf=SF(mod(floor((id-1)/numel(FAM)),numel(SF))+1);
    nom_fun=@(t) p9a_nominal(t,fam,sf);
    cfg=cfg0;
    cfg.sys.R_payload=cfg0.sys.R_payload*SYS(is,1);
    cfg.sys.R_uav=cfg0.sys.R_uav*SYS(is,2);
    cfg.sys.R_cable=cfg0.sys.R_cable*SYS(is,3);
    cfg.sys.L_cable=cfg0.sys.L_cable*SYS(is,4);
    obs=p9cf_make_obstacles(obs0,nom_fun,cfg,OG(io,:),id);

    D0=nom_fun(tplan);
    risk=audit_nominal_risk_window(nom_fun,obs,cfg,opt,tplan,tmission,.04);
    H=p6_predict_horizon(tplan,D0,risk,obs,nom_fun,cfg,limits,opt);
    T0=H.T_plan;
    N=max(30,min(42,ceil(2*T0))); if mod(N,2),N=N+1; end

    f101aa_silent_fprintf('\n[CASE #%02d] %s T0=%.3f N=%d\n',id,fam,T0,N);
    for im=1:numel(MULT{ic})
        mult=MULT{ic}(im); T=mult*T0;
        if tplan+T>tmission, continue; end
        q=p9cr3_probe(cfg,limits,obs,nom_fun,tplan,T,N,opt,alpha);
        q.id=id; q.mult=mult; REC=[REC q]; %#ok<AGROW>
        f101aa_silent_fprintf(' x%.2f | G/D/GD/C=%d/%d/%d/%d g=%+.4f | authReject=%d minSelectedAuth=%+.3e | C6s/e=%.1e/%.1e\n', ...
            mult,q.G,q.D,q.GD,q.C,q.min_g,q.authority_reject_count, ...
            q.min_selected_authority,q.c6s,q.c6e);
    end
end

f101aa_silent_fprintf('\n================================================================================\n');
f101aa_silent_fprintf('[PHASE 9C-R3 SUMMARY]\n');
for id=CASEID
    rr=REC([REC.id]==id);
    for k=1:numel(rr)
        f101aa_silent_fprintf(' #%02d x%.2f : %d/%d/%d/%d g=%+.3f authMin=%+.2e C6e=%.1e\n', ...
            id,rr(k).mult,rr(k).G,rr(k).D,rr(k).GD,rr(k).C,rr(k).min_g, ...
            rr(k).min_selected_authority,rr(k).c6e);
    end
end
f101aa_silent_fprintf(' NOTE: a horizon with no authority-reachable terminal normal is rejected;\n');
f101aa_silent_fprintf('       C6 is never weakened. Rejoin time must instead move to a safe time.\n');
f101aa_silent_fprintf('================================================================================\n');

result=struct('records',REC,'case_ids',CASEID);
end

function q=p9cr3_probe(cfg,limits,obs,nom_fun,tplan,T,N,opt,alpha)
D0=nom_fun(tplan); D1=nom_fun(tplan+T);
cfgN=cfg; cfgN.N_ctrl=N;
c=build_static_cache_boundary(cfgN,tplan,tplan+T,nom_fun,D0,D1,opt);

% Explicitly audit the intended boundary semantics: C6 at both ends.
baseS=0; baseE=0;
for r=0:6
    baseS=max(baseS,norm(eval_spline(c,c.Pbase,0,r)-D0(:,r+1),inf));
    baseE=max(baseE,norm(eval_spline(c,c.Pbase,1,r)-D1(:,r+1),inf));
end
if baseS>opt.c6_tol || baseE>opt.c6_tol
    error('R3 boundary construction error: start/end C6 mismatch.');
end

md=build_dyn_E(c); [Dmat,dvec]=dyn_E(md,limits,alpha);
[Gmat,gvec,info]=build_coherent_guided_corridor(c,cfgN,obs,opt);

rg=p8r6_feas_online(c,Gmat,gvec,opt);
rd=p8r6_feas_online(c,Dmat,dvec,opt);
rgd=p8r6_feas_online(c,[Gmat;Dmat],[gvec;dvec],opt);
G=rg.flag>0; D=rd.flag>0; GD=rgd.flag>0;

C=false; min_g=-inf; c6s=inf; c6e=inf;
if GD
    P=apply_z(c,rgd.z);
    cert=certify_candidate_global(P,c,cfgN,limits,obs,opt);
    min_g=cert.min_g_lower;
    c6s=0; c6e=0;
    for r=0:6
        c6s=max(c6s,norm(eval_spline(c,P,0,r)-D0(:,r+1),inf));
        c6e=max(c6e,norm(eval_spline(c,P,1,r)-D1(:,r+1),inf));
    end
    C=cert.pass && c6s<=opt.c6_tol && c6e<=opt.c6_tol;
end

sel=inf;
if isfield(info,'authority_margin')
    for sp=1:c.nspans
        for o=1:numel(obs)
            if ~info.active(sp,o), continue; end
            n=info.normal(:,sp,o);
            dirs=fibonacci_sphere(opt.separator_grid_N);
            [~,k]=max(n'*dirs);
            sel=min(sel,info.authority_margin(sp,k,o));
        end
    end
end
if isinf(sel), sel=NaN; end

q=struct('id',0,'mult',NaN,'T',T,'N',N,'G',G,'D',D,'GD',GD,'C',C, ...
    'min_g',min_g,'c6s',c6s,'c6e',c6e,'base_c6s',baseS,'base_c6e',baseE, ...
    'authority_reject_count',info.authority_reject_count, ...
    'min_selected_authority',sel);
end

function result = p9cr3_embedded_f5_unused()
% =========================================================================
% Phase 9C-F5: BOUNDARY-vs-NORMAL CONFLICT DECOMPOSITION
%
% Purpose
%   Decompose the G-toggle observed in F4 into:
%     A) fixed-C6 / low-authority boundary-row conflict,
%     B) discrete separator-normal selection conflict,
%     C) collective half-space conflict,
%     D) G-D intersection conflict.
%
% IMPORTANT CORRECTION FROM F4
%   Frozen 9A-G online feasibility uses |z_i| <= opt.box_z_max.
%   F5 uses the SAME box bounds for all G/D/GD feasibility and diagnostic
%   slack solves. No diagnostic relaxation is used for acceptance.
%
% Targets
%   #07: x1.55 (G feasible) -> x1.60 (G infeasible)
%   #40: x1.10 (G feasible) -> x1.15 (G infeasible)
%        x1.95 (G infeasible) -> x2.00 (G feasible, GD infeasible)
%
% Frozen corridor construction and independent certificate are unchanged.
% =========================================================================
clc;
scenario=setup_benchmark();
[cfg0,limits,obs0,~,~,~]=unpack_scenario(scenario);
opt=setup_options(); alpha=1/sqrt(3);

opt.coherent_lambda=1.25; opt.coherent_flip_cos=-0.15;
opt.coherent_topK=min(48,opt.separator_grid_N);
opt.compat_enable=true; opt.compat_min_dot=0.05; opt.compat_lambda=1.00;
opt.geom_guide_enable=true; opt.geom_guide_lambda=0.85;
opt.geom_guide_min_dot=0.35; opt.quality_enable=false;

p9cf_preflight(cfg0,limits,opt);
p9cf_runtime_smoke(cfg0,limits,obs0,opt,alpha);

SYS=[.70 .70 .70 .70;1 1 1 1;1.30 1 1 1;1 1.30 1 1;1 1 1.50 1; ...
     1 1 1 1.35;1.25 1.25 1.25 1.25;1.50 1.30 1.50 1.40];
OG=[.70 1 1 1 0 0 0;1 1 1 1 35 15 -20;1.20 1.50 .70 1 70 -25 30; ...
    1.30 .65 1.60 .85 115 35 -40;1.10 .75 .80 1.70 155 -35 55; ...
    1.35 1.70 .60 .70 205 20 65];
FAM={'STRAIGHT','CIRCLE','HELIX','S_CURVE','CLIMB_TURN'};
SF=[.75 1 1.25];

CASEID=[7 40];
MULT={ [1.55 1.60], [1.10 1.15 1.95 2.00 2.10] };
tplan=20; tmission=72;
REC=[];

f101aa_silent_fprintf('================================================================================\n');
f101aa_silent_fprintf(' Phase 9C-F5: BOUNDARY-vs-NORMAL CONFLICT DECOMPOSITION\n');
f101aa_silent_fprintf(' exact frozen box bounds / certificate unchanged / diagnostics only\n');
f101aa_silent_fprintf('================================================================================\n');

for ic=1:numel(CASEID)
    id=CASEID(ic);
    is=floor((id-1)/size(OG,1))+1; io=mod(id-1,size(OG,1))+1;
    fam=FAM{mod(id-1,numel(FAM))+1};
    sf=SF(mod(floor((id-1)/numel(FAM)),numel(SF))+1);
    nom_fun=@(t) p9a_nominal(t,fam,sf);

    cfg=cfg0;
    cfg.sys.R_payload=cfg0.sys.R_payload*SYS(is,1);
    cfg.sys.R_uav=cfg0.sys.R_uav*SYS(is,2);
    cfg.sys.R_cable=cfg0.sys.R_cable*SYS(is,3);
    cfg.sys.L_cable=cfg0.sys.L_cable*SYS(is,4);
    obs=p9cf_make_obstacles(obs0,nom_fun,cfg,OG(io,:),id);

    D0=nom_fun(tplan);
    risk=audit_nominal_risk_window(nom_fun,obs,cfg,opt,tplan,tmission,.04);
    H=p6_predict_horizon(tplan,D0,risk,obs,nom_fun,cfg,limits,opt);
    T0=H.T_plan;
    N=max(30,min(42,ceil(2*T0))); if mod(N,2),N=N+1; end

    f101aa_silent_fprintf('\n--------------------------------------------------------------------------------\n');
    f101aa_silent_fprintf('[CASE #%02d] %-10s sf=%.2f T0=%.3f N=%d box=+/-%.2f\n', ...
        id,fam,sf,T0,N,opt.box_z_max);
    f101aa_silent_fprintf('--------------------------------------------------------------------------------\n');

    for im=1:numel(MULT{ic})
        mult=MULT{ic}(im); T=mult*T0;
        if tplan+T>tmission, continue; end

        q=p9cf5_probe(cfg,limits,obs,nom_fun,tplan,T,N,opt,alpha);
        q.id=id; q.mult=mult;
        REC=[REC q]; %#ok<AGROW>

        f101aa_silent_fprintf('\nx%.2f | G/D/GD/C=%d/%d/%d/%d g=%+.4f | rhoG=%.3e\n', ...
            mult,q.G,q.D,q.GD,q.C,q.min_g,q.rhoG);
        f101aa_silent_fprintf('      rows=%d active=%d | unreachable=%d zeroAuthBad=%d worstRowMargin=%+.3e\n', ...
            q.nrows,q.nactive,q.n_unreachable,q.n_zero_auth_bad,q.worst_row_margin);

        if q.culprit.valid
            c=q.culprit;
            f101aa_silent_fprintf('      culprit: row=%d sp=%d obs=%d bez=%d u=[%.4f %.4f]\n', ...
                c.row,c.sp,c.obs,c.bez,c.ua,c.ub);
            f101aa_silent_fprintf('               authority L1=%.3e selected-row-margin=%+.3e selected-normal=[%+.3f %+.3f %+.3f]\n', ...
                c.authority,c.row_margin,c.normal(1),c.normal(2),c.normal(3));
            f101aa_silent_fprintf('      normal scan (%d dirs): pairReachable=%d, globalGRescue=%d, bestRho=%.3e\n', ...
                q.scan.ndir,q.scan.n_pair_reachable,q.scan.n_global_rescue,q.scan.best_rho);
            f101aa_silent_fprintf('               bestPairMargin=%+.3e bestAngle=%.1f deg bestNormal=[%+.3f %+.3f %+.3f]\n', ...
                q.scan.best_pair_margin,q.scan.best_angle_deg, ...
                q.scan.best_normal(1),q.scan.best_normal(2),q.scan.best_normal(3));
        end
        f101aa_silent_fprintf('      diagnosis: %s\n',q.diagnosis);
    end
end

f101aa_silent_fprintf('\n================================================================================\n');
f101aa_silent_fprintf('[PHASE 9C-F5 SUMMARY]\n');
for id=CASEID
    rr=REC([REC.id]==id);
    for k=1:numel(rr)
        f101aa_silent_fprintf(' #%02d x%.2f : G/D/GD/C=%d/%d/%d/%d rhoG=%.2e -> %s\n', ...
            id,rr(k).mult,rr(k).G,rr(k).D,rr(k).GD,rr(k).C,rr(k).rhoG,rr(k).diagnosis);
    end
end
f101aa_silent_fprintf('\nDiagnosis meanings:\n');
f101aa_silent_fprintf(' FIXED_C6_ZERO_AUTHORITY      : violated row has essentially no free-z authority.\n');
f101aa_silent_fprintf(' ROW_UNREACHABLE_WITHIN_BOX   : at least one row cannot be satisfied even alone within frozen z box.\n');
f101aa_silent_fprintf(' NORMAL_SELECTION_RESCUABLE   : replacing only culprit pair normal can restore global G feasibility.\n');
f101aa_silent_fprintf(' COLLECTIVE_HALFSPACE_CONFLICT: rows individually reachable but jointly inconsistent.\n');
f101aa_silent_fprintf(' G_D_INTERSECTION_CONFLICT    : G and D individually feasible, combined infeasible.\n');
f101aa_silent_fprintf(' LINEAR_CORRIDOR_FEASIBLE     : frozen G itself is feasible.\n');
f101aa_silent_fprintf(' Certificate remains the only execution gate; F5 never relaxes it.\n');
f101aa_silent_fprintf('================================================================================\n');

result=struct('records',REC,'case_ids',CASEID);
end

function q=p9cf5_probe(cfg,limits,obs,nom_fun,tplan,T,N,opt,alpha)
D0=nom_fun(tplan); D1=nom_fun(tplan+T);
cfgN=cfg; cfgN.N_ctrl=N;
c=build_static_cache_boundary(cfgN,tplan,tplan+T,nom_fun,D0,D1,opt);
md=build_dyn_E(c); [Dmat,dvec]=dyn_E(md,limits,alpha);
[Gmat,gvec,info]=build_coherent_guided_corridor(c,cfgN,obs,opt);
meta=p9cf5_row_meta(c,info,numel(obs));

% EXACT frozen box-bounded feasibility.
rg=p8r6_feas_online(c,Gmat,gvec,opt);
rd=p8r6_feas_online(c,Dmat,dvec,opt);
rgd=p8r6_feas_online(c,[Gmat;Dmat],[gvec;dvec],opt);
G=rg.flag>0; D=rd.flag>0; GD=rgd.flag>0;

C=false; min_g=-inf;
if GD
    P=apply_z(c,rgd.z);
    cert=certify_candidate_global(P,c,cfgN,limits,obs,opt);
    C=cert.pass; min_g=cert.min_g_lower;
end

% Exact row-wise reachability over frozen z box.
zmax=opt.box_z_max;
row_min=-zmax*sum(abs(Gmat),2);
row_margin=gvec-row_min;
authority=sum(abs(Gmat),2);
zero_auth=authority<1e-12;
unreachable=row_margin < -1e-10;
zero_auth_bad=zero_auth & (gvec < -1e-10);

% Box-bounded common slack, diagnostic only.
[rho,zs]=p9cf5_box_slack(c,Gmat,gvec,opt);

culprit=p9cf5_culprit(Gmat,gvec,zs,row_margin,authority,meta,info);
scan=p9cf5_empty_scan();
if culprit.valid
    scan=p9cf5_normal_scan(c,cfgN,obs,opt,Gmat,gvec,info,meta,culprit);
end

if any(zero_auth_bad)
    diagnosis='FIXED_C6_ZERO_AUTHORITY';
elseif any(unreachable)
    if scan.n_global_rescue>0
        diagnosis='NORMAL_SELECTION_RESCUABLE';
    else
        diagnosis='ROW_UNREACHABLE_WITHIN_BOX';
    end
elseif ~G
    if scan.n_global_rescue>0
        diagnosis='NORMAL_SELECTION_RESCUABLE';
    else
        diagnosis='COLLECTIVE_HALFSPACE_CONFLICT';
    end
elseif G && D && ~GD
    diagnosis='G_D_INTERSECTION_CONFLICT';
elseif G
    diagnosis='LINEAR_CORRIDOR_FEASIBLE';
else
    diagnosis='UNRESOLVED';
end

q=struct('id',0,'mult',NaN,'T',T,'N',N,'G',G,'D',D,'GD',GD,'C',C, ...
    'min_g',min_g,'rhoG',rho,'nrows',size(Gmat,1),'nactive',nnz(info.active), ...
    'n_unreachable',nnz(unreachable),'n_zero_auth_bad',nnz(zero_auth_bad), ...
    'worst_row_margin',min([row_margin;inf]),'culprit',culprit,'scan',scan, ...
    'diagnosis',diagnosis);
end

function [rho,z]=p9cf5_box_slack(c,A,b,opt)
% Diagnostic only:
% min rho + tiny ||z||^2
% s.t. A z - rho <= b, |z_i|<=box_z_max, rho>=0.
if isempty(A), rho=0; z=zeros(c.nz,1); return; end
lb=[-opt.box_z_max*ones(c.nz,1);0];
ub=[ opt.box_z_max*ones(c.nz,1);inf];
H=1e-12*eye(c.nz+1);
f=[zeros(c.nz,1);1];
qo=optimoptions('quadprog','Display','off','Algorithm','interior-point-convex', ...
    'ConstraintTolerance',1e-10,'OptimalityTolerance',1e-10,'MaxIterations',1500);
try
    [x,~,fl]=quadprog(H,f,[A,-ones(size(A,1),1)],b,[],[],lb,ub,[],qo);
    if fl>0 && all(isfinite(x))
        z=x(1:c.nz); rho=max(0,x(end));
    else
        z=zeros(c.nz,1); rho=inf;
    end
catch
    z=zeros(c.nz,1); rho=inf;
end
end

function meta=p9cf5_row_meta(c,info,nobs)
nr=info.n_constraints;
meta=repmat(struct('sp',0,'obs',0,'bez',0,'ua',NaN,'ub',NaN),nr,1);
r=0;
for sp=1:c.nspans
    for o=1:nobs
        if ~info.active(sp,o), continue; end
        for j=1:c.p+1
            r=r+1;
            meta(r).sp=sp; meta(r).obs=o; meta(r).bez=j;
            meta(r).ua=c.spans(sp,1); meta(r).ub=c.spans(sp,2);
        end
    end
end
assert(r==nr,'F5 row metadata mismatch.');
end

function cpl=p9cf5_culprit(A,b,z,row_margin,authority,meta,info)
cpl=struct('valid',false,'row',0,'sp',0,'obs',0,'bez',0,'ua',NaN,'ub',NaN, ...
    'authority',NaN,'row_margin',NaN,'normal',[NaN;NaN;NaN]);
if isempty(A), return; end

% Prefer the most individually unreachable row. If all rows are individually
% reachable, use the largest violation at the minimum-common-slack solution.
if any(row_margin<0)
    [~,r]=min(row_margin);
else
    [~,r]=max(A*z-b);
end
m=meta(r);
cpl.valid=true; cpl.row=r; cpl.sp=m.sp; cpl.obs=m.obs; cpl.bez=m.bez;
cpl.ua=m.ua; cpl.ub=m.ub; cpl.authority=authority(r);
cpl.row_margin=row_margin(r);
cpl.normal=info.normal(:,m.sp,m.obs);
end

function S=p9cf5_empty_scan()
S=struct('ndir',0,'n_pair_reachable',0,'n_global_rescue',0, ...
    'best_rho',inf,'best_pair_margin',-inf,'best_angle_deg',NaN, ...
    'best_normal',[NaN;NaN;NaN]);
end

function S=p9cf5_normal_scan(c,cfg,obs,opt,A,b,info,meta,culprit)
% Replace ONLY the culprit active (span,obstacle) pair's p+1 rows.
% Everything else in frozen G is held fixed.
% This is diagnostic only and never changes the accepted planner.
dirs=fibonacci_sphere(opt.separator_grid_N);
S=p9cf5_empty_scan(); S.ndir=size(dirs,2);

sp=culprit.sp; o=culprit.obs;
pairRows=find([meta.sp]==sp & [meta.obs]==o);
if numel(pairRows)~=c.p+1, return; end

ua=c.spans(sp,1); ub=c.spans(sp,2);
B0=c.B0{sp}; Bz=c.Bz{sp};
um=mean([ua ub]);
a0=eval_spline(c,c.Pbase,um,2);
w0=a0+cfg.g_acc*cfg.e3;
if norm(w0)<=opt.a_net_min, nT0=cfg.e3; else, nT0=w0/norm(w0); end

bestScore=inf;
for k=1:size(dirs,2)
    n=dirs(:,k);
    rhs=obstacle_support(obs(o),n)+ ...
        delta_sep_exact(n,nT0,cfg.sys)+cfg.d_margin+opt.guide_extra;

    Ap=zeros(c.p+1,c.nz); bp=zeros(c.p+1,1);
    for j=1:c.p+1
        Ap(j,:)=-n'*Bz(:,:,j);
        bp(j)=n'*B0(:,j)-rhs;
    end

    pair_margin=min(bp - (-opt.box_z_max*sum(abs(Ap),2)));
    if pair_margin>=-1e-10, S.n_pair_reachable=S.n_pair_reachable+1; end
    S.best_pair_margin=max(S.best_pair_margin,pair_margin);

    At=A; bt=b;
    At(pairRows,:)=Ap; bt(pairRows)=bp;

    rr=p8r6_feas_online(c,At,bt,opt);
    if rr.flag>0
        S.n_global_rescue=S.n_global_rescue+1;
        rho=0;
    else
        [rho,~]=p9cf5_box_slack(c,At,bt,opt);
    end

    % Primary criterion: global common slack; secondary: pair reachability.
    score=rho - 1e-9*pair_margin;
    if score<bestScore
        bestScore=score;
        S.best_rho=rho;
        S.best_normal=n;
        d=max(-1,min(1,culprit.normal'*n));
        S.best_angle_deg=acosd(d);
    end
end
end

function r=p9cf_empty()
r=struct('case_id',0,'sys_name','','obs_name','','family','','speed',NaN, ...
 'sys_scale',[],'obs_variant',[],'T0',NaN,'classification','NOT_RUN', ...
 'probes',repmat(p9cf_probe_empty(),1,0));
end

