end

function [is,io]=p9cf_decode_case(id,nog)
is=floor((id-1)/nog)+1;
io=mod(id-1,nog)+1;
end

function obs=f9_make_multi_obstacles(obs0,nom_fun,cfg,og,id,nObs,layout,tplan,tmission)
% Explicit simultaneous multi-obstacle generator for F9-J.
% Obstacles remain oriented ellipsoids; the global certificate uses their
% exact support function.  No obstacle is replaced by a sphere.
if nObs<1, error('nObs must be >=1'); end
obs=repmat(obs0(1),1,nObs);
% Put obstacle encounters inside the remaining mission interval, with enough
% temporal spread to exercise both same-span and different-span constraints.
ta=max(tplan+5,22); tb=min(tmission-5,58);
if tb<=ta, error('Insufficient mission interval for multi-obstacle test.'); end
thit=linspace(ta,tb,nObs);
for k=1:nObs
 D=nom_fun(thit(k)); W=D(:,3)+cfg.g_acc*cfg.e3;
 if norm(W)<1e-12, nT=cfg.e3; else, nT=W/norm(W); end
 tangent=D(:,2); if norm(tangent)<1e-9, tangent=[1;0;0]; else, tangent=tangent/norm(tangent); end
 side=cross(tangent,cfg.e3); if norm(side)<1e-9, side=[1;0;0]; else, side=side/norm(side); end
 up=cross(side,tangent); if norm(up)<1e-9, up=cfg.e3; else, up=up/norm(up); end
 switch upper(layout)
  case 'SERIAL'
   off=(0.16+0.035*mod(k,3))*(-1)^k*side;
  case 'ALTERNATING'
   off=(0.18+0.025*mod(k,2))*(-1)^k*side + 0.08*(-1)^(floor((k-1)/2))*up;
  case 'NARROW_3D'
   % Alternating lateral/vertical offsets form a 3-D constrained passage.
   off=0.13*(-1)^k*side + 0.12*(-1)^(mod(k,2)+floor((k-1)/2))*up;
  case 'CLUSTERED'
   % Compress hit times/centers so several obstacles can constrain nearby spans.
   tc=0.5*(ta+tb)+0.75*(k-(nObs+1)/2); D=nom_fun(tc);
   W=D(:,3)+cfg.g_acc*cfg.e3; if norm(W)<1e-12,nT=cfg.e3;else,nT=W/norm(W);end
   tangent=D(:,2); if norm(tangent)<1e-9,tangent=[1;0;0];else,tangent=tangent/norm(tangent);end
   side=cross(tangent,cfg.e3); if norm(side)<1e-9,side=[1;0;0];else,side=side/norm(side);end
   up=cross(side,tangent); if norm(up)<1e-9,up=cfg.e3;else,up=up/norm(up);end
   off=0.17*cos(2*pi*(k-1)/max(3,nObs))*side + 0.12*sin(2*pi*(k-1)/max(3,nObs))*up;
  otherwise, error('Unknown multi-obstacle layout: %s',layout);
 end
 obs(k).center=D(:,1)+cfg.sys.L_cable*nT+off;
 base=[1.10;.90;1.20];
 localScale=og(1)*(0.90+0.05*mod(k+id,3));
 anis=og(2:4)'.*[1+0.06*sin(k);1+0.05*cos(2*k);1+0.04*sin(3*k)];
 obs(k).radii=localScale*(base.*anis);
 ang=(og(5:7)+[19*k -13*k 29*k]+mod(id,17)*[1 -0.5 0.75])*pi/180;
 obs(k).R=eul2rotm_local(ang); obs(k).S=obs(k).R*diag(obs(k).radii.^2)*obs(k).R';
end
end

function obs=p9cf_make_obstacles(obs0,nom_fun,cfg,og,id)
% Exact Phase-9C deterministic obstacle construction.
obs=repmat(obs0(1),1,2);
thit=[31 43];
for k=1:2
    D=nom_fun(thit(k)); W=D(:,3)+cfg.g_acc*cfg.e3;
    if norm(W)<1e-12, nT=cfg.e3; else, nT=W/norm(W); end
    tangent=D(:,2);
    if norm(tangent)<1e-9, tangent=[1;0;0]; else, tangent=tangent/norm(tangent); end
    side=cross(tangent,cfg.e3);
    if norm(side)<1e-9, side=[1;0;0]; else, side=side/norm(side); end
    sg=(-1)^k;
    obs(k).center=D(:,1)+cfg.sys.L_cable*nT+sg*(.20+.08*k)*side;
    base=[1.10;.90;1.20];
    obs(k).radii=og(1)*(base.*og(2:4)');
    ang=(og(5:7)+[17*k -11*k 23*k])*pi/180;
    obs(k).R=eul2rotm_local(ang);
    obs(k).S=obs(k).R*diag(obs(k).radii.^2)*obs(k).R';
end
end

function [ok,z,ef]=p9cf_feas(A,b,nz)
% Diagnostic feasibility solve only; same tiny-norm objective as frozen P8R6.
H=1e-10*eye(nz); f=zeros(nz,1);
opts=optimoptions('quadprog','Display','off');
[z,~,ef]=quadprog(H,f,A,b,[],[],[],[],[],opts);
ok=(ef>0) && all(isfinite(z));
if ~ok, z=zeros(nz,1); end
end

function cls=p9cf_classify(P,recovered)
valid=~isnan([P.T]);
P=P(valid);
if isempty(P), cls='UNRESOLVED'; return; end
if recovered
    cls='RECOVERED_BY_TIME'; return;
end
G=[P.G]; D=[P.D]; GD=[P.GD]; C=[P.C];
if all(D) && ~any(G)
    cls='CORRIDOR_GEOMETRY_INFEASIBLE';
elseif any(G) && ~any(D)
    cls='DYNAMIC_LIMITED';
elseif any(GD) && ~any(C)
    cls='VERIFIER_INCOMPATIBLE';
elseif any(G) && any(D) && ~any(GD)
    cls='COMBINED_COUPLING_INFEASIBLE';
elseif ~any(G) && ~any(D)
    cls='GEOMETRY_AND_DYNAMICS_INFEASIBLE';
else
    cls='UNRESOLVED';
end
end

function a=p9cf_temporal_jump(info)
% Actual 9A-G info.normal is stored per obstacle; normalize access here.
a=0;
if ~isfield(info,'normal') || ~isfield(info,'active'), a=NaN; return; end
A=info.active;
[nsp,nobs]=size(A);
for o=1:nobs
    ids=find(A(:,o));
    for k=2:numel(ids)
        if ids(k)~=ids(k-1)+1, continue; end
        n1=p9cf_get_normal(info,ids(k-1),o,nsp,nobs);
        n2=p9cf_get_normal(info,ids(k),o,nsp,nobs);
        if all(isfinite(n1)) && all(isfinite(n2)) && norm(n1)>0 && norm(n2)>0
            a=max(a,acosd(max(-1,min(1,dot(n1,n2)/(norm(n1)*norm(n2))))));
        end
    end
end
end

function a=p9cf_cross_angle(info)
a=0;
if ~isfield(info,'normal') || ~isfield(info,'active'), a=NaN; return; end
A=info.active; [nsp,nobs]=size(A);
for sp=1:nsp
    ids=find(A(sp,:));
    for i=1:numel(ids)
      for j=i+1:numel(ids)
        n1=p9cf_get_normal(info,sp,ids(i),nsp,nobs);
        n2=p9cf_get_normal(info,sp,ids(j),nsp,nobs);
        if all(isfinite(n1)) && all(isfinite(n2)) && norm(n1)>0 && norm(n2)>0
          a=max(a,acosd(max(-1,min(1,dot(n1,n2)/(norm(n1)*norm(n2))))));
        end
      end
    end
end
end

function m=p9cf_multi_active(info)
if ~isfield(info,'active'), m=0; return; end
m=nnz(sum(info.active,2)>=2);
end

function n=p9cf_get_normal(info,sp,o,nsp,nobs)
% Normalize all layouts used by the frozen corridor helper:
%   cell{obstacle}: nsp x 3   (actual 9A-G layout)
%   numeric nsp x 3 x nobs
%   numeric 3 x nsp x nobs
%   numeric nsp x nobs x 3
N=info.normal; n=[NaN;NaN;NaN];
if iscell(N)
    if o<=numel(N) && ~isempty(N{o})
        X=N{o};
        if size(X,1)>=sp && size(X,2)==3, n=X(sp,:)';
        elseif size(X,2)>=sp && size(X,1)==3, n=X(:,sp);
        end
    end
    return;
end
sz=size(N);
if ndims(N)==2
    if nobs==1
        if size(N,1)>=sp && size(N,2)==3, n=N(sp,:)';
        elseif size(N,2)>=sp && size(N,1)==3, n=N(:,sp);
        end
    end
elseif ndims(N)>=3
    if sz(1)>=nsp && sz(2)==3 && sz(3)>=o
        n=squeeze(N(sp,:,o));
    elseif sz(1)==3 && sz(2)>=nsp && sz(3)>=o
        n=squeeze(N(:,sp,o));
    elseif sz(1)>=nsp && sz(2)>=nobs && sz(3)==3
        n=squeeze(N(sp,o,:));
    end
end
n=n(:);
if numel(n)~=3, n=[NaN;NaN;NaN]; end
end

function p9cf_runtime_smoke(cfg,limits,obs,opt,alpha)
nom=@(t) p9a_nominal(t,'STRAIGHT',1.0);
t0=20; T=10;
D0=nom(t0); D1=nom(t0+T);
c=build_static_cache_boundary(cfg,t0,t0+T,nom,D0,D1,opt);
md=build_dyn_E(c);
[Dmat,dvec]=dyn_E(md,limits,alpha); %#ok<NASGU>
[Gmat,gvec,~]=build_coherent_guided_corridor(c,cfg,obs,opt); %#ok<NASGU>
z=zeros(c.nz,1);
P=apply_z(c,z);
cert=certify_candidate_global(P,c,cfg,limits,obs,opt);
assert(isfield(cert,'pass') && isfield(cert,'min_g_lower') && ...
       isfield(cert,'v_bound') && isfield(cert,'a_bound') && isfield(cert,'j_bound'), ...
       'Phase9CFR5:BadCertificateSchema','Unexpected certificate schema.');
f101aa_silent_fprintf('FR5 RUNTIME SMOKE PASS: frozen helper chain executed successfully.\n');
end

function p9cf_preflight(cfg,limits,opt)
reqOpt={'separator_grid_N','a_net_min','c6_tol','cert_tol', ...
        'coherent_lambda','coherent_flip_cos','coherent_topK', ...
        'compat_enable','compat_min_dot','compat_lambda', ...
        'geom_guide_enable','geom_guide_lambda','geom_guide_min_dot'};
for k=1:numel(reqOpt)
    assert(isfield(opt,reqOpt{k}),'Phase9CFR5:MissingOption', ...
        'Missing opt.%s',reqOpt{k});
end
reqSys={'L_cable','R_payload','R_cable','R_uav'};
for k=1:numel(reqSys)
    assert(isfield(cfg.sys,reqSys{k}),'Phase9CFR5:MissingSystemField', ...
        'Missing cfg.sys.%s',reqSys{k});
end
reqLim={'v_max','a_max','j_max'};
for k=1:numel(reqLim)
    assert(isfield(limits,reqLim{k}),'Phase9CFR5:MissingLimitField', ...
        'Missing limits.%s',reqLim{k});
end
D=fibonacci_sphere(opt.separator_grid_N);
assert(isnumeric(D) && size(D,1)==3 && size(D,2)==opt.separator_grid_N, ...
    'Phase9CFR5:BadDirectionGrid','Bad fibonacci_sphere output.');
f101aa_silent_fprintf('FR5 PREFLIGHT PASS: schema/helper checks OK.\n');
end

function [np,nq,nc,qmin,qmax]=p9cf_support_dominance(c,P,cfg,opt)
% Diagnostic support dominance using ONLY the frozen source's own evaluator.
% eval_spline(c,P,u,r) is defined later in this same file.
tt=linspace(0,1,161);
np=0; nq=0; nc=0; qmin=inf; qmax=-inf;
dirs=fibonacci_sphere(opt.separator_grid_N);
if size(dirs,1)~=3, dirs=dirs'; end
for k=1:numel(tt)
    aL=eval_spline(c,P,tt(k),2);
    W=aL+cfg.g_acc*cfg.e3;
    if norm(W)<=opt.a_net_min, nT=cfg.e3; else, nT=W/norm(W); end
    for j=1:size(dirs,2)
        n=dirs(:,j); n=n/norm(n); q=dot(n,nT);
        qmin=min(qmin,q); qmax=max(qmax,q);
        v=[cfg.sys.R_payload; ...
           cfg.sys.L_cable*q+cfg.sys.R_uav; ...
           max(0,cfg.sys.L_cable*q)+cfg.sys.R_cable];
        [~,ii]=max(v);
        if ii==1, np=np+1;
        elseif ii==2, nq=nq+1;
        else, nc=nc+1;
        end
    end
end
if ~isfinite(qmin), qmin=NaN; qmax=NaN; end
end

function r=p9c_empty()
